import {useEffect, useState} from "react";
import {getSchedule} from "../../handlers/schedulehandler";
import ProgressRing from "../ProgressRing";
import MessageBar from "../MessageBar";
import ScheduleItem from "./ScheduleItem";
import {
    fetchBoatsFromDatabase,
    fetchCategoriesFromDatabase,
    fetchDistancesFromDatabase,
    fetchGendersFromDatabase,
    fetchRegistrationsFromDatabase
} from "../../handlers/databasehandler";
import {Button, Popover, PopoverSurface, PopoverTrigger} from "@fluentui/react-components";
import {
    Add16Regular, ArrowBidirectionalUpDown16Regular,
    ArrowClockwise16Regular, ArrowDownload16Filled, ContentView16Filled,
    MoreHorizontal16Regular,
    Sparkle16Filled, TextBulletList16Regular,
    Trophy16Filled
} from "@fluentui/react-icons";
import UpdateScheduleDialog from "./UpdateScheduleDialog";
import {fetchEventById} from "../../handlers/eventhandler";
import {fetchAllRegistrations} from "../../handlers/registrationhandler";
import GenerateRacesDialog from "./GenerateRacesDialog";
import GenerateFinalsDialog from "./GenerateFinalsDialog";
import {generateHanzebokaal, generateHzBokaalPDF} from "../../handlers/hanzebokaalhandler";
import * as React from "react";
import MoveScheduleItemDialog from "./MoveScheduleItemDialog";
import {DownloadOptions} from "../../enums/downloadOptions";
import {generateScheduleDetailedPdf, generateScheduleTitleOverviewPdf} from "../../handlers/schedulepdfhandler";
import {generateScheduleDetailedCsv, generateScheduleTitleOverviewCsv} from "../../handlers/schedulecsvhandler";

const AllScheduleItemsView = ({eventId}) => {
    const [scheduleData, setScheduleData] = useState({});
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [distances, setDistances] = useState([]);
    const [genders, setGenders] = useState([]);
    const [categories, setCategories] = useState([]);
    const [boats, setBoats] = useState([]);
    const [registrations, setRegistrations] = useState([]);
    const [lastRaceNR, setLastRaceNR] = useState(0);
    const [eventData, setEventData] = useState({});

    async function fetchGenders() {
        return await fetchGendersFromDatabase(eventId);
    }

    async function fetchCategories() {
        return await fetchCategoriesFromDatabase(eventId);
    }

    async function fetchBoats() {
        return await fetchBoatsFromDatabase(eventId);
    }

    async function fetchDistances() {
        return await fetchDistancesFromDatabase(eventId);
    }

    async function fetchRegistrations() {
        return await fetchAllRegistrations(eventId);
    }

    function loadAllSettings() {
        fetchEventById(eventId).then((data) => setEventData(data));
        fetchGenders().then((data) => {
            if(!data) {
                return;
            }

            setGenders(data);
        });
        fetchCategories().then((data) => {
            if (!data) {
                return;
            }

            setCategories(data);
        });
        fetchBoats().then((data) => {
            if (!data) {
                return;
            }

            setBoats(data);
        });
        fetchDistances().then((data) => {
            if (!data) {
                return;
            }

            setDistances(data);
        });
        fetchRegistrations().then((data) => {
            if (!data) {
                return;
            }

            setRegistrations(data);
        });
    }

    function fetchScheduleAfterUpdate() {
        getSchedule(eventId).then((data) => {
            if (!data) {
                setError(`An error occurred fetching schedule data`);
                return;
            }

            setLastRaceNR(data.slice(-1)[0]?.race_nr || 0);
            setScheduleData(data);
        });
    }

    function getNewDateTimeForSchedule(index) {
        if ((!index && index !== 0) || scheduleData?.length < index) {
            return new Date();
        }

        if (index === 0) {
            let eventStartDate = new Date(eventData?.startDate);

            if (isNaN(eventStartDate.getTime())) {
                return new Date();
            }

            eventStartDate.setHours(8, 0, 0, 0);

            return eventStartDate;
        }

        if (index === 1) {
            const prevStartTime = new Date(scheduleData[0].planned_start_time);
            return prevStartTime.setMinutes(prevStartTime.getMinutes() + 5);
        }

        let prevScheduleItem1Date = new Date(scheduleData[index - 1].planned_start_time);
        const prevScheduleItem2Date = new Date(scheduleData[index - 2].planned_start_time);

        const dateTimeDifference = prevScheduleItem1Date - prevScheduleItem2Date;

        prevScheduleItem1Date.setTime(prevScheduleItem1Date.getTime() + dateTimeDifference);
        return prevScheduleItem1Date;
    }

    const generateHanzebokaalClicked = () => {
        const result = generateHanzebokaal(scheduleData);

        if (!result) {
            setError("Failed to generate Hanzebokaal");
            return;
        }

        generateHzBokaalPDF(result).then(r => {/*ignored*/});
    }

    const downloadPDF = (option) => {
        if (!option) {
            return;
        }

        switch (option) {
            case DownloadOptions.SCHEDULE_FULL_EXPORT:
                generateScheduleDetailedPdf(scheduleData).then((r) => {/*ignored*/});
                break;

            case DownloadOptions.SCHEDULE_TITLE_EXPORT:
                generateScheduleTitleOverviewPdf(scheduleData).then((r) => {/*ignored*/});
                break;

            case DownloadOptions.SCHEDULE_FULL_EXPORT_CSV:
                generateScheduleDetailedCsv(scheduleData).then((r) => {/*ignored*/});
                break;

            case DownloadOptions.SCHEDULE_TITLE_EXPORT_CSV:
                generateScheduleTitleOverviewCsv(scheduleData).then((r) => {/*ignored*/});
                break;

            default:
                break;
        }
    }

    useEffect(() => {
        setIsLoading(true);
        getSchedule(eventId).then((data) => {
            setIsLoading(false);

            if (!data) {
                setScheduleData([]);
                setError(`An error occurred while fetching schedule data`);
                return;
            }

            setLastRaceNR(data.slice(-1)[0]?.race_nr || 0);
            setScheduleData(data);
            setError(null);
        });

        loadAllSettings();
    }, []);

    return (
        <>
            { isLoading &&
                <>
                    <ProgressRing/>
                </>
            }
            { !isLoading && error &&
                <>
                    <MessageBar title={error} intent={`error`} closeButtonFunction={ () => setError(null) } />
                </>
            }
            { !isLoading && scheduleData &&
                <>
                    {
                        scheduleData.map((scheduleItem, index) => {
                            return (
                                <ScheduleItem
                                    boats={boats}
                                    genders={genders}
                                    categories={categories}
                                    distances={distances}
                                    scheduleItem={scheduleItem}
                                    registrations={registrations}
                                    onUpdate={() => fetchScheduleAfterUpdate()}
                                    key={index} />
                            );
                        })
                    }
                    <div className={`pos-sticky pos-bottom flex flex-justify-center width-100 mt-medium`}>
                        <div className={`flex flex-gap-medium flex-wrap actions-container`}>
                            <UpdateScheduleDialog
                                key={lastRaceNR + 1}
                                isNew={true}
                                onUpdate={() => fetchScheduleAfterUpdate()}
                                button={
                                    <Button as={`a`} className={`button`} appearance={`primary`}>
                                        <Add16Regular/>
                                        Add Race
                                    </Button>
                                }
                                newStartTime={getNewDateTimeForSchedule(scheduleData?.length)}
                                availableDistances={distances}
                                availableBoats={boats}
                                availableCategories={categories}
                                availableGenders={genders}
                                eventId={eventId}
                                raceNR={parseInt(lastRaceNR.toString()) + 1}
                            />
                            <GenerateRacesDialog
                                key={`generate-${lastRaceNR}`}
                                eventId={eventId}
                                availableDistances={distances}
                                availableBoats={boats}
                                availableCategories={categories}
                                availableGenders={genders}
                                registrations={registrations}
                                scheduleData={Array.isArray(scheduleData) ? scheduleData : []}
                                lastRaceNR={lastRaceNR}
                                newStartTime={getNewDateTimeForSchedule(scheduleData?.length)}
                                onUpdate={() => fetchScheduleAfterUpdate()}
                                button={
                                    <Button as={`a`} className={`button`}>
                                        <Sparkle16Filled/>
                                        Generate
                                    </Button>
                                }
                            />
                            <GenerateFinalsDialog
                                key={`finals-${lastRaceNR}`}
                                eventId={eventId}
                                scheduleData={Array.isArray(scheduleData) ? scheduleData : []}
                                onUpdate={() => fetchScheduleAfterUpdate()}
                                button={
                                    <Button as={`a`} className={`button`}>
                                        <Trophy16Filled/>
                                        Finals
                                    </Button>
                                }
                            />

                            <Button as={`a`} className={`button`} onClick={() => fetchScheduleAfterUpdate()}>
                                <ArrowClockwise16Regular/> Reload
                            </Button>
                            <Popover>
                                <PopoverTrigger>
                                    <Button as={`a`} className={`button`}>
                                        <MoreHorizontal16Regular /> More
                                    </Button>
                                </PopoverTrigger>
                                <PopoverSurface className={`dialog`}>
                                    <div className={`flex flex-column flex-gap-small`}>
                                        <MoveScheduleItemDialog
                                            scheduleData={scheduleData}
                                            eventId={eventId}
                                            afterUpdate={() => fetchScheduleAfterUpdate()}
                                            button={
                                                <Button as={`a`} className={`button`}>
                                                    <ArrowBidirectionalUpDown16Regular /> Move
                                                </Button>
                                            }
                                        />
                                        <Button as={`a`} className={`button`} onClick={() => generateHanzebokaalClicked()}>
                                            <Trophy16Filled/> Hanzebokaal
                                        </Button>
                                        <Button as={`a`} className={`button`} onClick={() => downloadPDF(DownloadOptions.SCHEDULE_FULL_EXPORT)}>
                                            <ArrowDownload16Filled /> {DownloadOptions.SCHEDULE_FULL_EXPORT}
                                        </Button>
                                        <Button as={`a`} className={`button`} onClick={() => downloadPDF(DownloadOptions.SCHEDULE_FULL_EXPORT_CSV)}>
                                            <ArrowDownload16Filled /> {DownloadOptions.SCHEDULE_FULL_EXPORT_CSV}
                                        </Button>
                                        <Button as={`a`} className={`button`} onClick={() => downloadPDF(DownloadOptions.SCHEDULE_TITLE_EXPORT)}>
                                            <ArrowDownload16Filled /> {DownloadOptions.SCHEDULE_TITLE_EXPORT}
                                        </Button>
                                        <Button as={`a`} className={`button`} onClick={() => downloadPDF(DownloadOptions.SCHEDULE_TITLE_EXPORT_CSV)}>
                                            <ArrowDownload16Filled /> {DownloadOptions.SCHEDULE_TITLE_EXPORT_CSV}
                                        </Button>
                                    </div>
                                </PopoverSurface>
                            </Popover>
                        </div>
                    </div>
                </>
            }
        </>
    )
}

export default AllScheduleItemsView;