import {useState} from "react";
import {addCategoryToDatabase, updateCategoryFromDatabase} from "../../../handlers/databasehandler";
import {Add12Regular} from "@fluentui/react-icons";
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger, Input, Label
} from "@fluentui/react-components";

const ChangeRegistrationCategoryDialog = ({eventId, category, onUpdate, isNew = false, altButton = null}) => {
    const [categoryText, setCategoryText] = useState(isNew ? "" : category.category);

    async function updateCategory() {
        updateCategoryFromDatabase(eventId, category.id, categoryText).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    async function addCategory() {
        addCategoryToDatabase(eventId, categoryText).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    return (
        <>
            <Dialog>
                <DialogTrigger>
                    { altButton ? altButton : <Button as={"a"} className={`button`}  appearance={"primary"}>{ isNew ? <><Add12Regular/> Toevoegen</> : <>Wijzigen</> }</Button> }
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>{ isNew ? <>Category Toevoegen</> : <>{category.category} wijzigen</>}</DialogTitle>
                    <DialogContent>
                        <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 12, marginTop: 12 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <Label style={{ width: 150 }}>Category:</Label>
                                <Input
                                    value={categoryText}
                                    onChange={(e) => setCategoryText(e.target.value)}
                                    style={{ flex: 1 }}/>
                            </div>
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button as={"a"} className={`button`} appearance="secondary">Annuleren</Button>
                        </DialogTrigger>
                        <DialogTrigger>
                            <Button as={"a"} className={`button`} appearance="primary" onClick={isNew ? addCategory : updateCategory}>
                                { isNew ? <>Toevoegen</> : <>Wijzigen</> }
                            </Button>
                        </DialogTrigger>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
}

export default ChangeRegistrationCategoryDialog;