import {
    Button,
    Combobox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger,
    Input,
    Label,
    Option,
} from "@fluentui/react-components";
import {useState} from "react";
import MessageBox from "../MessageBar";
import ProgressRing from "../ProgressRing";
import DistanceSchedule from "../../models/DistanceSchedule";
import Distance from "../../models/Distance";
import {addRaceFromSchedule, getParticipantsForSchedule} from "../../handlers/schedulehandler";
import {formatDateForInput} from "../../handlers/datehandler";

/**
 * Randomly shuffles an array (Fisher-Yates).
 */
function shuffleArray(array) {
    const arr = [...array];
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

/**
 * Splits participants into race groups based on lane count.
 * Distributes as evenly as possible across races.
 * Every race always has exactly `lanes` slots; participants are placed in the
 * center lanes, with empty slots padded symmetrically on the outside.
 *
 * Example: 16 participants, 6 lanes → 3 races of 6 slots
 *   Race 1: 6 filled  → start_nrs 1-6 (all filled)
 *   Race 2: 5 filled  → start_nrs 1(empty), 2-6 (filled) or similar centering
 *   Race 3: 5 filled  → center-aligned
 *
 * Returns an array of lane arrays, where each lane is either a participant
 * object or null (empty lane).
 */
function distributeParticipants(participants, lanes) {
    const total = participants.length;
    const raceCount = Math.ceil(total / lanes);
    const baseSize = Math.floor(total / raceCount);
    const remainder = total % raceCount;

    const groups = [];
    let offset = 0;

    for (let i = 0; i < raceCount; i++) {
        const size = i < raceCount - 1 ? baseSize : baseSize + remainder;
        const group = participants.slice(offset, offset + size);
        offset += size;

        // Build a lanes-sized array with nulls, then fill participants into center
        const laneSlots = Array(lanes).fill(null);
        const startIndex = Math.floor((lanes - group.length) / 2);
        group.forEach((participant, idx) => {
            laneSlots[startIndex + idx] = participant;
        });

        groups.push(laneSlots);
    }

    return groups;
}

const GenerateRacesDialog = ({
                                 button,
                                 eventId,
                                 availableDistances = [],
                                 availableBoats = [],
                                 availableCategories = [],
                                 availableGenders = [],
                                 registrations = [],
                                 scheduleData = [],
                                 lastRaceNR = 0,
                                 newStartTime = new Date(),
                                 onUpdate,
                             }) => {
    const initialDate = new Date(newStartTime);

    const [open, setOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [errorMsg, setErrorMsg] = useState(null);

    const [selectedDistance, setSelectedDistance] = useState(null);
    const [selectedBoat, setSelectedBoat] = useState(null);
    const [selectedGender, setSelectedGender] = useState(null);
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [startTime, setStartTime] = useState(initialDate);
    const [lanes, setLanes] = useState(6);

    function resetState() {
        setSelectedDistance(null);
        setSelectedBoat(null);
        setSelectedGender(null);
        setSelectedCategory(null);
        setStartTime(new Date(newStartTime));
        setLanes(6);
        setErrorMsg(null);
    }

    function onDialogOpenChange(e, data) {
        setOpen(data.open);
        if (!data.open) {
            resetState();
        }
    }

    // ── Distance field helpers (mirrors UpdateScheduleDialog) ──────────────
    function setSelectedDistanceField(value) {
        if (value instanceof DistanceSchedule) {
            setSelectedDistance(value);
        } else if (value instanceof Distance) {
            setSelectedDistance(value);
            setSelectedBoat(value.Boat ?? null);
            setSelectedGender(value.Gender ?? null);
            setSelectedCategory(value.Categories ?? null);
        } else {
            setSelectedDistance(new DistanceSchedule(-1, value));
        }
    }

    function getDistanceText(distance) {
        if (!distance || !(distance instanceof Distance)) {
            return distance?.text?.length ? distance.text : distance;
        }
        return `${distance.distance} (${distance.Boat?.boat} - ${distance.Gender?.gender} - ${distance.Categories?.category})`;
    }

    // ── Lane input ─────────────────────────────────────────────────────────
    function setLanesField(value) {
        const parsed = parseInt(value);
        if (isNaN(parsed) || parsed < 1) {
            setErrorMsg("Lanes must be a positive number");
            return;
        }
        setErrorMsg(null);
        setLanes(parsed);
    }

    // ── Derive a clone scheduleItem from current selections so we can reuse
    //    getParticipantsForSchedule, which filters registrations by matching
    //    boat / gender / category / distance ─────────────────────────────────
    function buildScheduleItemClone() {
        return {
            id: null,
            distance: selectedDistance,
            boat: selectedBoat,
            gender: selectedGender,
            category: selectedCategory,
            participants: [],
        };
    }

    // ── Generate races ─────────────────────────────────────────────────────
    async function generateRaces() {
        if (!eventId) {
            setErrorMsg("An unexpected error occurred.");
            return;
        }

        if (!selectedDistance) {
            setErrorMsg("Please select a distance / race type.");
            return;
        }

        if (!lanes || lanes < 1) {
            setErrorMsg("Please enter a valid number of lanes.");
            return;
        }

        const scheduleItemClone = buildScheduleItemClone();

        const allParticipants = getParticipantsForSchedule(registrations, scheduleItemClone);

        if (allParticipants.length === 0) {
            setErrorMsg("No registered participants found for the selected race type.");
            return;
        }

        const shuffled = shuffleArray(allParticipants);
        const groups = distributeParticipants(shuffled, lanes);

        setIsLoading(true);

        try {
            let currentRaceNR = parseInt(lastRaceNR.toString()) + 1;
            let currentStartTime = new Date(startTime);

            // Calculate interval between existing races to space the new ones
            let intervalMs = 5 * 60 * 1000; // default 5 minutes
            if (scheduleData.length >= 2) {
                const last = new Date(scheduleData[scheduleData.length - 1].planned_start_time);
                const secondLast = new Date(scheduleData[scheduleData.length - 2].planned_start_time);
                const diff = last - secondLast;
                if (diff > 0) intervalMs = diff;
            }

            for (let i = 0; i < groups.length; i++) {
                const laneSlots = groups[i]; // array of `lanes` slots, nulls are empty lanes

                const participants = laneSlots.map((participant, idx) => ({
                    start_nr: idx + 1,
                    participants: participant ? participant.participants : [],
                }));

                const raceStartTime = new Date(currentStartTime.getTime() + i * intervalMs);

                const scheduleItemToAdd = {
                    updated_at: new Date().toISOString(),
                    event_id: eventId,
                    race_nr: currentRaceNR,
                    planned_start_time: raceStartTime,
                    distance: selectedDistance,
                    category: selectedCategory,
                    gender: selectedGender,
                    boat: selectedBoat,
                    participants,
                    race_type: groups.length > 1 ? `Serie` : `Finale`
                };

                const result = await addRaceFromSchedule(eventId, scheduleItemToAdd);

                if (!result) {
                    setErrorMsg(`Error saving race ${currentRaceNR}`);
                    setIsLoading(false);
                    return;
                }

                currentRaceNR++;
            }

            setIsLoading(false);

            if (onUpdate) {
                onUpdate();
            }

            setOpen(false);
        } catch (err) {
            setIsLoading(false);
            setErrorMsg("An unexpected error occurred while generating races.");
        }
    }

    // ── Participant preview ────────────────────────────────────────────────
    function getParticipantCount() {
        if (!selectedDistance) return null;
        const scheduleItemClone = buildScheduleItemClone();
        const matching = getParticipantsForSchedule(registrations, scheduleItemClone);
        return matching.length;
    }

    function getRaceCount() {
        const count = getParticipantCount();
        if (!count || !lanes || lanes < 1) return null;
        return Math.ceil(count / lanes);
    }

    const participantCount = getParticipantCount();
    const raceCount = getRaceCount();

    return (
        <>
            <Dialog open={open} onOpenChange={onDialogOpenChange}>
                <DialogTrigger>
                    {button}
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>
                        Generate Races
                    </DialogTitle>
                    <DialogContent>
                        {errorMsg && <MessageBox title={errorMsg} intent={"error"} />}
                        <div className={`dialog-content-container`}>
                            <div className={`dialog-content-item`}>
                                <Label>Start time:</Label>
                                <Input
                                    id="generate-start-time-picker"
                                    type="datetime-local"
                                    value={formatDateForInput(startTime)}
                                    onChange={(e, data) => {
                                        setStartTime(new Date(data.value));
                                    }}
                                />
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Race:</Label>
                                <Combobox
                                    value={getDistanceText(selectedDistance) ?? ""}
                                    onOptionSelect={(e, data) => setSelectedDistanceField(data.optionValue)}
                                    onInput={(e) => setSelectedDistanceField(e.target.value)}
                                    placeholder={`Select Races`}
                                    freeform
                                    autocomplete
                                >
                                    {Array.from(availableDistances).map((distance) => (
                                        <Option key={distance.id} value={distance}>
                                            {getDistanceText(distance)}
                                        </Option>
                                    ))}
                                </Combobox>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Number of lanes:</Label>
                                <Input
                                    type={`number`}
                                    value={lanes}
                                    min={1}
                                    onInput={(e) => setLanesField(e.target.value)}
                                    placeholder={`Lanes`}
                                />
                            </div>
                            {participantCount !== null && (
                                <div className={`dialog-content-item`}>
                                    <Label>Preview:</Label>
                                    <span>
                                        {participantCount} participant{participantCount !== 1 ? "s" : ""} →{" "}
                                        {raceCount} race{raceCount !== 1 ? "s" : ""} of max {lanes} lane{lanes !== 1 ? "s" : ""}
                                        , starting at race nr {parseInt(lastRaceNR.toString()) + 1}
                                    </span>
                                </div>
                            )}
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button className={`button`} as={"a"} appearance="secondary">
                                Cancel
                            </Button>
                        </DialogTrigger>
                        <Button
                            as={"a"}
                            className={`button`}
                            appearance="primary"
                            disabled={!!errorMsg || isLoading}
                            onClick={generateRaces}
                        >
                            {isLoading && <ProgressRing />}
                            {!isLoading && `Generate`}
                        </Button>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
};

export default GenerateRacesDialog;
