import { useParams } from "react-router-dom";
import { useEffect, useState, useMemo } from "react";
import {
    deleteDistanceFromDatabase, fetchBoatsFromDatabase, fetchCategoriesFromDatabase,
    fetchDistancesFromDatabase, fetchDistancesFromDatabaseForExport,
    fetchGendersFromDatabase
} from "../../../handlers/databasehandler";
import {
    Button, Table, TableBody, TableHeader,
    TableHeaderCell, TableRow, TableCell, Dropdown, Option
} from "@fluentui/react-components";
import ProgressRing from "../../ProgressRing";
import MessageBox from "../../MessageBar";
import * as React from "react";
import ChangeRegistrationDistanceDialog from "./ChangeRegistrationDistanceDialog";
import {
    ArrowClockwise16Regular, ArrowDownload16Regular,
    Copy16Filled,
    Delete16Filled,
    Edit16Filled,
} from "@fluentui/react-icons";
import MenuToolbar from "../../MenuToolbar";
import InnerBodyContainer from "../../InnerBodyContainer";
import ConfirmDialog from "../../ConfirmDialog";
import {downloadFile} from "../../../handlers/downloadhandler";

const RegistrationDistanceView = () => {
    const { id } = useParams();
    const [isLoading, setIsLoading] = useState(true);
    const [distances, setDistances] = useState([]);
    const [genders, setGenders] = useState([]);
    const [categories, setCategories] = useState([]);
    const [boats, setBoats] = useState([]);
    const [errorMsg, setErrorMsg] = useState(null);

    // Filter States
    const [selectedGenderId, setSelectedGenderId] = useState("all");
    const [selectedCategoryId, setSelectedCategoryId] = useState("all");
    const [selectedBoatId, setSelectedBoatId] = useState("all");

    const reloadAllSettings = async () => {
        setIsLoading(true);
        try {
            const [g, c, b, d] = await Promise.all([
                fetchGendersFromDatabase(id),
                fetchCategoriesFromDatabase(id),
                fetchBoatsFromDatabase(id),
                fetchDistancesFromDatabase(id)
            ]);
            setGenders(g || []);
            setCategories(c || []);
            setBoats(b || []);
            setDistances(d || []);
        } catch (e) {
            setErrorMsg("Error reloading data");
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        reloadAllSettings().then((r) => { /*ignored*/ });
    }, []);

    const deleteDistances = async (distanceId) => {
        const result = await deleteDistanceFromDatabase(id, distanceId);
        if (!result) {
            setErrorMsg("Error deleting distance.");
            return;
        }
        const updated = await fetchDistancesFromDatabase(id);
        setDistances(updated);
    };

    const filteredDistances = useMemo(() => {
        return distances.filter(d => {
            const matchGender = selectedGenderId === "all" || d.Gender?.id === selectedGenderId;
            const matchCategory = selectedCategoryId === "all" || d.Categories?.id === selectedCategoryId;
            const matchBoat = selectedBoatId === "all" || d.Boat?.id === selectedBoatId;
            return matchGender && matchCategory && matchBoat;
        });
    }, [distances, selectedGenderId, selectedCategoryId, selectedBoatId]);

    const DistanceTableColumns = [
        { columnKey: "gender", label: "Gender", span: 3 },
        { columnKey: "category", label: "Category", span: 3 },
        { columnKey: "boat", label: "Boat", span: 2 },
        { columnKey: "distance", label: "Distance", span: 3 },
        { columnKey: "actions", label: "Actions", span: 1 },
    ];

    const getWidthForColumnForDistance = (columnKey) => {
        const column = DistanceTableColumns.find(col => col.columnKey === columnKey);
        if (column) {
            return `${(column.span / 12) * 100}%`;
        }
        return 'auto';
    };

    const downloadDistances = async () => {
        const csvValue = await fetchDistancesFromDatabaseForExport(id);
        if (!csvValue) {
            setErrorMsg("Error downloading Club with registrations");
            return;
        }
        const csvData = new Blob([csvValue], {type: 'text/csv'});

        const fileName = `Distances_${Date.now()}`;
        downloadFile(csvData, fileName);
    }

    return (
        <InnerBodyContainer content={
            <>
                <MenuToolbar content={
                    <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
                        <Button as={`a`} className={`button`} appearance={"secondary"} onClick={reloadAllSettings} >
                            <ArrowClockwise16Regular/> Reload
                        </Button>

                        <Dropdown
                            className={`dropdown`}
                            placeholder="All Genders"
                            onOptionSelect={(_, data) => setSelectedGenderId(data.selectedOptions[0])}
                        >
                            <Option key="all" value="all">All Genders</Option>
                            {genders.map(g => <Option key={g.id} value={g.id}>{g.gender}</Option>)}
                        </Dropdown>
                        <Dropdown
                            placeholder="All Categories"
                            onOptionSelect={(_, data) => setSelectedCategoryId(data.selectedOptions[0])}
                        >
                            <Option key="all" value="all">All Categories</Option>
                            {categories.map(c => <Option key={c.id} value={c.id}>{c.category}</Option>)}
                        </Dropdown>

                        <Dropdown
                            placeholder="All Boats"
                            onOptionSelect={(_, data) => setSelectedBoatId(data.selectedOptions[0])}
                        >
                            <Option key="all" value="all">All Boats</Option>
                            {boats.map(b => <Option key={b.id} value={b.id}>{b.boat}</Option>)}
                        </Dropdown>

                        <Button as={`a`} className={`button`} appearance={"secondary"} onClick={downloadDistances}>
                            <ArrowDownload16Regular/> Download
                        </Button>

                        <ChangeRegistrationDistanceDialog
                            eventId={id}
                            genderList={genders}
                            categoryList={categories}
                            boatList={boats}
                            isNew={true}
                            onUpdate={reloadAllSettings}
                        />
                    </div>
                }/>

                {isLoading && <ProgressRing />}

                {!isLoading && errorMsg && (
                    <MessageBox intent="error" title="Error:" message={errorMsg} closeButtonFunction={() => setErrorMsg(null)} />
                )}

                {!isLoading && !errorMsg && (
                    <Table className={`table`}>
                        <TableHeader>
                            <TableRow>
                                {DistanceTableColumns.map(col => (
                                    <TableHeaderCell key={col.columnKey} style={{ width: getWidthForColumnForDistance(col.columnKey) }}>
                                        <b>{col.label}</b>
                                    </TableHeaderCell>
                                ))}
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {filteredDistances.length === 0 ? (
                                <TableRow><TableCell colSpan={5}>No distances found matching these filters.</TableCell></TableRow>
                            ) : (
                                filteredDistances.map((distance) => (
                                    <TableRow key={distance.id}>
                                        <TableCell>{distance.Gender?.gender}</TableCell>
                                        <TableCell>{distance.Categories?.category}</TableCell>
                                        <TableCell>{distance.Boat?.boat}</TableCell>
                                        <TableCell>{distance.distance}</TableCell>
                                        <TableCell>
                                            <div className={`flex flex-gap-medium`}>
                                                <ChangeRegistrationDistanceDialog
                                                    eventId={id}
                                                    genderList={genders}
                                                    categoryList={categories}
                                                    boatList={boats}
                                                    selectedGender={distance.Gender}
                                                    selectedCategory={distance.Categories}
                                                    selectedBoat={distance.Boat}
                                                    onUpdate={reloadAllSettings}
                                                    isNew={true}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Copy16Filled/>}/>
                                                    }
                                                />
                                                <ChangeRegistrationDistanceDialog
                                                    eventId={id}
                                                    genderList={genders}
                                                    categoryList={categories}
                                                    boatList={boats}
                                                    selectedGender={distance.Gender}
                                                    selectedCategory={distance.Categories}
                                                    selectedBoat={distance.Boat}
                                                    distance={distance}
                                                    onUpdate={reloadAllSettings}
                                                    isNew={false}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Edit16Filled/>}/>
                                                    }
                                                />
                                                <ConfirmDialog
                                                    title={"Item verwijderen?"}
                                                    description={`Weet u zeker dat '${distance.distance}' moet worden verwijderd? Deze actie kan niet ongedaan worden gemaakt`}
                                                    buttonText={"Verwijderen"}
                                                    onConfirm={() => deleteDistances(distance.id)}
                                                    buttonColor={"red"}
                                                    appearance={`subtle`}
                                                    buttonSize={`small`}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>}/>
                                                    }
                                                />
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                )}
            </>
        } />
    );
}

export default RegistrationDistanceView;