import {
    Button,
    Combobox,
    Dialog, DialogActions, DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger,
    Label, Option,
    Input
} from "@fluentui/react-components";
import Boat from "../../models/Boat";
import {useState} from "react";
import MessageBox from "../MessageBar";
import Gender from "../../models/Gender";
import Category from "../../models/Category";
import DistanceSchedule from "../../models/DistanceSchedule";
import Distance from "../../models/Distance";
import {addRaceFromSchedule, updateRaceFromSchedule} from "../../handlers/schedulehandler";
import ProgressRing from "../ProgressRing";
import {formatDateForInput} from "../../handlers/datehandler";
import {RaceTypes} from "../../models/Schedule";

const UpdateScheduleDialog = ({button , isNew, scheduleItem, onUpdate, availableDistances = [new DistanceSchedule(-1, "200 meter")], availableCategories: availableCategories = [new Category(-1, "Junioren B")], availableGenders = [new Gender(-1, "Mixed")], availableBoats = [new Boat(-1, "K1", 1), new Boat(-1, "K2", 2)], eventId = null, newStartTime = new Date(), raceNR = 1}) => {
    const initialDate = scheduleItem && scheduleItem?.planned_start_time ? new Date(scheduleItem.planned_start_time) : new Date(newStartTime);

    const [selectedDistance, setSelectedDistance] = useState(scheduleItem && scheduleItem?.distance ? scheduleItem.distance : undefined);
    const [selectedBoat, setSelectedBoat] = useState(scheduleItem && scheduleItem?.boat ? scheduleItem.boat : undefined);
    const [selectedGender, setSelectedGender] = useState(scheduleItem && scheduleItem?.gender ? scheduleItem.gender : undefined);
    const [selectedCategory, setSelectedCategory] = useState(scheduleItem && scheduleItem?.category ? scheduleItem.category : undefined);
    const [selectedRaceType, setSelectedRaceType] = useState(scheduleItem && scheduleItem.race_type ? scheduleItem.race_type : undefined);
    const [startTime, setStartTime] = useState(initialDate);
    const [errorMsg, setErrorMsg] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [open, setOpen] = useState(false);

    function setSelectedDistanceField(value) {
        if (value instanceof DistanceSchedule) {
            setSelectedDistance(value);
        } else if (value instanceof Distance) {
            setSelectedDistance(value);
            setSelectedBoatField(value.Boat);
            setSelectedGenderField(value.Gender);
            setSelectedCategoryField(value.Categories);
        } else {
            setSelectedDistance(new DistanceSchedule(-1, value));
        }
    }

    function setSelectedBoatField(value) {
        if (value instanceof Boat) {
            setSelectedBoat(value);
        } else {
            setSelectedBoat(new Boat(-1, value, -1));
        }
    }

    function setSelectedGenderField(value) {
        if (value instanceof Gender) {
            setSelectedGender(value);
        } else {
            setSelectedGender(new Gender(-1, value));
        }
    }

    function setSelectedCategoryField(value) {
        if (value instanceof Category) {
            setSelectedCategory(value);
        } else {
            setSelectedCategory(new Category(-1, value));
        }
    }

    function getDistanceText(distance) {
        if (!distance || !distance instanceof Distance) {
            return (distance?.text?.length) ? distance.text : distance;
        }

        return `${distance.distance} (${distance.Boat?.boat} - ${distance.Gender?.gender} - ${distance.Categories?.category})`;
    }

    function saveScheduleItem() {
        setIsLoading(true);

        if (isNew) {
            addScheduleItem();
            return;
        }

        updateScheduleItem();

    }
    function addScheduleItem() {
        if (!eventId) {
            setErrorMsg("An unexpected error occurred.");
            return;
        }

        const scheduleItemToAdd = {
            updated_at: new Date().toISOString(),
            event_id: eventId,
            race_nr: raceNR,
            planned_start_time: startTime,
            distance: selectedDistance,
            category: selectedCategory,
            gender: selectedGender,
            boat: selectedBoat,
            race_type: selectedRaceType,
            participants: []
        };

        addRaceFromSchedule(eventId, scheduleItemToAdd).then((result) => {
            setIsLoading(false);
            if(!result) {
                setErrorMsg("Error saving schedule item");
                return;
            }

            setErrorMsg(null);

            if (onUpdate) {
                onUpdate();
            }

            setOpen(false);
        });

    }

    function updateScheduleItem() {
        const scheduleItemToUpdate = {
            updated_at: new Date().toISOString(),
            planned_start_time: startTime,
            distance: selectedDistance,
            category: selectedCategory,
            gender: selectedGender,
            boat: selectedBoat,
            race_type: selectedRaceType,
        };

        updateRaceFromSchedule(scheduleItem.id, scheduleItemToUpdate).then((result) => {
            setIsLoading(false);
            if(!result) {
                setErrorMsg("Error saving schedule item");
                return;
            }

            setErrorMsg(null);

            if (onUpdate) {
                onUpdate();
            }

            setOpen(false);
        });

    }

    return (
        <>
            <Dialog open={open} onOpenChange={(e, data) => setOpen(data.open)}>
                <DialogTrigger>
                    { button }
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>
                        { isNew ? <>Add Schedule Item</> : <>Update Schedule Item</>}
                    </DialogTitle>
                    <DialogContent>
                        {
                            errorMsg && <MessageBox title={errorMsg} intent={"error"}/>
                        }
                        <div className={`dialog-content-container`}>
                            <div className={`dialog-content-item`}>
                                <Label>Start time:</Label>
                                <Input
                                    id="start-time-picker"
                                    type="datetime-local"
                                    value={formatDateForInput(startTime)}
                                    onChange={(e, data) => {
                                        setStartTime(new Date(data.value));
                                    }}
                                />
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Distance:</Label>
                                <Combobox
                                    value={selectedDistance?.distance}
                                    onOptionSelect={(e, data) => setSelectedDistanceField(data.optionValue)}
                                    onInput={(e) => setSelectedDistanceField(e.target.value)}
                                    placeholder={`Select Distance`}
                                    freeform
                                    autocomplete
                                >
                                    {
                                        Array.from(availableDistances).map((distance) => (
                                            <Option key={distance.id} value={distance}>
                                                { getDistanceText(distance) }
                                            </Option>
                                        ))
                                    }
                                </Combobox>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Boat:</Label>
                                <Combobox
                                    value={selectedBoat?.boat}
                                    onOptionSelect={(e, data) => setSelectedBoatField(data.optionValue)}
                                    onInput={(e) => setSelectedBoatField(e.target.value)}
                                    placeholder={`Select Boat`}
                                    freeform
                                    autocomplete
                                >
                                    {
                                        Array.from(availableBoats).map((boat) => (
                                            <Option key={boat.id} value={boat}>
                                                {boat.boat} ({boat.amount_of_people} person{boat.amount_of_people === 1 ? '' : 's'})
                                            </Option>
                                        ))
                                    }
                                </Combobox>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Gender:</Label>
                                <Combobox
                                    value={selectedGender?.gender}
                                    onOptionSelect={(e, data) => setSelectedGenderField(data.optionValue)}
                                    onInput={(e) => setSelectedGenderField(e.target.value)}
                                    placeholder={`Select Gender`}
                                    freeform
                                    autocomplete
                                >
                                    {
                                        Array.from(availableGenders).map((gender) => (
                                            <Option key={gender.id} value={gender}>
                                                {gender.gender}
                                            </Option>
                                        ))
                                    }
                                </Combobox>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Category:</Label>
                                <Combobox
                                    value={selectedCategory?.category}
                                    onOptionSelect={(e, data) => setSelectedCategoryField(data.optionValue)}
                                    onInput={(e) => setSelectedCategoryField(e.target.value)}
                                    placeholder={`Select Category`}
                                    freeform
                                    autocomplete
                                >
                                    {
                                        Array.from(availableCategories).map((category) => (
                                            <Option key={category.id} value={category}>
                                                {category.category}
                                            </Option>
                                        ))
                                    }
                                </Combobox>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Race Type:</Label>
                                <Combobox
                                    value={selectedRaceType}
                                    onOptionSelect={(e, data) => setSelectedRaceType(data.optionValue)}
                                    onInput={(e) => setSelectedRaceType(e.target.value)}
                                    placeholder={`Select Race Type`}
                                    freeform
                                    autocomplete
                                >
                                    {
                                        RaceTypes.map((raceType) => (
                                            <Option key={raceType} value={raceType}>{raceType}</Option>
                                        ))
                                    }
                                </Combobox>
                            </div>
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button as={"a"} className={`button`} appearance="secondary">Annuleren</Button>
                        </DialogTrigger>
                        <Button as={"a"} className={`button`} disabled={isLoading} appearance="primary" onClick={() => saveScheduleItem()}>
                            { isLoading && <ProgressRing/> }
                            { !isLoading && `Save` }
                        </Button>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
}

export default UpdateScheduleDialog;