import './styles/App.css';
import './styles/Site.css';
import {HashRouter as Router, Routes, Route, useLocation} from "react-router-dom";
import HomeView from "./pages/HomeView";
import EventOverview from "./pages/EventOverview";
import RegistrationOverview from "./pages/registration/RegistrationOverview";
import ManageRegistrations from "./pages/registration/ManageRegistrations";
import ManageClubs from "./pages/registration/ManageClubs";
import SetUpRegistration from "./pages/registration/SetUpRegistration";
import {
    FluentProvider,
    webLightTheme
} from "@fluentui/react-components";
import {isLoggedIn} from "./handlers/userhandler";
import LoginView from "./pages/LoginView";
import EventSettingsOverview from "./pages/eventsettings/EventSettingsOverview";
import {handleLoginPages} from "./handlers/routehandler";
import {useEffect, useState} from "react";
import ScheduleView from "./pages/schedule/ScheduleView";
import StartRaceOverview from "./pages/racesystem/start/StartRaceOverview";
import StartSingleRaceView from "./pages/racesystem/start/StartSingleRaceView";
import FinishRaceOverview from "./pages/racesystem/finish/FinishRaceOverview";
import FinishSingleRaceView from "./pages/racesystem/finish/FinishSingleRaceView";
import {supabase} from "./handlers/databasehandler";
import {fullSupabaseSync} from "./handlers/localdatabasehandler";
import SideNavBar from "./components/SideNavBar";
import {fetchEvents, getAllEventIDs} from "./handlers/eventhandler";
export default function App() {
    const [loggedIn, setLoggedIn] = useState(false);
    let interval = null;

    isLoggedIn().then(isLoggedIn => {
        setLoggedIn(isLoggedIn);
        handleLoginPages(isLoggedIn);
    });

    useEffect(() => {
        const checkUserAndSync = async () => {
            const { data: { session } } = await supabase.auth.getSession();

            if (session) {
                let userEvents = getAllEventIDs();
                if (!userEvents) {
                    await fetchEvents();

                    userEvents = getAllEventIDs();

                    if (!userEvents) return;
                }
                startSupabaseSyncInterval(userEvents);
            }
        };

        checkUserAndSync().then(r => {/*ignored*/});
    }, []);

    function RouteChangeHandler() {
        const location = useLocation();

        useEffect(() => {
            isLoggedIn().then(isLoggedIn => {
                setLoggedIn(isLoggedIn);
                handleLoginPages(isLoggedIn);
            });
        }, [location, loggedIn]);
        return null;
    }

    const startSupabaseSyncInterval = (eventIdsArray) => {
        if (interval) {
            clearInterval(interval);
        }

        interval = setInterval(() => {
            fullSupabaseSync(eventIdsArray).then((result) => {
                console.info(result);
            });
        }, 3000)
    }

    const stopSupabaseSyncInterval = () => {
        clearInterval(interval);
    }

    return (
          <FluentProvider theme={webLightTheme} className={`bg-gradient`}>
              <Router>
                  <RouteChangeHandler />
                  <div className={`app-container`}>
                      {loggedIn && <SideNavBar/> }
                      <Routes>
                          <Route path="/" element={<HomeView />} />
                          <Route path="/login" element={<LoginView />} />
                          <Route path="/add-event" element={<EventSettingsOverview />} />
                          <Route path="/events/:id" element={<EventOverview />} />
                          <Route path="/events/:id/settings" element={<EventSettingsOverview />} />
                          <Route path="/events/:id/registration" element={<RegistrationOverview />} />
                          <Route path="/events/:id/registration/clubs" element={<ManageClubs />} />
                          <Route path="/events/:id/registration/manage" element={<ManageRegistrations />} />
                          <Route path="/events/:id/registration/setup" element={<SetUpRegistration />} />
                          <Route path="/events/:id/schedule" element={<ScheduleView />} />
                          <Route path="/events/:id/race" element={<ScheduleView />} />
                          <Route path="/events/:id/start" element={<StartRaceOverview />} />
                          <Route path="/events/:id/start/:raceId" element={<StartSingleRaceView />} />
                          <Route path="/events/:id/finish" element={<FinishRaceOverview />} />
                          <Route path="/events/:id/finish/:raceId" element={<FinishSingleRaceView />} />
                      </Routes>
                  </div>
              </Router>
          </FluentProvider>
    );
}