import {useParams} from "react-router-dom";
import BodyContainer from "../../components/BodyContainer";
import Title from "../../components/Title";
import {
    Button, Combobox,
    Dialog, DialogActions, DialogBody, DialogContent, DialogSurface, DialogTitle,
    DialogTrigger,
    Input,
    Label, Option,
    Spinner,
    Switch,
    useId
} from "@fluentui/react-components";
import {useEffect, useRef, useState} from "react";
import * as React from "react";
import {getUserID} from "../../handlers/userhandler";
import MessageBox from "../../components/MessageBar";
import LoginCard from "../../components/LoginCard";
import SettingsItem from "../../components/SettingsItem";
import {QRCodeCanvas} from "qrcode.react";
import {downloadFile} from "../../handlers/downloadhandler";
import {navigateToPage} from "../../handlers/routehandler";
import {addEvent, deleteEvent, fetchEventById, updateEvent} from "../../handlers/eventhandler";
import RaceEvent from "../../models/Event";

const EventSettingsOverview = () => {
    const baseUrl = `https://gadijkhuis.github.io/Klokking-2026-Registration-Beta/#/`;

    const { id } = useParams();
    const [msg, setMsg] = useState(null);
    const [msgIntent, setMsgIntent] = useState(null);
    const [msgTitle, setMsgTitle] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [isLoadingEventData, setIsLoadingEventData] = useState(false);
    const [eventData, setEventData] = useState(new RaceEvent(undefined));

    const eventNameID = useId("name");
    const eventLocationID = useId("location");
    const eventStartDateID = useId("startDate");
    const eventEndDateID = useId("endDate");
    const eventContactEmailID = useId("contactEmail");
    const eventRaceTypeID = useId("raceType");
    const eventRegistrationEndId = useId("registrationEnd");

    const qrRegistrationRef = useRef(null);
    const idExists = id !== undefined && id !== null;
    const raceTypes = [
        "Propaganda Wedstrijd",
        "Nederlands Kampioenschap",
        "(Inter)nationale Wedstrijd"
    ];

    useEffect(() => {
        if (idExists && !isLoadingEventData) {
            setIsLoadingEventData(true);
            fetchEventById(id).then((result) => {
                if (!result) {
                    setMessageData("Error fetching data: ", "An error occurred fetching data", "error");
                    return;
                }

                setEventData(result);
                setIsLoadingEventData(false);
            });
        }
    }, []);

    async function handleSubmit() {
        setIsLoading(true);

        const event = {...eventData};

        if (!idExists) {
            event.user_id = getUserID();
        }

        if (event.name === "") {
            setMessageData("Error saving data: ", "Name cannot be empty", "error");
            setIsLoading(false);
            return;
        }

        const result = idExists ? await updateEvent(id, event) : await addEvent(event);

        if (result == null) {
            setMessageData("Error saving data: ", "An unknown error has occurred.", "error");
            setIsLoading(false);
            return;
        }

        if (result.error != null) {
            setMessageData("Error saving data: ", result.error.message, "error");
            setIsLoading(false);
            return;
        }

        setIsLoading(false);
        setMessageData("Data successfully saved: ", "Event is successfully saved to the database", "success");

        if (!idExists) {
            navigateToPage(``);
        }
    }

    function setMessageData(title, message, intent) {
        setMsgIntent(intent);
        setMsgTitle(title);
        setMsg(message);
    }

    async function deleteEventClick() {
        if (await deleteEvent(id) != null) {
            setMessageData("Data successfully deleted: ", "Event is successfully deleted from the database", "success");

            setTimeout(() => {
                navigateToPage(``);
            }, 1000)
        } else {
            setMessageData("Error deleting data: ", "An error occurred deleting the event", "error");
        }
    }

    function downloadRegistrationImage() {
        const imageUrl = qrRegistrationRef.current.toDataURL('image/png');
        const filename = `QR_${eventData.name}_${Date.now()}.png`;
        downloadFile(imageUrl, filename);
    }

    return (
        <BodyContainer showBackButton={true} content={
            <>
                {msg != null &&
                    <MessageBox
                        intent={msgIntent}
                        title={msgTitle}
                        message={msg}
                        closeButtonFunction={() => { setMsg(null) }}
                    />
                }
                <Title title={ idExists ? `Evenement instellingen` : `Evenement aanmaken` } />
                { isLoadingEventData && <Spinner /> }
                { !isLoadingEventData &&
                <LoginCard content={
                    <>
                        {isLoadingEventData ? <Spinner /> : null}
                        <Label htmlFor={eventNameID}>
                            Naam:
                        </Label>
                        <Input
                            id={eventNameID}
                            value={eventData.name}
                            onChange={(e) => setEventData({ ...eventData, name: e.target.value })}
                        />
                        <Label htmlFor={eventLocationID}>
                            Locatie:
                        </Label>
                        <Input
                            id={eventLocationID}
                            value={eventData.location}
                            onChange={(e) => setEventData({ ...eventData, location: e.target.value })}
                        />
                        <Label htmlFor={eventStartDateID}>
                            Startdatum:
                        </Label>
                        <Input
                            id={eventStartDateID}
                            type={"date"}
                            value={eventData.startDate}
                            onChange={(e) => setEventData({ ...eventData, startDate: e.target.value })}
                        />
                        <Label htmlFor={eventEndDateID}>
                            Einddatum:
                        </Label>
                        <Input
                            id={eventEndDateID}
                            type={"date"}
                            value={eventData.endDate}
                            onChange={(e) => setEventData({ ...eventData, endDate: e.target.value })}
                        />
                        <Label htmlFor={eventContactEmailID}>
                            Contact Email:
                        </Label>
                        <Input
                            id={eventContactEmailID}
                            type={"email"}
                            value={eventData.contact_email}
                            onChange={(e) => setEventData({ ...eventData, contact_email: e.target.value })}
                        />
                        <Label htmlFor={eventRaceTypeID}>
                            Wedstrijd type:
                        </Label>
                        <Combobox
                            id={eventRaceTypeID}
                            value={eventData.race_type}
                            onOptionSelect={(e, o) => setEventData({ ...eventData, race_type: o.optionValue })}
                            onChange={(e) => setEventData({ ...eventData, race_type: e.target.value })}>
                            <>
                                {raceTypes.map((raceType, index) => (
                                    <Option key={index} value={raceType}>{raceType}</Option>
                                ))}
                            </>
                        </Combobox>
                        <Switch
                            onChange={(e) => setEventData({...eventData, using_wsv: e.currentTarget.checked })}
                            checked={eventData.using_wsv}
                            label={"Watersportverbond Informatie"}
                        />
                        <Switch
                            onChange={(e) => setEventData({...eventData, is_public: e.currentTarget.checked })}
                            checked={eventData.is_public}
                            label={"Weergeven op online inschrijfsysteem"}
                        />
                        <Label htmlFor={eventRegistrationEndId}>
                            Einde inschrijving:
                        </Label>
                        <Input
                            id={eventRegistrationEndId}
                            type={"date"}
                            value={eventData.registration_end}
                            onChange={(e) => setEventData({ ...eventData, registration_end: e.target.value })}
                        />
                    </>
                } onClick={async () => { if (!isLoading && !isLoadingEventData) { await handleSubmit(); }}} isLoading={isLoading} buttonText={`Opslaan`} />
                }
                { !isLoadingEventData && idExists &&
                    <>
                        <Dialog>
                            <DialogTrigger>
                                <SettingsItem title={`Online zichtbaarheid`} text={`Geef de QR codes en URL's van het evenement weer.`} buttonText={`Online data weergeven`} />
                            </DialogTrigger>
                            <DialogSurface>
                                <DialogBody>
                                    <DialogTitle>Online Zichtbaarheid</DialogTitle>
                                    <DialogContent>
                                        <div className={`dialog-content-container`}>
                                            <div className={`dialog-content-item`}>
                                                <Label>
                                                    Registration URL:
                                                </Label>
                                                <QRCodeCanvas
                                                    ref={qrRegistrationRef}
                                                    marginSize={5}
                                                    value={`${baseUrl}${id}`}
                                                />
                                                <div className={`menu-toolbar`}>
                                                    <Button
                                                        as={`a`}
                                                        appearance={`primary`}
                                                        onClick={() => downloadRegistrationImage()}
                                                    >
                                                        Download QR Code
                                                    </Button>
                                                    <Button
                                                        as={`a`}
                                                        appearance={`secondary`}
                                                        onClick={() => navigator.clipboard.writeText(`${baseUrl}${id}`)}
                                                    >
                                                        Copy URL
                                                    </Button>
                                                    <Button
                                                        as={`a`}
                                                        href={`${baseUrl}${id}`}
                                                        target={`_blank`}
                                                        appearance={`secondary`}
                                                    >
                                                        Open Registration Page
                                                    </Button>
                                                </div>
                                                <Input disabled={true} value={`${baseUrl}${id}`}/>
                                            </div>
                                        </div>
                                    </DialogContent>
                                    <DialogActions>
                                        <DialogTrigger disableButtonEnhancement>
                                            <Button as={`a`} appearance="primary">Sluiten</Button>
                                        </DialogTrigger>
                                    </DialogActions>
                                </DialogBody>
                            </DialogSurface>
                        </Dialog>
                        <Dialog>
                            <DialogTrigger>
                                <SettingsItem title={"Evenement verwijderen"} text={"Verwijder het evenement van de server. Alle gekoppelde data wordt verwijderd."} buttonText={"Evenement verwijderen"} buttonColor={"red"}/>
                            </DialogTrigger>
                            <DialogSurface>
                                <DialogBody>
                                    <DialogTitle>Evenement verwijderen</DialogTitle>
                                    <DialogContent>
                                        Deze actie kan niet ongedaan worden gemaakt
                                    </DialogContent>
                                    <DialogActions>
                                        <DialogTrigger>
                                            <Button as={`a`} className={`button `} style={{backgroundColor: `red`}} appearance={`primary`} onClick={async () => deleteEventClick()}>Verwijderen</Button>
                                        </DialogTrigger>
                                        <DialogTrigger disableButtonEnhancement>
                                            <Button as={`a`} className={`button`} appearance="secondary">Sluiten</Button>
                                        </DialogTrigger>
                                    </DialogActions>
                                </DialogBody>
                            </DialogSurface>
                        </Dialog>
                    </>
                }
            </>
        }></BodyContainer>
    );
};

export default EventSettingsOverview;