import EventItemCard from "../components/EventItemCard.jsx";
import BodyContainer from "../components/BodyContainer";
import Title from "../components/Title";
import {useEffect, useState} from "react";
import ProgressRing from "../components/ProgressRing";
import {navigateToPage} from "../handlers/routehandler";
import {fetchEvents} from "../handlers/eventhandler";

const HomeView = () => {
    const [localEvents, setLocalEvents] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchEvents().then((events) => {
            setLocalEvents(events);
            setIsLoading(false);
        });
    }, []);

    return (
        <BodyContainer content={
            <>
                {isLoading && <ProgressRing/>}
                {!isLoading &&
                    <>
                        <Title title={"Welkom bij Klokking"} subtitle={"Selecteer een evenement om verder te gaan"} />
                        {localEvents.map(event => (
                            <EventItemCard
                                key={event.id}
                                title={event.name}
                                onSelect={() => navigateToPage(`events/${event.id}`) }/>
                        ))}
                        <EventItemCard title="Evenement Toevoegen" onSelect={() => navigateToPage(`add-event`)}/>
                    </>
                }
            </>
        }/>
    );
}

export default HomeView;