import Dexie from 'dexie';
import { supabase } from "./databasehandler";

// ─────────────────────────────────────────────────────────────────────────────
// DATABASE SETUP
// ─────────────────────────────────────────────────────────────────────────────

//RUN this supabase migration
// ALTER TABLE "Schedules"
// ADD COLUMN field_timestamps jsonb NOT NULL DEFAULT '{}';

const db = new Dexie('RaceDatabase');

// Version 1 → original schema (no field_timestamps)
db.version(1).stores({
    schedules: 'id, event_id, race_nr'
});

// Version 2 → adds field_timestamps support; existing rows get it set to {}
//             via the upgrade hook so old records are handled gracefully.
db.version(2).stores({
    schedules: 'id, event_id, race_nr'
}).upgrade(tx => {
    return tx.table('schedules').toCollection().modify(record => {
        if (!record.field_timestamps) {
            record.field_timestamps = {};
        }
    });
});

// ─────────────────────────────────────────────────────────────────────────────
// TRACKED FIELDS
// Fields listed here participate in per-field timestamp conflict resolution.
// Any field NOT listed falls back to last-write-wins at the record level.
// Add or remove field names here as your schema evolves.
// ─────────────────────────────────────────────────────────────────────────────

const TRACKED_FIELDS = [
    'planned_start_time',
    'race_start_time',
    'race_nr',
    'boat',
    'gender',
    'category',
    'distance',
    'participants',
    'results',
];

// ─────────────────────────────────────────────────────────────────────────────
// MERGE HELPERS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Merges a remote record into a local record using per-field timestamps.
 *
 * Rules:
 *  - For each TRACKED_FIELD, whichever side has the higher field timestamp wins,
 *    even if the winning value is null/empty (intentional deletions are respected).
 *  - For untracked fields, the remote value wins (standard pull behaviour).
 *  - Returns the merged record and a flag indicating whether the local side
 *    has any fields that are newer than the remote, meaning a push is needed.
 *
 * @param {object} remoteItem  - Record as it came from Supabase
 * @param {object|undefined} localItem - Existing local Dexie record, if any
 * @returns {{ merged: object, needsPush: boolean }}
 */
const mergeRemoteWithLocal = (remoteItem, localItem) => {
    if (!localItem) {
        // No local record — take remote as-is, initialise empty field_timestamps
        // if the remote doesn't have them yet (e.g. rows inserted before this migration).
        return {
            merged: {
                ...remoteItem,
                field_timestamps: remoteItem.field_timestamps ?? {},
            },
            needsPush: false,
        };
    }

    const remoteTs = remoteItem.field_timestamps ?? {};
    const localTs  = localItem.field_timestamps  ?? {};

    const mergedFieldTs = { ...remoteTs };
    const merged = { ...remoteItem }; // Start from remote, then selectively override.
    let needsPush = false;

    for (const field of TRACKED_FIELDS) {
        const rTs = remoteTs[field] ?? 0;
        const lTs = localTs[field]  ?? 0;

        if (lTs > rTs) {
            // Local change is newer → keep local value and timestamp.
            merged[field]        = localItem[field];
            mergedFieldTs[field] = lTs;
            needsPush = true; // We need to push this field back to the cloud.
        }
        // If rTs >= lTs: remote wins (already set via spread above).
    }

    merged.field_timestamps = mergedFieldTs;
    return { merged, needsPush };
};

// ─────────────────────────────────────────────────────────────────────────────
// PUBLIC SYNC API
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Full sync: push local changes first, then pull remote changes.
 * Pushing first reduces the chance of a pull overwriting an in-flight local change.
 */
const fullSupabaseSync = async (eventIdsArray) => {
    const pushResult = await pushToSupabase();
    const pullResult = await pullFromSupabase(eventIdsArray);
    return { pushResult, pullResult };
};

/**
 * PULL: Fetches all remote records for the given event IDs and merges them
 * into Dexie using per-field timestamp conflict resolution.
 * Records where local fields were newer are immediately pushed back to Supabase.
 * Local records that no longer exist remotely are deleted (propagates remote deletes).
 */
const pullFromSupabase = async (eventIdsArray) => {
    try {
        const { data, error } = await supabase
            .from('Schedules')
            .select('*')
            .in('event_id', eventIdsArray);

        if (error) {
            console.error('[Sync] Pull failed:', error);
            return { success: false, error };
        }

        // ── Propagate remote deletes ──────────────────────────────────────────
        // Fetch every local record that belongs to the synced event IDs.
        // Any local record whose ID is absent from the remote result set has
        // been deleted on another device and must be removed here too.
        const eventIdNumbers = eventIdsArray.map(Number);
        const allLocalForEvents = await db.schedules
            .filter(r => eventIdNumbers.includes(Number(r.event_id)))
            .toArray();

        const remoteIdSet = new Set(
            (data ?? []).map(item => item?.id?.toString()).filter(Boolean)
        );

        const staleLocalIds = allLocalForEvents
            .map(r => r.id)
            .filter(id => !remoteIdSet.has(id.toString()));

        if (staleLocalIds.length > 0) {
            console.warn('[Sync] Trying to remove:', await db.schedules.filter(r => staleLocalIds.includes(r.id.toString())).toArray());

            await db.schedules.bulkDelete(staleLocalIds);
            console.info(`[Sync] Removed ${staleLocalIds.length} locally-stale record(s) that were deleted remotely.`);
        }
        // ─────────────────────────────────────────────────────────────────────

        if (!data || data.length === 0) {
            return { success: true, count: 0 };
        }

        const now = Date.now();

        // Batch-fetch all matching local records for efficient comparison.
        const remoteIds = [...remoteIdSet];
        const localRecords = await db.schedules.where('id').anyOf(remoteIds).toArray();
        const localMap = Object.fromEntries(localRecords.map(r => [r.id, r]));

        const recordsToPushBack = [];

        const mergedData = data.map(item => {
            if (!item?.id) return item;

            const localItem = localMap[item.id.toString()];
            const { merged, needsPush } = mergeRemoteWithLocal(item, localItem);

            const finalItem = {
                ...merged,
                id: item.id.toString(),
                last_synced: now,
                // Only bump last_modified if we're keeping a locally-newer field,
                // so the regular push cycle also picks this up as a pending change.
                ...(needsPush ? { last_modified: now + 1 } : {}),
            };

            if (needsPush) {
                recordsToPushBack.push(finalItem);
            }

            return finalItem;
        });

        await db.schedules.bulkPut(mergedData);

        // Push corrections back immediately so other devices get the right data
        // without waiting for the next push cycle.
        if (recordsToPushBack.length > 0) {
            console.info(
                `[Sync] ${recordsToPushBack.length} record(s) had locally-newer fields. Pushing corrections to cloud.`
            );
            await pushCorrectedRecordsToSupabase(recordsToPushBack);
        }

        return { success: true, count: data.length };

    } catch (error) {
        console.error('[Sync] Pull exception:', error);
        return { success: false, error };
    }
};

/**
 * PUSH: Sends all locally modified records (last_modified > last_synced) to Supabase.
 */
const pushToSupabase = async () => {
    try {
        const localChanges = await db.schedules
            .filter(item => (item.last_modified || 0) > (item.last_synced || 0))
            .toArray();

        if (localChanges.length === 0) return { success: true, count: 0 };

        const toUpload = localChanges.map(({ last_synced, ...cleanItem }) => ({
            ...cleanItem,
            id: parseInt(cleanItem.id),
        }));

        const { error } = await supabase
            .from('Schedules')
            .upsert(toUpload);

        if (error) {
            console.error('[Sync] Push failed:', error);
            return { success: false, error };
        }

        const ids = localChanges.map(item => item.id);
        await db.schedules.where('id').anyOf(ids).modify({ last_synced: Date.now() });

        return { success: true, count: toUpload.length };
    } catch (error) {
        console.error('[Sync] Push exception:', error);
        return { success: false, error };
    }
};

/**
 * Internal helper: pushes a specific set of already-merged records back to Supabase.
 * Used after a pull detects locally-newer fields that the cloud should receive.
 */
const pushCorrectedRecordsToSupabase = async (records) => {
    try {
        const toUpload = records.map(({ last_synced, last_modified, ...cleanItem }) => ({
            ...cleanItem,
            id: parseInt(cleanItem.id),
        }));

        const { error } = await supabase
            .from('Schedules')
            .upsert(toUpload);

        if (error) {
            console.error('[Sync] Failed to push corrected records:', error);
            return;
        }

        // Mark as synced so the regular push cycle doesn't re-upload them.
        const ids = records.map(r => r.id);
        await db.schedules.where('id').anyOf(ids).modify({ last_synced: Date.now() });
    } catch (error) {
        console.error('[Sync] Exception while pushing corrected records:', error);
    }
};

// ─────────────────────────────────────────────────────────────────────────────
// LOCAL CRUD
// ─────────────────────────────────────────────────────────────────────────────

/**
 * FETCH: Returns all schedule records for a given event, sorted by race_nr.
 */
const fetchScheduleFromLocalDatabase = async (eventId) => {
    try {
        const results = await db.schedules
            .where('event_id')
            .equals(Number(eventId))
            .sortBy('race_nr');
        return { data: results, error: null };
    } catch (error) {
        return { data: null, error };
    }
};

/**
 * GET SINGLE: Returns a single schedule record by its ID.
 */
const fetchSingleScheduleItemFromLocalDatabase = async (id) => {
    try {
        const item = await db.schedules.get(id.toString());
        return { data: item, error: null };
    } catch (error) {
        return { data: null, error };
    }
};

/**
 * ADD: Inserts a new race record locally.
 * Initialises field_timestamps for all tracked fields to the current time.
 */
const addRaceToScheduleFromLocalDatabase = async (raceData) => {
    try {
        const now = Date.now();
        const initialFieldTimestamps = {};

        for (const field of TRACKED_FIELDS) {
            if (raceData[field] !== undefined) {
                initialFieldTimestamps[field] = now;
            }
        }

        await db.schedules.put({
            ...raceData,
            id: raceData.id.toString(),
            last_modified: now,
            field_timestamps: {
                ...(raceData.field_timestamps ?? {}),
                ...initialFieldTimestamps,
            },
        });
        return { error: null };
    } catch (error) {
        return { error };
    }
};

/**
 * UPDATE: Updates specific fields on an existing race record.
 *
 * IMPORTANT: `updatedData` should only contain the fields that actually changed.
 * Only the timestamps for those fields are bumped, so unrelated fields on other
 * devices are not incorrectly considered stale.
 *
 * @param {string|number} id
 * @param {object} updatedData - Only the fields that changed, e.g. { results: [...] }
 */
const updateRaceFromScheduleFromLocalDatabase = async (id, updatedData) => {
    try {
        const now = Date.now();
        const existing = await db.schedules.get(id.toString());
        const existingFieldTs = existing?.field_timestamps ?? {};

        // Bump timestamps only for the fields that are being updated.
        const updatedFieldTs = { ...existingFieldTs };
        for (const field of TRACKED_FIELDS) {
            if (field in updatedData) {
                updatedFieldTs[field] = now;
            }
        }

        await db.schedules.update(id.toString(), {
            ...updatedData,
            last_modified: now,
            field_timestamps: updatedFieldTs,
        });
        return { error: null };
    } catch (error) {
        return { error };
    }
};

/**
 * DELETE: Removes a race record from local storage.
 */
const deleteRaceFromScheduleFromLocalDatabase = async (id) => {
    try {
        await db.schedules.delete(id.toString());
        return { error: null };
    } catch (error) {
        return { error };
    }
};

export {
    fullSupabaseSync,
    pullFromSupabase,
    pushToSupabase,
    fetchScheduleFromLocalDatabase,
    fetchSingleScheduleItemFromLocalDatabase,
    addRaceToScheduleFromLocalDatabase,
    updateRaceFromScheduleFromLocalDatabase,
    deleteRaceFromScheduleFromLocalDatabase,
};