import * as React from "react";
import {useEffect, useState} from "react";
import {useParams} from "react-router-dom";
import {
    deleteRegistrationFromDatabase, fetchBoatsFromDatabase, fetchCategoriesFromDatabase, fetchDistancesFromDatabase,
    fetchParticipantsFromDatabaseForList,
    fetchRegistrationsFromDatabaseForClub,
    fetchRegistrationsFromDatabaseForList,
    fetchRegistrationsFromDatabaseForRG
} from "../../../handlers/databasehandler";
import ProgressRing from "../../ProgressRing";
import MessageBox from "../../MessageBar";
import MenuToolbar from "../../MenuToolbar";
import {ArrowDownload16Regular, Delete16Filled, Edit16Filled} from "@fluentui/react-icons";
import {
    Button,
    Menu,
    MenuItem,
    MenuList,
    MenuPopover,
    MenuTrigger,
    Table, TableBody, TableCell,
    TableHeader, TableHeaderCell, TableRow
} from "@fluentui/react-components";
import {DownloadOptions} from "../../../enums/downloadOptions";
import ChangeRegistrationParticipantDialog from "./ChangeRegistrationParticipantDialog";
import {downloadFile} from "../../../handlers/downloadhandler";
import ConfirmDialog from "../../ConfirmDialog";
import InnerBodyContainer from "../../InnerBodyContainer";
import {fetchAllRegistrations} from "../../../handlers/registrationhandler";
import RegistrationCostsDialog from "../registration-costs/RegistrationCostsDialog";

const RegistrationParticipantView = () => {
    const {id} = useParams();
    const [registrations, setRegistrations] = useState([]);
    const [boats, setBoats] = useState([]);
    const [categories, setCategories] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isDownloading, setIsDownloading] = useState(false);
    const [errorMsg, setErrorMsg] = useState(null);
    const [allAvailableParticipants, setAllAvailableParticipants] = useState([]);
    const [distances, setDistances] = useState([]);

    function fetchRegistrationsAfterUpdate() {
        setIsLoading(true);
        fetchRegistrations().then((data) => {
            setIsLoading(false);

            if (data == null) {
                setErrorMsg("Error loading registrations");
                return;
            }
            setRegistrations(data);
            setParticipantsFromRegistrations(data);
        });
    }

    async function fetchRegistrations() {
        return await fetchAllRegistrations(id);
    }

    async function fetchBoats() {
        return await fetchBoatsFromDatabase(id);
    }

    async function fetchCategories() {
        return await fetchCategoriesFromDatabase(id);
    }

    useEffect(() => {
        fetchRegistrations().then((data) => {
            setIsLoading(false);

            if (data == null) {
                setErrorMsg("Error loading registrations");
                return;
            }

            setRegistrations(data);
            setParticipantsFromRegistrations(data);

            fetchDistances();

        });

        fetchBoats().then((data) => {
            if (data == null) {
                return;
            }
            setBoats(data);
        });

        fetchCategories().then((data) => {
            if (data == null) {
                return;
            }
            setCategories(data);
        });
    }, []);

    function setParticipantsFromRegistrations(registrationData) {
        const participantsSet = new Set();

        registrationData.forEach((registration) => {

            if (checkExistingParticipant(registration.participant1)) {
                participantsSet.add(registration.participant1);
            }

            if (checkExistingParticipant(registration.participant2)) {
                participantsSet.add(registration.participant2);
            }

            if (checkExistingParticipant(registration.participant3)) {
                participantsSet.add(registration.participant3);
            }

            if (checkExistingParticipant(registration.participant4)) {
                participantsSet.add(registration.participant4);
            }
        });

        setAllAvailableParticipants(participantsSet);

        function checkExistingParticipant(participantToAdd) {
            if (!participantToAdd) return false;

            for (let participant of participantsSet) {
                if (participant.id === participantToAdd.id) {
                    return false;
                }
            }

            return true;
        }
    }

    function downloadTrigger(downloadOptions) {
        if (!downloadOptions && !downloadOptions instanceof DownloadOptions) {
            return;
        }

        setIsDownloading(true);

        switch (downloadOptions) {
            case DownloadOptions.LIST_EXPORT:
                downloadList().then(() => setIsDownloading(false));
                break;
            case DownloadOptions.RG_EXPORT:
                downloadRG().then(() => setIsDownloading(false));
                break;
            case DownloadOptions.CLUB_EXPORT:
                downloadClub().then(() => setIsDownloading(false));
                break;
            case DownloadOptions.PARTICIPANTS_EXPORT:
                downloadParticipants().then(() => setIsDownloading(false));
                break;
            default:
                downloadList().then(() => setIsDownloading(false));
                return;
        }
    }

    async function downloadList() {
        const csvValue = await fetchRegistrationsFromDatabaseForList(id);
        if (!csvValue) {
            setErrorMsg("Error downloading list with registrations");
            return;
        }
        const csvData = new Blob([csvValue], {type: 'text/csv'});

        downloadData(csvData);
    }

    async function downloadParticipants() {
        const csvValue = await fetchParticipantsFromDatabaseForList(id);
        if (!csvValue) {
            setErrorMsg("Error downloading list with participants");
            return;
        }
        const csvData = new Blob([csvValue], {type: 'text/csv'});

        downloadData(csvData);
    }


    async function downloadRG() {
        const csvValue = await fetchRegistrationsFromDatabaseForRG(id);
        if (!csvValue) {
            setErrorMsg("Error downloading RG with registrations");
            return;
        }
        const csvData = new Blob([csvValue], {type: 'text/csv'});

        downloadData(csvData);
    }

    async function downloadClub() {
        const csvValue = await fetchRegistrationsFromDatabaseForClub(id);
        if (!csvValue) {
            setErrorMsg("Error downloading Club with registrations");
            return;
        }
        const csvData = new Blob([csvValue], {type: 'text/csv'});

        downloadData(csvData);
    }

    function downloadData(csvData) {
        const fileName = `Registrations_${Date.now()}`;
        downloadFile(csvData, fileName);
    }

    function createParticipantText(p, p2, p3, p4) {
        if (!p) return ``;

        let text = p.fullName;

        if (p2) {
            text += ` - ${p2.fullName}`;
        }

        if (p3) {
            text += ` - ${p3.fullName}`;
        }

        if (p4) {
            text += ` - ${p4.fullName}`;
        }

        return text;
    }

    function deleteRegistrationItem(r) {
        deleteRegistrationFromDatabase(id, r.id).then((result) => {
            if (!result) {
                setErrorMsg("Error deleting registration");
                return;
            }

            fetchRegistrationsAfterUpdate();
        });
    }

    function fetchDistances() {
        fetchDistancesFromDatabase(id).then((data) => {
            if (data == null) {
                return;
            }

            setDistances(data);
        });
    }

    const ParticipantTableColumns = [
        { columnKey: "name", label: "Name", span: 5 },
        { columnKey: "distance", label: "Race", span: 6 },
        { columnKey: "actions", label: "Actions", span: 1 },
    ]

    const getWidthForColumnForParticipant = (columnKey) => {
        const column = ParticipantTableColumns.find(col => col.columnKey === columnKey);
        if (column) {
            return `${(column.span / 12) * 100}%`;
        }
        return 'auto';
    };

    return (
        <InnerBodyContainer content={
            <>
                { isLoading && <ProgressRing/>}
                { !isLoading && errorMsg != null &&
                    <MessageBox
                        intent={"error"}
                        title={"An error occurred:"}
                        message={errorMsg}
                        closeButtonFunction={() => { setErrorMsg(null) }}
                    />
                }
                { !isLoading && !errorMsg &&
                    <>
                        <MenuToolbar content={
                           <>
                               <Menu>
                                   <MenuTrigger>
                                       <Button as={`a`} className={`button`} appearance={"primary"} disabled={isDownloading} >
                                           { isDownloading && <ProgressRing/> }
                                           <ArrowDownload16Regular/> Download
                                       </Button>
                                   </MenuTrigger>
                                   <MenuPopover>
                                       <MenuList>
                                           <MenuItem onClick={() => downloadTrigger(DownloadOptions.LIST_EXPORT)}>
                                               List overview
                                           </MenuItem>
                                           <MenuItem onClick={() => downloadTrigger(DownloadOptions.PARTICIPANTS_EXPORT)}>
                                               Participants data
                                           </MenuItem>
                                           <MenuItem onClick={() => downloadTrigger(DownloadOptions.RG_EXPORT)}>
                                               RG export
                                           </MenuItem>
                                           <MenuItem onClick={() => downloadTrigger(DownloadOptions.CLUB_EXPORT)}>
                                               Club overview
                                           </MenuItem>
                                       </MenuList>
                                   </MenuPopover>
                               </Menu>
                               <RegistrationCostsDialog
                                   button={
                                       <Button as={`a`} className={`button`}>
                                           Registrations costs overview
                                       </Button>
                                   }
                                   eventId={id}
                                   eventName={`Registrations costs overview`}
                                   registrations={registrations}
                                   boats={boats}
                                   categories={categories}
                               />
                           </>
                        } />

                        <Table className={`table`}>
                            <TableHeader>
                                <TableRow>
                                    { ParticipantTableColumns.map(col => (
                                        <TableHeaderCell key={col.columnKey} style={{ width: getWidthForColumnForParticipant(col.columnKey) }} >
                                            <b>{col.label}</b>
                                        </TableHeaderCell>
                                    ))}
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                { registrations.length === 0 && <TableRow><TableCell colSpan={3}>No registrations found</TableCell></TableRow> }
                                { registrations.map(registration => (
                                    <TableRow key={registration.id}>
                                        <TableCell>
                                            {createParticipantText(registration.participant1, registration.participant2, registration.participant3, registration.participant4)}
                                        </TableCell>
                                        <TableCell>
                                            {`${registration.distance.Gender.gender} - ${registration.distance.Categories.category} - ${registration.distance.Boat.boat} - ${registration.distance.distance}`}
                                        </TableCell>
                                        <TableCell>
                                            <div className={`flex flex-gap-medium`}>
                                                <ChangeRegistrationParticipantDialog
                                                    eventId={id}
                                                    registrationRow={registration}
                                                    availableDistances={distances}
                                                    availableParticipants={allAvailableParticipants}
                                                    onUpdate={() => fetchRegistrationsAfterUpdate()}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Edit16Filled/>} />
                                                    }
                                                />
                                                <ConfirmDialog
                                                    title={"Item verwijderen?"}
                                                    description={`Weet u zeker dat deze inschrijving met naam '${createParticipantText(registration.participant1, registration.participant2, registration.participant3, registration.participant4)}' moet worden verwijderd? Deze actie kan niet ongedaan worden gemaakt`}
                                                    buttonText={"Verwijderen"}
                                                    onConfirm={() => deleteRegistrationItem(registration)}
                                                    buttonColor={"red"}
                                                    appearance={`subtle`}
                                                    buttonSize={`small`}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>}/>
                                                    }
                                                />
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </>
                }
            </>
        }/>
    )
}

export default RegistrationParticipantView