import {
    Button, Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger,
    Label
} from "@fluentui/react-components";
import React, {useState} from "react";
import RaceSelectBox from "../racesystem/RaceSelectBox";
import MessageBox from "../MessageBar";
import ProgressRing from "../ProgressRing";
import {moveScheduleItem} from "../../handlers/schedulehandler";

const MoveScheduleItemDialog = ({ button, scheduleData, eventId, afterUpdate }) => {
    const [scheduleItemIdFrom, setScheduleItemIdFrom] = useState([]);
    const [scheduleItemIdDest, setScheduleItemIdDest] = useState([]);
    const [updateTime, setUpdateTime] = useState(true);
    const [isOpen, setIsOpen] = useState(false);
    const [errorMsg, setErrorMsg] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const moveRace = async () => {
        setIsLoading(true);
        try {
            const result = await moveScheduleItem(scheduleItemIdFrom[0], scheduleItemIdDest[0], eventId, updateTime);

            setIsLoading(false);

            if (!result) {
                setErrorMsg(`An unexpected error occurred.`);
            } else {
                if (afterUpdate) afterUpdate();

                setIsOpen(false);
            }

        } catch (error) {
            setIsLoading(false);

            console.error(error);
            setErrorMsg(`An error occurred: ${error}`);
        }
    }

    return (
        <>
            <Dialog open={isOpen} onOpenChange={(e, data) => setIsOpen(data.open)}>
                <DialogTrigger>
                    {button}
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>Move Race</DialogTitle>
                    <DialogContent>
                        {errorMsg && <MessageBox title={errorMsg} intent={"error"} />}
                        <div className={`dialog-content-container`}>
                            <div className={`dialog-content-item`}>
                                <Label>Race to move:</Label>
                                <RaceSelectBox
                                    raceIds={scheduleItemIdFrom}
                                    setRaceIds={setScheduleItemIdFrom}
                                    scheduleData={scheduleData}
                                    showFinishedRaces={true}
                                    showStartedRaces={true}
                                    showNotStartedRaces={true}
                                />
                                <p className={`text-sub text-no-margin`}>Select 1 race</p>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Destination:</Label>
                                <RaceSelectBox
                                    raceIds={scheduleItemIdDest}
                                    setRaceIds={setScheduleItemIdDest}
                                    scheduleData={scheduleData}
                                    showFinishedRaces={true}
                                    showStartedRaces={true}
                                    showNotStartedRaces={true}
                                />
                                <p className={`text-sub text-no-margin`}>Select 1 race</p>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Checkbox as={`input`} checked={updateTime} onChange={() => setUpdateTime(!updateTime)} label={`Update Schedule Time`}/>
                                <p className={`text-sub text-no-margin`}>Do not select if the race will be moved between different days.</p>
                            </div>
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger>
                            <Button as={`a`} className={`button`}>
                                Cancel
                            </Button>
                        </DialogTrigger>
                        <Button as={`a`}
                                className={`button`}
                                appearance={`primary`}
                                disabled={scheduleItemIdFrom.length !== 1 || scheduleItemIdDest.length !== 1}
                                onClick={moveRace}>
                            {isLoading ? <ProgressRing /> : `Generate`}
                        </Button>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    )
}

export default MoveScheduleItemDialog