import {Button, TableCell, TableRow} from "@fluentui/react-components";
import {useEffect, useState} from "react";
import ProgressRing from "../../ProgressRing";
import {useParams} from "react-router-dom";
import {
    deleteCategoryFromDatabase,
    fetchCategoriesFromDatabase
} from "../../../handlers/databasehandler";
import MessageBox from "../../MessageBar";
import * as React from "react";
import {Delete16Filled, Edit16Filled} from "@fluentui/react-icons";
import ChangeRegistrationCategoryDialog from "./ChangeRegistrationCategoryDialog";
import InnerBodyContainer from "../../InnerBodyContainer";
import RegistrationSettingsTable from "../RegistrationSettingsTable";
import ConfirmDialog from "../../ConfirmDialog";

const RegistrationCategoryView = () => {
    const {id} = useParams();
    const [isLoading, setIsLoading] = useState(true);
    const [categories, setCategories] = useState([]);
    const [errorMsg, setErrorMsg] = useState(null);

    async function fetchCategories() {
        return await fetchCategoriesFromDatabase(id);
    }

    async function deleteCategories(categoryId) {
        const result = await deleteCategoryFromDatabase(id, categoryId);
        if (!result) {
            setErrorMsg("Error deleting category.");
            return;
        }

        fetchCategoriesAfterOperation();
    }

    function fetchCategoriesAfterOperation() {
        fetchCategories().then((data) => setCategories(data));
    }

    useEffect(() => {
        fetchCategories().then((data) => {
            setIsLoading(false);

            if (data == null) {
                setErrorMsg("Error loading genders");
                return;
            }

            setCategories(data);
        });
    }, []);

    return (
        <InnerBodyContainer content={
            <>
                { isLoading && <ProgressRing/>}
                { !isLoading && errorMsg != null &&
                    <MessageBox
                        intent={"error"}
                        title={"An error occurred:"}
                        message={errorMsg}
                        closeButtonFunction={() => { setErrorMsg(null) }}
                    />
                }
                { !isLoading && errorMsg == null &&
                    <>
                        <RegistrationSettingsTable title={`Categories`} tableRows={
                            categories.map((category, index) => (
                                <TableRow key={`${category.id}-${index}`}>
                                    <TableCell>{category.category}</TableCell>
                                    <TableCell>
                                        <div className={`flex flex-gap-medium`}>
                                            <ChangeRegistrationCategoryDialog
                                                eventId={id}
                                                category={category}
                                                onUpdate={() => fetchCategoriesAfterOperation()}
                                                altButton={
                                                    <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Edit16Filled/>}/>
                                                }
                                            />
                                            <ConfirmDialog
                                                title={"Item verwijderen?"}
                                                description={`Weet u zeker dat '${category.category}' moet worden verwijderd? Deze actie kan niet ongedaan worden gemaakt`}
                                                buttonText={"Verwijderen"}
                                                onConfirm={() => deleteCategories(category.id)}
                                                buttonColor={"red"}
                                                appearance={`subtle`}
                                                buttonSize={`small`}
                                                altButton={
                                                    <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>}/>
                                                }
                                            />
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ))
                        }/>
                    </>
                }
                <div style={{display: "flex"}}>
                    <ChangeRegistrationCategoryDialog
                        isNew={true}
                        eventId={id}
                        onUpdate={() => fetchCategoriesAfterOperation()}
                    />
                </div>
            </>
        }></InnerBodyContainer>
    );
}

export default RegistrationCategoryView;