import {
    Button, Combobox,
    Dialog, DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger, Input, Label,
    Table, TableBody, TableCell,
    TableHeader, TableHeaderCell, TableRow, Option, Select
} from "@fluentui/react-components";
import MessageBox from "../MessageBar";
import {useState} from "react";
import SingleScheduleParticipant, {ParticipantTableColumns} from "../../models/SingleScheduleParticipant";
import {Add16Filled, Delete16Filled} from "@fluentui/react-icons";
import {updateRaceFromSchedule} from "../../handlers/schedulehandler";
import ProgressRing from "../ProgressRing";
import {getParticipantString} from "./ScheduleItem";

const UpdateScheduleParticipantDialog = ({button, isNew, scheduleItem, registrationsForRace, scheduleItemParticipants, start_nr, onUpdate}) => {
    const [errorMsg, setErrorMsg] = useState(null);
    const [participants, setParticipants] = useState(isNew ? [] : scheduleItemParticipants);
    const [savedParticipants, setSavedParticipants] = useState([]);
    const [open, setOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [startNR, setStartNR] = useState(isNew ? getNewStartNr() : (start_nr || start_nr === 0 ? start_nr : 1));

    function setStartNrField(text) {
        if (isNaN(text) && text !== 0) {
            return;
        }

        setStartNR(text);

        if (!isStartNrAvailable(text)) {
            setErrorMsg("Invalid Start NR");
            return;
        }

        setErrorMsg(null);
    }

    function setParticipantFromRegisteredParticipants(id) {
        const registration = registrationsForRace.find((r) => r.id === id);

        if (!registration || !(registration.participants) || !(registration.participants instanceof Array) || registration.participants.length === 0) {
            return;
        }

        setParticipants(registration.participants);
    }

    function setSelectedParticipant({name, id}, index) {

        setErrorMsg(null);

        if (index === null || index === undefined) return;

        if (id) {
            //TO-DO v0.1.3
            // setParticipants(participants.map((participant, p_index) => {
            //     if (p_index === index) {
            //         return autoCompleteParticipants[p_index];
            //     } else {
            //         return participant;
            //     }
            // }));
            return;
        }

        setParticipants(prev => prev.map((p, i) => (i === index ? name : p)));

        //
        if (name || name === "") {
            const club_name_split = name.split(" - ");
            const name_split = club_name_split.shift();
            let club = club_name_split.pop();

            if (!club && name.includes(" - ")) {
                club = "";
            }

            const separated_names = name_split.split(" ");
            const first_name = separated_names.shift();
            const last_name = separated_names.join(' ');

            if (name !== "" && (!club || !first_name || !last_name)) {
                setErrorMsg("Participants value are not valid");
            }
        }
    }

    function addParticipant() {
        setErrorMsg(null);
        setParticipants([...participants, ""]);
    }

    function removeParticipant(index) {
        setErrorMsg(null);
        setParticipants(participants.filter((participant, p_index) => p_index !== index));
    }

    async function saveParticipant() {
        if (scheduleItem.id === null || scheduleItem.id === undefined || !areParticipantsReadyForSave() || !isStartNrAvailable(startNR)) return;

        setIsLoading(true);

        const parsedParticipants = participants.map(p => {
            if (p instanceof SingleScheduleParticipant) return p;

            const club_name_split = p.split(" - ");
            const name_part = club_name_split[0] || "";
            const club = club_name_split.length > 1 ? club_name_split.pop() : "";
            const names = name_part.trim().split(" ");
            const first = names.shift() || "";
            const last = names.join(" ") || "";

            return new SingleScheduleParticipant({
                first_name: first,
                last_name: last,
                short_club_name: club
            });
        });

        let scheduleItemToUpdate;

        if (isNew) {
            scheduleItemToUpdate = {
                participants: [...scheduleItem.participants, {
                    start_nr: startNR,
                    participants: parsedParticipants
                }],
            };
        } else {
            scheduleItemToUpdate = {
                participants: scheduleItem.participants.map((participant) => {
                    if (participant.start_nr === start_nr) {
                        return {
                            start_nr: startNR,
                            participants: parsedParticipants
                        };
                    }

                    return participant;
                })
            };

        }

        updateRaceFromSchedule(scheduleItem.id, scheduleItemToUpdate).then((result) => {
            setIsLoading(false);
            if(!result) {
                setErrorMsg("Error saving schedule item");
                return;
            }

            setParticipants(parsedParticipants);
            setSavedParticipants(parsedParticipants);

            if (onUpdate) {
                onUpdate();
            }

            if (isNew) {
                setStartNR(startNR + 1);
            }

            setOpen(false);
        });
    }

    function getNewStartNr() {
        if (scheduleItem.participants.length === 0) {
            return 1;
        }

        const orderedParticipants = scheduleItem.participants.sort((a, b) => parseInt(a.start_nr) - parseInt(b.start_nr));

        return parseInt(orderedParticipants[orderedParticipants.length - 1].start_nr) + 1;
    }

    function isStartNrAvailable(text) {
        if (!text && text !== 0) {
            return false;
        }

        const filteredParticipants = scheduleItem.participants.filter((participant) => {
            return parseInt(participant.start_nr) === parseInt(text) && parseInt(participant.start_nr) !== parseInt(start_nr);
        });

        return filteredParticipants.length === 0;
    }

    function areParticipantsReadyForSave() {
        if (participants.length !== 0) {
            for (let participant of participants) {
                if (!participant || (participant instanceof String)) {
                    setErrorMsg("Participants value are not valid");
                    return false;
                }
            }
        }
        return true;
    }

    function getParticipantText(participant) {
        if (!participant || !((participant instanceof SingleScheduleParticipant))) {
            return;
        }

        if (participant instanceof String) {
            return participant;
        }

        return `${participant.first_name} ${participant.last_name} - ${participant.short_club_name}`;
    }

    const getWidthForColumn = (columnKey) => {
        const column = ParticipantTableColumns.find(col => col.columnKey === columnKey);
        if (column) {
            return `${(column.span / 12) * 100}%`;
        }
        return 'auto';
    };

    function onDialogOpenChange(event, data) {
        setOpen(data.open);
        if (data.open || participants.length === 0) {
            return;
        }

        if (savedParticipants.length === 0 && areParticipantsReadyForSave()) {
            setParticipants(scheduleItemParticipants);
            setErrorMsg(null);
        } else {
            setParticipants(savedParticipants);
            setErrorMsg(null);
        }
    }

    return (
      <>
          <Dialog open={open} onOpenChange={onDialogOpenChange}>
              <DialogTrigger>
                  {button}
              </DialogTrigger>
              <DialogSurface className={`dialog`}>
                  <DialogTitle>
                      { isNew ? <>Add Participant Item</> : <>Update Participant Item</>}
                  </DialogTitle>
                  <DialogContent>
                      {
                          errorMsg && <MessageBox title={errorMsg} intent={"error"}/>
                      }
                      <div className={`dialog-content-container`}>
                          <div className={`dialog-content-item`}>
                              <Label>Start NR:</Label>
                              <Input
                                  type={`number`}
                                  value={startNR}
                                  onInput={(e) => setStartNrField(e.target.value)}
                                  placeholder={`Start NR`}
                              />
                          </div>
                          <div className={`dialog-content-item`}>
                              <Label>Registered Participants:</Label>
                              <Combobox
                                onOptionSelect={(e, data) => setParticipantFromRegisteredParticipants(data.optionValue)}
                              >
                                  {
                                      registrationsForRace.map((r) => (
                                          <Option key={r.id} value={r.id}>
                                              { getParticipantString(r.participants) }
                                          </Option>
                                      ))
                                  }
                              </Combobox>
                          </div>
                          <Table
                              style={{tableLayout: "fixed"}}>
                              <TableHeader>
                                  <TableRow>
                                      {
                                          ParticipantTableColumns.map((column) => {
                                              return (
                                                      <TableHeaderCell key={column.columnKey}
                                                                       style={{ width: getWidthForColumn(column.columnKey) }}>
                                                          {column.label}
                                                      </TableHeaderCell>
                                              )
                                          })
                                      }
                                  </TableRow>
                              </TableHeader>
                              <TableBody>
                                  {
                                      (participants instanceof Array) && participants.map((participant, index) => {
                                        return (
                                            <TableRow key={index}>
                                                <TableCell>
                                                    <div className={`dialog-content-container`}>
                                                        <Input
                                                            value={getParticipantText(participants[index])}
                                                            onInput={(e) => setSelectedParticipant({name: e.target.value}, index)}
                                                            placeholder={`Participant`}
                                                        />
                                                    </div>

                                                    {/*<Combobox*/}
                                                    {/*    value={getFullName(participants[index])}*/}
                                                    {/*    onOptionSelect={(e, data) => setSelectedParticipant({id: data.optionValue}, index)}*/}
                                                    {/*    onInput={(e) => setSelectedParticipant({name: e.target.value}, index)}*/}
                                                    {/*    placeholder={`Select Participant`}*/}
                                                    {/*    freeform*/}
                                                    {/*    autocomplete*/}
                                                    {/*>*/}
                                                    {/*    {*/}
                                                    {/*        Array.from(autoCompleteParticipants).map((participant) => (*/}
                                                    {/*            <Option key={participant.id} value={participant.id}>*/}
                                                    {/*                { getFullName(participant) }*/}
                                                    {/*            </Option>*/}
                                                    {/*        ))*/}
                                                    {/*    }*/}
                                                    {/*</Combobox>*/}
                                                </TableCell>
                                                <TableCell>
                                                    <Button as={`a`}
                                                            className={`button`}
                                                            appearance={`subtle`}
                                                            size={`small`}
                                                            onClick={() => removeParticipant(index)}>
                                                        <Delete16Filled/>
                                                    </Button>
                                                </TableCell>
                                            </TableRow>
                                        )
                                      })
                                  }
                              </TableBody>
                          </Table>

                      </div>
                      <Button as={`a`}
                              className={`button`}
                              appearance={`primary`}
                              onClick={addParticipant}>
                          <Add16Filled/> Add row
                      </Button>
                  </DialogContent>
                  <DialogActions>
                      <DialogTrigger>
                          <Button as={`a`} className={`button`} appearance={`outline`}>
                              Cancel
                          </Button>
                      </DialogTrigger>
                      <Button as={`a`}
                              className={`button`}
                              appearance={`primary`}
                              disabled={errorMsg || isLoading}
                              onClick={saveParticipant}>
                          { isLoading && <ProgressRing/> }
                          { !isLoading && `Save` }
                      </Button>
                  </DialogActions>

              </DialogSurface>
          </Dialog>
      </>
    );
}

export default UpdateScheduleParticipantDialog;