import {
    Button, Combobox,
    Dialog, DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger,
    Label, Option
} from "@fluentui/react-components";
import {useState} from "react";
import Participant from "../../../models/Participant";
import MessageBox from "../../MessageBar";
import Distance from "../../../models/Distance";
import {updateRegistrationFromDatabase} from "../../../handlers/databasehandler";

const ChangeRegistrationParticipantDialog = ({eventId, registrationRow, availableDistances, availableParticipants, onUpdate, altButton}) => {
    const amount = registrationRow.distance.Boat.amount_of_people;
    const initialIds = [
        registrationRow.participant1,
        registrationRow.participant2,
        registrationRow.participant3,
        registrationRow.participant4
    ].slice(0, amount);
    const initialTexts = [
        registrationRow.participant1?.fullName || "",
        registrationRow.participant2?.fullName || "",
        registrationRow.participant3?.fullName || "",
        registrationRow.participant4?.fullName || "",
    ]

    function generateDistanceText(distance) {
        return `${distance.Boat.boat} ${distance.Gender.gender} ${distance.Categories.category} ${distance.distance}`;
    }

    const [participantIds, setParticipantIds] = useState(initialIds);
    const [participantTexts, setParticipantTexts] = useState(initialTexts);
    const [warningMsg, setWarningMsg] = useState(null);
    const [distance, setDistance] = useState(registrationRow ? registrationRow.distance : null);
    const [distanceText, setDistanceText] = useState(registrationRow ? generateDistanceText(registrationRow.distance) : "");


    function setParticipantFields(index, value) {
        if (value instanceof Participant) {
            const newIds = [...participantIds];
            newIds[index] = value;
            setParticipantIds(newIds);
            setWarningMsg(null);
        } else if (warningMsg === null) {
            setWarningMsg("A name of the dropdown must be selected to save");
        }


        const newParticipantTexts = [...participantTexts];
        newParticipantTexts[index] = value instanceof Participant ? value.fullName : value;
        setParticipantTexts(newParticipantTexts);
    }

    function setDistanceField(value) {
        if (value instanceof Distance) {
            setDistance(value);
            setWarningMsg(null);
        } else if (warningMsg === null) {
            setWarningMsg("A distance of the dropdown must be selected to save");
        }

        const newDistanceText = value instanceof Distance ? generateDistanceText(value) : value;
        setDistanceText(newDistanceText);
    }

    async function updateRegistrationRow() {
        if (warningMsg !== null) {
            return;
        }

        const participantsId = participantIds.map(participant => participant.id);

        const result = await updateRegistrationFromDatabase(eventId, registrationRow.id, participantsId, distance.id);

        if (!result) {
            console.error(result);
            return;
        }

        if (onUpdate) {
            onUpdate();
        }
    }

    return (
      <>
          <Dialog>
              <DialogTrigger>
                  {altButton ? altButton : <Button as={"a"} appearance={"primary"}>Wijzigen</Button>}
              </DialogTrigger>
              <DialogSurface className={`dialog`}>
                  <DialogTitle>
                      Deelnemer Wijzigen
                  </DialogTitle>
                  <DialogContent>
                      {
                          warningMsg && <MessageBox title={warningMsg} intent={"warning"}/>
                      }
                      <div className={`dialog-content-container`}>
                          {
                              Array.from({ length: amount }).map((_, index) => (
                                  <div className={`dialog-content-item`} key={index}>
                                      <Label>
                                          Participant {index + 1}
                                      </Label>
                                      <Combobox
                                          placeholder="Search participant"
                                          value={participantTexts[index]}
                                          onOptionSelect={(e, data) => setParticipantFields(index, data.optionValue)}
                                          onInput={(e) => setParticipantFields(index, e.target.value)}
                                          freeform
                                          autocomplete
                                      >
                                          {Array.from(availableParticipants).map((participant) => (
                                              <Option key={participant.id} value={participant}>
                                                  {participant.fullName} ({participant.birthyear})
                                              </Option>
                                          ))}
                                      </Combobox>
                                  </div>
                              ))
                          }
                          <div className={`dialog-content-item`}>
                              <Label>
                                  Category
                              </Label>
                              <Combobox
                                  placeholder="Search category"
                                  value={distanceText}
                                  onOptionSelect={(e, data) => setDistanceField(data.optionValue)}
                                  onInput={(e) => setDistanceField(e.target.value)}
                                  freeform
                                  autocomplete
                              >
                                    {Array.from(availableDistances).filter((distance) => distance.Boat.amount_of_people === registrationRow.distance.Boat.amount_of_people).map((distance) => (
                                        <Option key={distance.id} value={distance}>
                                            {generateDistanceText(distance)}
                                        </Option>
                                    ))}
                              </Combobox>
                          </div>
                      </div>
                  </DialogContent>
                  <DialogActions>
                      <DialogTrigger disableButtonEnhancement>
                          <Button as={"a"} className={`button`} appearance="secondary">Annuleren</Button>
                      </DialogTrigger>
                      <DialogTrigger>
                          <Button as={"a"} className={`button`} appearance="primary" onClick={() => updateRegistrationRow()}>
                              { `Wijzigen` }
                          </Button>
                      </DialogTrigger>
                  </DialogActions>
              </DialogSurface>
          </Dialog>
      </>
    );
}

export default ChangeRegistrationParticipantDialog;