//GENDERS
export const fetchGendersFromDatabase = async (eventId) => {
    try {
        const result = await supabase.from("Gender")
            .select("*")
            .eq("event_id", eventId)
            .order(`gender`);

        if (!result || !result.data || !(result.data instanceof Array)) {
            console.error("Error fetching objects");
            return null;
        }
        return result.data.map((gender) => new Gender(gender.id, gender.gender));
    } catch (error) {
        console.error(error);
        return null;
    }
}

