import {formatDateForTitle} from "./datehandler";
import {downloadFile} from "./downloadhandler";

const CSV_MODES = {
    detailed: "detailed",
    titles: "titles",
};

function getTitleString(scheduleItem) {
    if (!scheduleItem) {
        return "";
    }

    return `Race ${scheduleItem.race_nr} - ${formatDateForTitle(scheduleItem.planned_start_time)} - ${scheduleItem.boat?.boat} - ${scheduleItem.gender?.gender} - ${scheduleItem.category?.category} - ${scheduleItem.distance?.distance}${scheduleItem.race_type ? ` - ${scheduleItem.race_type}` : ""}`;
}

function getParticipantString(participants) {
    if (!Array.isArray(participants) || participants.length === 0) {
        return "-";
    }

    return participants
        .map((participant) => participant.first_name + " " + participant.last_name + (participant.short_club_name?.length === 0 ? "" : " - " + participant.short_club_name))
        .join(", ");
}

function isValidDate(dateValue) {
    if (!dateValue) {
        return false;
    }

    const parsed = new Date(dateValue);
    return !Number.isNaN(parsed.getTime());
}

function padTimeValue(value) {
    return value.toString().padStart(2, "0");
}

function formatElapsedTime(raceStartTime, finishTime) {
    if (!isValidDate(finishTime)) {
        return "-";
    }

    if (!isValidDate(raceStartTime)) {
        const finishDate = new Date(finishTime);

        return `${padTimeValue(finishDate.getHours())}:${padTimeValue(finishDate.getMinutes())}:${padTimeValue(finishDate.getSeconds())}.${finishDate.getMilliseconds().toString().padStart(3, "0")}`;
    }

    const diffMs = new Date(finishTime).getTime() - new Date(raceStartTime).getTime();

    if (Number.isNaN(diffMs) || diffMs < 0) {
        return "-";
    }

    const hours = Math.floor(diffMs / 3_600_000);
    const minutes = Math.floor((diffMs % 3_600_000) / 60_000);
    const seconds = Math.floor((diffMs % 60_000) / 1_000);
    const milliseconds = diffMs % 1_000;

    return `${padTimeValue(hours)}:${padTimeValue(minutes)}:${padTimeValue(seconds)}.${milliseconds.toString().padStart(3, "0")}`;
}

function getParticipantsByStartNr(scheduleItem) {
    const participantMap = new Map();

    (scheduleItem.participants || []).forEach((lane) => {
        if (lane?.start_nr === undefined || lane?.start_nr === null) {
            return;
        }

        participantMap.set(String(lane.start_nr), lane.participants || []);
    });

    return participantMap;
}

function escapeCsvValue(value) {
    const text = value ?? "";
    const escaped = String(text).replace(/"/g, '""');

    return `"${escaped}"`;
}

function toCsvRow(values) {
    return values.map((value) => escapeCsvValue(value)).join(",");
}

function getDetailedCsvLines(scheduleData) {
    const lines = [];

    lines.push(toCsvRow([
        "Item",
        "Start nr",
        "Uitslag",
        "Time",
        "Deelnemer(s)",
    ]));

    scheduleData.forEach((scheduleItem) => {
        lines.push(toCsvRow([
            getTitleString(scheduleItem),
            "",
            "",
            "",
            "",
        ]));

        const results = Array.isArray(scheduleItem.results) ? scheduleItem.results : [];

        if (results.length > 0) {
            const participantsByStartNr = getParticipantsByStartNr(scheduleItem);

            results.forEach((result, index) => {
                const isOrderText = Number.isNaN(Number(result.order));

                lines.push(toCsvRow([
                    "  Result",
                    result.start_nr ?? "",
                    index + 1,
                    isOrderText ? (result.order ?? "") : formatElapsedTime(scheduleItem.race_start_time, result.finish_time),
                    getParticipantString(participantsByStartNr.get(String(result.start_nr)) || []),
                ]));
            });

            lines.push(toCsvRow(["", "", "", "", ""]));

            return;
        }

        const participantRows = Array.isArray(scheduleItem.participants) ? scheduleItem.participants : [];

        if (participantRows.length === 0) {
            lines.push(toCsvRow([
                "  Entry",
                "",
                "",
                "",
                "Geen deelnemers of uitslagen",
            ]));

            lines.push(toCsvRow(["", "", "", "", ""]));

            return;
        }

        participantRows.forEach((lane) => {
            lines.push(toCsvRow([
                "  Entry",
                lane.start_nr ?? "",
                "",
                "",
                getParticipantString(lane.participants),
            ]));
        });

        lines.push(toCsvRow(["", "", "", "", ""]));
    });

    return lines;
}

function getTitleCsvLines(scheduleData) {
    const lines = [toCsvRow(["Title"])];

    scheduleData.forEach((scheduleItem) => {
        lines.push(toCsvRow([getTitleString(scheduleItem)]));
    });

    return lines;
}

function buildCsv(scheduleData, mode) {
    const data = Array.isArray(scheduleData) ? scheduleData : [];

    if (mode === CSV_MODES.titles) {
        return getTitleCsvLines(data).join("\n");
    }

    return getDetailedCsvLines(data).join("\n");
}

async function generateScheduleCsv(scheduleData, {filename, mode, warningContext}) {
    if (!scheduleData?.length) {
        console.warn(`${warningContext}: no schedule data provided`);
        return;
    }

    const csv = buildCsv(scheduleData, mode);
    const csvBlob = new Blob([`\uFEFF${csv}`], {type: "text/csv;charset=utf-8"});

    downloadFile(csvBlob, filename);
}

export async function generateScheduleDetailedCsv(scheduleData) {
    await generateScheduleCsv(scheduleData, {
        filename: "schedule_detailed.csv",
        mode: CSV_MODES.detailed,
        warningContext: "generateScheduleDetailedCsv",
    });
}

export async function generateScheduleTitleOverviewCsv(scheduleData) {
    await generateScheduleCsv(scheduleData, {
        filename: "schedule_titles.csv",
        mode: CSV_MODES.titles,
        warningContext: "generateScheduleTitleOverviewCsv",
    });
}

