const sortResultsByOrder = (items) => {
    if (!Array.isArray(items)) {
        return [];
    }

    return items.sort((a, b) => {
        const valA = parseInt(a.order, 10);
        const valB = parseInt(b.order, 10);

        const isANaN = isNaN(valA);
        const isBNaN = isNaN(valB);

        if (isANaN && isBNaN) return 0;
        if (isANaN) return 1;
        if (isBNaN) return -1;

        return valA - valB;
    });
};