import {Button, TableCell, TableRow} from "@fluentui/react-components";
import {useEffect, useState} from "react";
import ProgressRing from "../../ProgressRing";
import {useParams} from "react-router-dom";
import {deleteGendersFromDatabase, fetchGendersFromDatabase} from "../../../handlers/databasehandler";
import MessageBox from "../../MessageBar";
import * as React from "react";
import ChangeRegistrationGenderDialog from "./ChangeRegistrationGenderDialog";
import InnerBodyContainer from "../../InnerBodyContainer";
import {Delete16Filled, Edit16Filled} from "@fluentui/react-icons";
import RegistrationSettingsTable from "../RegistrationSettingsTable";
import ConfirmDialog from "../../ConfirmDialog";

const RegistrationGenderView = () => {
    const {id} = useParams();
    const [isLoading, setIsLoading] = useState(true);
    const [genders, setGenders] = useState([]);
    const [errorMsg, setErrorMsg] = useState(null);

    async function fetchGenders() {
        return await fetchGendersFromDatabase(id);
    }

    async function deleteGender(genderId) {
        const result = await deleteGendersFromDatabase(id, genderId);
        if (!result) {
            setErrorMsg("Error deleting gender");
            return;
        }

        fetchGendersAfterOperation();
    }

    function fetchGendersAfterOperation() {
        fetchGenders().then((data) => setGenders(data));
    }

    useEffect(() => {
        fetchGenders().then((data) => {
            setIsLoading(false);

            if (data == null) {
                setErrorMsg("Error loading genders");
                return;
            }

            setGenders(data);
        });
    }, []);

    return (
        <InnerBodyContainer content={
            <>
                { isLoading && <ProgressRing/>}
                { !isLoading && errorMsg != null &&
                    <MessageBox
                        intent={"error"}
                        title={"An error occurred:"}
                        message={errorMsg}
                        closeButtonFunction={() => { setErrorMsg(null) }}
                    />
                }
                { !isLoading && errorMsg == null &&
                    <>
                        <RegistrationSettingsTable title={`Genders`} tableRows={
                            genders.map((gender, index) => (
                                    <TableRow key={`${gender.id}-${index}`}>
                                        <TableCell>{gender.gender}</TableCell>
                                        <TableCell>
                                            <div className={`flex flex-gap-medium`}>
                                                <ChangeRegistrationGenderDialog
                                                    eventId={id}
                                                    gender={gender}
                                                    onUpdate={() => fetchGendersAfterOperation()}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Edit16Filled/>}/>
                                                    }
                                                />
                                                <ConfirmDialog
                                                    title={"Item verwijderen?"}
                                                    description={`Weet u zeker dat '${gender.gender}' moet worden verwijderd? Deze actie kan niet ongedaan worden gemaakt`}
                                                    buttonText={"Verwijderen"}
                                                    onConfirm={() => deleteGender(gender.id)}
                                                    buttonColor={"red"}
                                                    appearance={`subtle`}
                                                    buttonSize={`small`}
                                                    altButton={
                                                        <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>}/>
                                                    }
                                                />
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))
                        }/>
                    </>
                }
                <div style={{display: "flex"}}>
                    <ChangeRegistrationGenderDialog
                        isNew={true}
                        eventId={id}
                        onUpdate={() => fetchGendersAfterOperation()}
                    />
                </div>
            </>
        }></InnerBodyContainer>
    );
}

export default RegistrationGenderView;