export default class RaceEvent {
    constructor(event) {
        this.id = event?.id ?? undefined;
        this.name = event?.name ?? "";
        this.startDate = event?.startDate ?? "";
        this.endDate = event?.endDate ?? "";
        this.location = event?.location ?? "";
        this.contact_email = event?.contact_email ?? "";
        this.race_type = event?.race_type ?? "";
        this.using_wsv = event?.using_wsv ?? false;
        this.is_public = event?.is_public ?? false;
        this.registration_end = event?.registration_end ?? "";
    }
}