import React, {useState} from "react";
import {addGenderToDatabase, updateGendersFromDatabase} from "../../../handlers/databasehandler";
import {Add12Regular} from "@fluentui/react-icons";
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger, Input, Label
} from "@fluentui/react-components";

const ChangeRegistrationGenderDialog = ({eventId, gender, onUpdate, isNew = false, altButton = null}) => {
    const [genderText, setGenderText] = useState(isNew ? "" : gender.gender);

    async function updateGender() {
        updateGendersFromDatabase(eventId, gender.id, genderText).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    async function addGender() {
        addGenderToDatabase(eventId, genderText).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    return (
        <>
            <Dialog>
                <DialogTrigger>
                    { altButton ? altButton : <Button as={"a"} className={`button`} appearance={"primary"}>{ isNew ? <><Add12Regular/> Toevoegen</> : <>Wijzigen</> }</Button>}
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>{ isNew ? <>Gender Toevoegen</> : <>{gender.gender} wijzigen</>}</DialogTitle>
                    <DialogContent>
                        <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 12, marginTop: 12 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <Label style={{ width: 150 }}>Gender:</Label>
                                <Input
                                    value={genderText}
                                    onChange={(e) => setGenderText(e.target.value)}
                                    style={{ flex: 1 }}/>
                            </div>
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button as={"a"} className={`button`} appearance="secondary">Annuleren</Button>
                        </DialogTrigger>
                        <DialogTrigger>
                            <Button as={"a"} className={`button`} appearance="primary" onClick={isNew ? addGender : updateGender}>
                                { isNew ? <>Toevoegen</> : <>Wijzigen</> }
                            </Button>
                        </DialogTrigger>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
}

export default ChangeRegistrationGenderDialog;