/**
 * Constants for the finals generation methods.
 */
export const FINALS_METHOD = {
    POSITIONS: 'positions',
    ABC: 'abc',
    HASSLER: 'hassler'
};

export const FINALS_METHOD_LABELS = {
    [FINALS_METHOD.POSITIONS]: 'Main method (Positions)',
    [FINALS_METHOD.ABC]: 'A, B, C Finals (Positions)',
    [FINALS_METHOD.HASSLER]: 'Hassler series (Time)'
};

/**
 * Generates an array of lane numbers in "middle-out" order.
 * Generic for any number of lanes.
 */
export const getLanesOrder = (numLanes) => {
    const lanes = [];
    let left, right;
    const n = parseInt(numLanes);

    if (n % 2 !== 0) {
        const middle = Math.ceil(n / 2);
        lanes.push(middle);
        left = middle - 1;
        right = middle + 1;
    } else {
        left = n / 2;
        right = left + 1;
    }

    while (left >= 1 || right <= n) {
        if (left >= 1) { lanes.push(left); left--; }
        if (right <= n) { lanes.push(right); right++; }
    }
    return lanes;
};

/**
 * Calculates the mapping of participants to output races and lanes.
 */
export const generateFinalsData = (inputRaces, outputRaces, method, numLanes) => {
    let allParticipants = [];

    // 1. Process Input Races: Match Results to Participants
    inputRaces.forEach(race => {
        const results = race.results || [];
        const raceParticipants = race.participants || [];

        results.forEach(result => {
            // Find the participant group by matching start_nr (handling string/int comparison)
            const pEntry = raceParticipants.find(p => String(p.start_nr) === String(result.start_nr));

            if (pEntry && result.order > 0) {
                const combinedParticipant = {
                    ...pEntry, // Contains start_nr and the 'participants' array (the athletes)
                    order: result.order,
                    finish_time: result.finish_time,
                    _sourceRaceId: race.id
                };

                // Calculate Score
                if (method === FINALS_METHOD.HASSLER) {
                    // Hassler: (Finish Time - Race Start Time). Lower is faster.
                    const start = new Date(race.race_start_time).getTime();
                    const finish = new Date(result.finish_time).getTime();
                    combinedParticipant._score = finish - start;
                } else {
                    combinedParticipant._score = result.order;
                }

                allParticipants.push(combinedParticipant);
            }
        });
    });

    if (allParticipants.length === 0) return {};

    // 2. Sort all participants globally by their score (Rank or Time)
    allParticipants.sort((a, b) => a._score - b._score);

    const assignments = {};
    outputRaces.forEach(r => assignments[r.id] = []);

    // 3. Distribute participants to output races
    if (method === FINALS_METHOD.POSITIONS) {
        // Snake distribution for balanced heats (Semi-finals logic)
        let outIdx = 0;
        let direction = 1;

        // Group by rank to ensure ranks are split evenly
        const byRank = {};
        allParticipants.forEach(p => {
            if (!byRank[p.order]) byRank[p.order] = [];
            byRank[p.order].push(p);
        });

        Object.keys(byRank).sort((a, b) => a - b).forEach(rank => {
            byRank[rank].forEach(p => {
                assignments[outputRaces[outIdx].id].push(p);
                outIdx += direction;
                if (outIdx >= outputRaces.length) { outIdx = outputRaces.length - 1; direction = -1; }
                else if (outIdx < 0) { outIdx = 0; direction = 1; }
            });
        });
    } else {
        // ABC/Hassler: Linear fill (Final A gets top set, Final B gets next set)
        const lanesLimit = method === FINALS_METHOD.HASSLER
            ? Math.ceil(allParticipants.length / outputRaces.length)
            : parseInt(numLanes);

        outputRaces.forEach((race, i) => {
            assignments[race.id] = allParticipants.slice(i * lanesLimit, (i + 1) * lanesLimit);
        });
    }

    // 4. Assign Lanes (Middle-out + ICF Adjacency logic)
    const finalMapping = {};
    Object.keys(assignments).forEach(raceId => {
        const raceParticipants = assignments[raceId];
        const lanesOrder = getLanesOrder(numLanes || raceParticipants.length);

        // Group by rank within this specific final
        const byRank = {};
        raceParticipants.forEach(p => {
            const r = p.order;
            if (!byRank[r]) byRank[r] = [];
            byRank[r].push(p);
        });

        const laneReadyList = [];
        let rankCounter = 0;
        Object.keys(byRank).sort((a, b) => a - b).forEach(rank => {
            const group = byRank[rank];
            // Sort by source race ID to keep people from the same heat together in the pool
            group.sort((a, b) => String(a._sourceRaceId).localeCompare(String(b._sourceRaceId)));

            // ICF logic: Reverse order for every other rank to ensure participants
            // from the same source race don't end up in adjacent lanes (e.g. 4 and 5)
            if (rankCounter % 2 !== 0) group.reverse();

            laneReadyList.push(...group);
            rankCounter++;
        });

        // Map to final array structure for the database
        finalMapping[raceId] = laneReadyList.filter((p, idx) => !!lanesOrder[idx]).map((p, idx) => ({
            start_nr: lanesOrder[idx],       // Keep original or generate new if needed
            participants: p.participants, // The array of athlete objects
        }));
    });

    return finalMapping;
};