import * as React from "react";
import {useEffect, useState} from "react";
import ProgressRing from "../ProgressRing";
import MessageBar from "../MessageBar";
import {getSchedule, isScheduleItemFinished} from "../../handlers/schedulehandler";
import Schedule, {RaceOverviewColumns} from "../../models/Schedule";
import {
    Badge,
    Button,
    Table,
    TableBody,
    TableCell,
    TableHeader,
    TableHeaderCell,
    TableRow
} from "@fluentui/react-components";
import {ArrowClockwise16Regular,} from "@fluentui/react-icons";
import {navigateToPage} from "../../handlers/routehandler";
import {getTitleString} from "../schedule/ScheduleItem";

const AllRacesOverview = ({eventId, buttonText, buttonRoute, showNotStartedRaces = true, showStartedRaces = true, showFinishedRaces = true}) => {
    const [scheduleData, setScheduleData] = useState({});
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    function fetchScheduleAtReload() {
        getSchedule(eventId, true).then((data) => {
            if (!data) {
                setError(`An error occurred fetching schedule data`);
                return;
            }

            setScheduleData(sortSchedule(data));
        });
    }

    useEffect(() => {
        setIsLoading(true);
        getSchedule(eventId, true).then((data) => {
            setIsLoading(false);

            if (!data) {
                setScheduleData([]);
                setError(`An error occurred while fetching schedule data`);
                return;
            }

            setScheduleData(sortSchedule(data));
            setError(null);
        });
    }, []);


    const showRace = (scheduleItem) => {
        if (!scheduleItem || !(scheduleItem instanceof Schedule)) {
            return false;
        }

        const hasStarted = scheduleItem.race_start_time != null;
        const isFinished = isScheduleItemFinished(scheduleItem);
        const isNotStarted = !hasStarted;

        if (showNotStartedRaces && isNotStarted) return true;
        if (showFinishedRaces && isFinished) return true;
        if (showStartedRaces && hasStarted && !isFinished) return true;

        return !showNotStartedRaces && !showStartedRaces && !showFinishedRaces;
    }

    const sortSchedule = (schedule) => {
        if (!Array.isArray(schedule)) return [];

        return [...schedule].sort((a, b) => {
            // 1. Define the Priority Rank
            // We assign a numeric rank to the statuses to make comparison easy.
            const getStatusRank = (item) => {
                const hasStarted = item.race_start_time != null;
                const isFinished = isScheduleItemFinished(item);

                if (!hasStarted) return 1;           // Top: Not started
                if (hasStarted && !isFinished) return 2; // Middle: Started/Running
                return 3;                            // Bottom: Finished
            };

            const rankA = getStatusRank(a);
            const rankB = getStatusRank(b);

            // 2. Primary Sort: By Status Rank
            // If the ranks are different, sort by rank (1 comes before 2, etc.)
            if (rankA !== rankB) {
                return rankA - rankB;
            }

            // 3. Secondary Sort: By Race Number
            // If they have the same status, sort by race_nr
            const nrA = parseInt(a.race_nr) || 0;
            const nrB = parseInt(b.race_nr) || 0;

            return nrA - nrB;
        });
    }

    const getWidthForColumn = (columnKey) => {
        const column = RaceOverviewColumns.find(col => col.columnKey === columnKey);
        if (column) {
            return `${(column.span / 12) * 100}%`;
        }
        return 'auto';
    };

    return (
        <>
            { isLoading &&
                <>
                    <ProgressRing/>
                </>
            }
            { !isLoading && error &&
                <>
                    <MessageBar title={error} intent={`error`} closeButtonFunction={ () => setError(null) } />
                </>
            }
            { !isLoading &&
                <>
                    <div className={`flex`}>
                        <Button as={`a`} appearance={`outline`} className={`button`} onClick={ () => fetchScheduleAtReload() }>
                            <ArrowClockwise16Regular/> Reload
                        </Button>
                    </div>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                {RaceOverviewColumns.map((column) => (
                                    <TableHeaderCell
                                        key={column.columnKey}
                                        style={{ width: getWidthForColumn(column.columnKey) }}
                                    >
                                        <b>{column.label}</b>
                                    </TableHeaderCell>
                                ))}
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {
                                scheduleData.filter((race) => race instanceof Schedule && showRace(race)).map((race) => (
                                    <TableRow key={race.id}>
                                        <TableCell>
                                            <div className={`flex flex-wrap flex-gap-small`}>
                                                {
                                                    race.race_start_time && !isScheduleItemFinished(race) &&
                                                    <>
                                                        <Badge appearance="filled" color="warning">
                                                            Started
                                                        </Badge>
                                                    </>
                                                }
                                                {
                                                    isScheduleItemFinished(race) &&
                                                    <>
                                                        <Badge appearance="filled" color="success">
                                                            Finished
                                                        </Badge>
                                                    </>
                                                }
                                                { getTitleString(race) }
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <Button className={`button`} as={`a`} appearance={`subtle`} onClick={() => navigateToPage(`${buttonRoute}/${race.id}`)}>
                                                {buttonText}
                                            </Button>
                                        </TableCell>
                                    </TableRow>
                                ))
                            }
                        </TableBody>
                    </Table>
                </>
            }
        </>
    );
}

export default AllRacesOverview;