import {
    addEventToDatabase, deleteEventFromDatabase,
    fetchEventByIdFromDatabase,
    fetchEventsFromDatabase,
    updateEventToDatabase
} from "./databasehandler";
import RaceEvent from "../models/Event";
import {getData, saveData} from "./filehandler";

const eventKey = `events`;

export const fetchEvents = async () => {
    const data = await fetchEventsFromDatabase();

    if (!data) {
        return getData(eventKey) ?? [];
    }

    saveData(eventKey, data);

    return data.map((event) => new RaceEvent(event));
}

export const fetchEventById = async (eventId) => {
    const data = await fetchEventByIdFromDatabase(eventId);

    if (!data) {
        const localEvents = await getData(eventKey) ?? [];
        return localEvents.filter((event) => event.eventId === eventId).at(0);
    }

    return new RaceEvent(data);
}

export const getAllEventIDs = () => {
    const result = getData("events");

    if (result == null)
        return null;

    return result.map(e => parseInt(e.id));
}

export const addEvent = async (event) => {
    const result = await addEventToDatabase(event);

    if (result) {
        saveData("events", [...getData(eventKey), event]);
    }

    return result;
}

export const updateEvent = async (id, event) => {
    const result = await updateEventToDatabase(id, event);

    if (result) {
        saveData("events", [...getData(eventKey).filter((e) => e.id !== id), event]);
    }

    return result;
}

export const deleteEvent = async (id) => {
    const result = await deleteEventFromDatabase(id);

    if (result) {
        saveData("events", [...getData(eventKey).filter((e) => e.id !== id)]);
    }

    return result;
}