import html2pdf from "html2pdf.js";
import SingleScheduleParticipant from "../models/SingleScheduleParticipant";

/**
 * registrationCostsPdfHandler.js
 *
 * Generates a registration-costs PDF using html2pdf.
 * One page (or more if long) per club.
 *
 * ACTUAL DATA SHAPES (verified from console logs):
 *
 * scheduleData: array of race items, each shaped as:
 * {
 *   id, race_nr, planned_start_time,
 *   boat:     { id, boat, amount_of_people },
 *   gender:   { id, gender },
 *   category: { id, category },
 *   distance: { id, distance },
 *   participants: [
 *     {
 *       start_nr: number,
 *       participants: [   // <-- flat participant objects
 *         {
 *           id: number | null,       // null for manually-added entries
 *           first_name: string,
 *           last_name:  string,
 *           short_club_name: string, // can be ""
 *           club_id: number | null,
 *         }
 *       ]
 *     }
 *   ]
 * }
 *
 * registrations: array of registration objects, each shaped as:
 * {
 *   id: number,
 *   participant_id, participant_id2, participant_id3, participant_id4,
 *   participant1: { id, first_name, last_name, club: { id, club, shortClub } },
 *   participant2..4: { ... } | null,
 *   distance: { id, distance, Gender, Categories, Boat }
 * }
 *
 * LOGIC:
 *   - The schedule is the source of truth. We iterate race slots, not registrations.
 *   - Each race slot (start_nr entry) = one PDF row, containing one or more participants.
 *   - Club is derived from the slot's participants: prefer short_club_name, fall back to club_id.
 *   - A slot is LATE when NONE of its participants have an id that appears as a
 *     participant_id in the registrations list. Manually-added entries (id: null) are
 *     always considered late since they were never formally registered.
 *   - Cost is looked up via costMatrix[categoryId][boatId] from the race-level category/boat.
 */

// ── Helpers ────────────────────────────────────────────────────────────────────

function formatEuro(amount) {
    return `€ ${parseFloat(amount || 0).toFixed(2).replace(".", ",")}`;
}

/**
 * Builds a Set of participant ids that exist in the formal registrations list.
 * Keyed as the raw number so we can compare directly against participant.id.
 *
 * @param {Array} registrations
 * @returns {Set<number>}
 */
function buildRegisteredParticipantIdSet(registrations) {
    const set = new Set();
    if (!Array.isArray(registrations)) return set;

    for (const reg of registrations) {
        [reg.participant_id, reg.participant_id2, reg.participant_id3, reg.participant_id4]
            .filter((pid) => pid != null)
            .forEach((pid) => set.add(pid));
    }

    return set;
}

/**
 * Returns true when a slot is a late registration.
 * A slot is late when:
 *   - All its participants have id === null (manually added), OR
 *   - None of its participant ids appear in the registered participant id set.
 *
 * @param {SingleScheduleParticipant} slotParticipant  – flat participant objects in this slot
 * @param {Set<number>}   registeredIdSet
 * @returns {boolean}
 */
function isLateSlot(slotParticipant, registeredIdSet) {
    const withId = slotParticipant.id != null ? [slotParticipant] : [];

    // Fully manually-added entry → always late
    if (withId.length === 0) return true;

    // Late if none of the ids are in the formal registration list
    return !withId.some((p) => registeredIdSet.has(p.id));
}

/**
 * Derives the club label for a slot from its participants.
 * Priority: short_club_name (first non-empty) → club_id as string → "Unknown club"
 *
 * @param {Participant} slotParticipant
 * @returns {string}
 */
function getClubFromSlot(slotParticipant) {
    if (!slotParticipant && !(slotParticipant instanceof SingleScheduleParticipant)) return "Unknown club";

    // Try short_club_name first
    if (slotParticipant?.short_club_name) return slotParticipant.short_club_name.trim();

    // Fall back to club_id as a label (will be the same club, just no short name stored)
    if (slotParticipant?.club_id) return `Club #${slotParticipant.club_id}`;

    return "Unknown club";
}

/**
 * Builds a display string for a slot's participants.
 *
 * @param {SingleScheduleParticipant} slotParticipant
 * @returns {string}
 */
function getParticipantNames(slotParticipant) {
    if (!slotParticipant || !(slotParticipant instanceof SingleScheduleParticipant)) return "-";
    return slotParticipant.fullName;
    // return slotParticipants
    //     .map((p) => `${p.first_name} ${p.last_name}`)
    //     .join(", ");
}

// ── Flatten schedule into slot rows ────────────────────────────────────────────

/**
 * Flattens the schedule into an array of "slot rows" — one per non-empty lane.
 * Each row carries the race-level metadata needed for cost lookup and display.
 *
 * @param {Array} scheduleData
 * @returns {Array<{
 *   participants: object[],
 *   boat:     object,
 *   category: object,
 *   gender:   object,
 *   distance: object,
 * }>}
 */
function flattenToSlotRows(scheduleData) {
    if (!Array.isArray(scheduleData)) return [];

    const rows = [];

    for (const race of scheduleData) {
        if (!Array.isArray(race.participants)) continue;

        for (const slot of race.participants) {
            // Skip empty lanes (no participants or empty array)
            if (!Array.isArray(slot.participants) || slot.participants.length === 0) continue;

            for (const p of slot.participants) {

                const participantObj = new SingleScheduleParticipant(p);

                rows.push({
                    participant: participantObj,
                    boat:     race.boat     ?? null,
                    category: race.category ?? null,
                    gender:   race.gender   ?? null,
                    distance: race.distance ?? null,
                });
            }
        }
    }

    return rows;
}

// ── Deduplication ─────────────────────────────────────────────────────────────

/**
 * Removes duplicate slot rows where the same participant has the same
 * boat + category + distance combination. This prevents finals/semi-finals
 * from doubling the registration costs.
 *
 * Deduplication key:
 *   - For registered participants (id != null): participantId|boatId|categoryId|distanceId
 *   - For manually-added participants (id == null): fullName|boatId|categoryId|distanceId
 *
 * @param {Array} slotRows
 * @returns {Array}
 */
function deduplicateSlotRows(slotRows) {
    const seen = new Set();
    return slotRows.filter((row) => {
        const p = row.participant;
        const participantKey =
            p?.id != null
                ? `id:${p.id}`
                : `name:${p?.fullName ?? "unknown"}`;
        const key = `${participantKey}|boat:${row.boat?.id ?? ""}|cat:${row.category?.id ?? ""}|dist:${row.distance?.id ?? ""}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
    });
}

// ── Grouping ───────────────────────────────────────────────────────────────────

/**
 * Groups slot rows by club, sorted alphabetically.
 * Uses club_id to merge entries that share a club but have empty short_club_name,
 * so they don't appear as separate "Unknown club" buckets.
 *
 * @param {Array} slotRows
 * @returns {Map<string, slotRows[]>}
 */
function groupByClub(slotRows) {
    const map = new Map();

    for (const row of slotRows) {
        const club = getClubFromSlot(row.participant);
        if (!map.has(club)) map.set(club, []);
        map.get(club).push(row);
    }

    return new Map([...map.entries()].sort(([a], [b]) => a.localeCompare(b)));
}

// ── HTML builder ───────────────────────────────────────────────────────────────

function buildHtml(rowsByClub, costMatrix, lateRegistrationCost, registeredIdSet) {
    const clubSections = [];
    let clubIndex = 0;

    for (const [clubName, rows] of rowsByClub) {
        const pageBreak = clubIndex > 0 ? `style="page-break-before: always;"` : "";

        const tableRows = rows.map((row) => {
            const late = isLateSlot(row.participant, registeredIdSet);
            const categoryId = row.category?.id;
            const boatId = row.boat?.id;
            const baseCost = parseFloat(costMatrix[categoryId]?.[boatId] ?? 0);
            const lateCost = late ? parseFloat(lateRegistrationCost ?? 0) : 0;
            const rowCost = baseCost + lateCost;

            const lateBadge = late
                ? `<span style="background: #fef3c7; color: #92400e; border: 1px solid #fcd34d; border-radius: 4px; padding: 1px 4px; font-size: 10px; margin-left: 6px;">Late</span>`
                : "";

            return `
                <tr>
                    <td style="padding: 6px; border-bottom: 1px solid #ccc;">${getParticipantNames(row.participant)}${lateBadge}</td>
                    <td style="padding: 6px; border-bottom: 1px solid #ccc;">${row.boat?.boat ?? "-"}</td>
                    <td style="padding: 6px; border-bottom: 1px solid #ccc;">${row.category?.category ?? "-"}</td>
                    <td style="padding: 6px; border-bottom: 1px solid #ccc;">${row.gender?.gender ?? "-"}</td>
                    <td style="padding: 6px; border-bottom: 1px solid #ccc;">${row.distance?.distance ?? "-"}</td>
                    <td style="padding: 6px; border-bottom: 1px solid #ccc; text-align: right;">${formatEuro(rowCost)}</td>
                </tr>`;
        });

        const clubTotal = rows.reduce((sum, row) => {
            const late = isLateSlot(row.participant, registeredIdSet);
            const baseCost = parseFloat(costMatrix[row.category?.id]?.[row.boat?.id] ?? 0);
            const lateCost = late ? parseFloat(lateRegistrationCost ?? 0) : 0;
            return sum + baseCost + lateCost;
        }, 0);

        const lateCount = rows.filter((row) => isLateSlot(row.participant, registeredIdSet)).length;
        const lateNote = lateCount > 0 && parseFloat(lateRegistrationCost) > 0
            ? `<div style="font-size: 11px; color: #666; margin-bottom: 4px;">* ${lateCount} late registration(s) included</div>`
            : "";

        clubSections.push(`
            <div ${pageBreak} style="padding: 20px;">
                <h3 style="margin: 0; font-size: 18px;">${clubName}</h3>
                <table style="width: 100%; border-collapse: collapse; font-size: 12px;">
                    <thead>
                        <tr style="background: #f2f2f2;">
                            <th style="padding: 6px; text-align: left; border-bottom: 1px solid #999;">Participant(s)</th>
                            <th style="padding: 6px; text-align: left; border-bottom: 1px solid #999;">Boat</th>
                            <th style="padding: 6px; text-align: left; border-bottom: 1px solid #999;">Category</th>
                            <th style="padding: 6px; text-align: left; border-bottom: 1px solid #999;">Gender</th>
                            <th style="padding: 6px; text-align: left; border-bottom: 1px solid #999;">Distance</th>
                            <th style="padding: 6px; text-align: right; border-bottom: 1px solid #999;">Cost</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${tableRows.join("")}
                    </tbody>
                </table>

                <div style="margin-top: 12px; text-align: right;">
                    ${lateNote}
                    <div style="font-size: 14px; font-weight: bold; border-top: 1px solid #999; display: inline-block; padding-top: 4px; min-width: 120px;">
                        Total: ${formatEuro(clubTotal)}
                    </div>
                </div>
            </div>
        `);

        clubIndex++;
    }

    return `
        <div style="font-family: Arial, sans-serif; color: #000;">
            ${clubSections.join("\n")}
        </div>
    `;
}

// ── Entry point ────────────────────────────────────────────────────────────────

/**
 * @param {object} options
 * @param {Array}   options.registrations       – formal registration list (for late detection)
 * @param {Array}   options.scheduleData        – full schedule (source of truth)
 * @param {object}  options.costMatrix          – { [categoryId]: { [boatId]: number } }
 * @param {number}  options.lateRegistrationCost
 */
export async function generateRegistrationCostsPdf({
                                                       registrations,
                                                       scheduleData,
                                                       costMatrix,
                                                       lateRegistrationCost,
                                                   }) {
    const registeredIdSet = buildRegisteredParticipantIdSet(registrations);
    const slotRows = deduplicateSlotRows(flattenToSlotRows(scheduleData));
    const rowsByClub = groupByClub(slotRows);
    const html = buildHtml(rowsByClub, costMatrix, lateRegistrationCost, registeredIdSet);

    await html2pdf()
        .set({
            margin:      [12, 12, 12, 12],
            format:      "a4",
            orientation: "portrait",
            image:       { type: "jpeg", quality: 2 },
            html2canvas: { scale: 1, useCORS: true, logging: false },
            pagebreak:   { mode: ["avoid-all", "css"] },
        })
        .from(html)
        .save();
}