import {Badge, Combobox, Option} from "@fluentui/react-components";
import Schedule from "../../models/Schedule";
import {getTitleString} from "../schedule/ScheduleItem";
import {isScheduleItemFinished} from "../../handlers/schedulehandler";

const RaceSelectBox = ({ scheduleData, raceIds, setRaceIds, showNotStartedRaces = true, showStartedRaces = true, showFinishedRaces = true }) => {
    const showRace = (scheduleItem) => {
        if (!scheduleItem || !(scheduleItem instanceof Schedule)) {
            return false;
        }

        const hasStarted = scheduleItem.race_start_time != null;
        const isFinished = isScheduleItemFinished(scheduleItem);
        const isNotStarted = !hasStarted;

        if (showNotStartedRaces && isNotStarted) return true;
        if (showFinishedRaces && isFinished) return true;

        if (showStartedRaces && hasStarted && !isFinished) return true;

        return !showNotStartedRaces && !showStartedRaces && !showFinishedRaces;
    }

    function getRaceNRs(raceId) {
        if (!scheduleData || !raceId || !scheduleData instanceof Array) {
            return;
        }

        return `Race ${scheduleData.find(race => race instanceof Schedule && race.id && raceId === race.id).race_nr}`;
    }

    const onRacesSelect = (event, data) => {
        if (!setRaceIds) {
            return;
        }

        setRaceIds(data.selectedOptions);
    };

    return (
        <Combobox
            multiselect={true}
            placeholder="Select races"
            onOptionSelect={onRacesSelect}
            value={raceIds.length > 0 ? raceIds.map((id) => getRaceNRs(id)).join(', ') : ``}
        >
            {
                (scheduleData instanceof Array) ? scheduleData.filter((race) => showRace(race)).map((race) => (
                    <Option key={race.id} value={race.id}>
                        <div className={`flex flex-column`}>
                            <div className={`flex`}>
                                {
                                    race.race_start_time && !isScheduleItemFinished(race) &&
                                    <>
                                        <Badge appearance="filled" color="warning">
                                            Started
                                        </Badge>
                                    </>
                                }
                                {
                                    isScheduleItemFinished(race) &&
                                    <>
                                        <Badge appearance="filled" color="success">
                                            Finished
                                        </Badge>
                                    </>
                                }
                            </div>
                            { getTitleString(race) }
                        </div>
                    </Option>
                )) : null
            }
        </Combobox>
    )
}

export default RaceSelectBox;