import {isScheduleItemFinished} from "./schedulehandler";
import Schedule from "../models/Schedule";
import ScheduleResult from "../models/ScheduleResult";
import html2pdf from "html2pdf.js";

export const generateHanzebokaal = (schedule) => {
    const k1FinishPoints = [ 20, 16, 12, 8, 6, 4, 2, 1, 0 ];
    const k2FinishPoints = [ 15, 12, 9, 6, 4, 3, 2, 1, 0 ];
    const k4FinishPoints = [ 10, 8, 6, 5, 4, 3, 2, 1, 0 ];

    let pointsPerClubs = {};

    for (const scheduleItem of schedule) {
        if (!(scheduleItem instanceof Schedule) || !isScheduleItemFinished(scheduleItem)) {
            continue;
        }

        const raceType = scheduleItem.race_type?.toLowerCase() || "";
        const dist = scheduleItem.distance?.distance.toLowerCase() || "";
        const cat = scheduleItem.category?.category.toLowerCase() || "";
        const boat = scheduleItem.boat?.boat.toLowerCase() || "";

        if (
            raceType.includes("serie") ||

            (!raceType.includes("finale") || raceType.includes("halve")) ||

            raceType.includes("kvn") ||

            !(
                dist === "200 meter" ||
                dist === "500 meter" ||
                (dist === "1000 meter" && (cat.includes("junioren") || cat.includes("senioren") || cat.includes("masters")))
            ) ||

            !(
                boat === "k1" ||
                boat === "k2" ||
                boat === "k4"
            )
        ) {
            continue;
        }

        for (const result of scheduleItem.results) {
            if (!(result instanceof ScheduleResult)) continue;

            const order = parseInt(String(result.order)) - 1;

            if (isNaN(order)) continue;

            if (order > k1FinishPoints.length || order > k2FinishPoints.length || order > k4FinishPoints.length) continue;

            const participants = scheduleItem.participants?.find(p => String(p.start_nr) === String(result.start_nr));

            if (participants?.length <= 0) continue;

            participants.participants.forEach((participant) => {
                const club = participant.short_club_name;

                switch (boat) {
                    case "k1":
                        if (pointsPerClubs[club]) {
                            pointsPerClubs[club] = pointsPerClubs[club] + k1FinishPoints[order];
                            break;
                        }

                        pointsPerClubs[club] = k1FinishPoints[order];
                        break;

                    case "k2":
                        if (pointsPerClubs[club]) {
                            pointsPerClubs[club] = pointsPerClubs[club] + k2FinishPoints[order];
                            break;
                        }

                        pointsPerClubs[club] = k2FinishPoints[order];
                        break;

                    case "k4":
                        if (pointsPerClubs[club]) {
                            pointsPerClubs[club] = pointsPerClubs[club] + k4FinishPoints[order];
                            break;
                        }

                        pointsPerClubs[club] = k4FinishPoints[order];
                        break;
                }
            })
        }
    }

    return pointsPerClubs;
}

export const generateHzBokaalPDF = async (hzBokaalData) => {
    let rows = "";

    Object.entries(hzBokaalData).forEach(([key, value]) => {
        rows += `
        <tr>
            <td style="padding: 6px">${key}</td>
            <td style="padding: 6px">${value}</td>
        </tr>
    `;
    });
    const html = `
        <div style="font-family: Arial, sans-serif; padding:20px;">
            <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 12px" >
                <img style="width: 32px; height: 32px;" src="data:image/png;base64," alt="Klokking"/>
                <h3>Hanzebokaal</h3>
            </div>
            <table style="width:100%; border-collapse: collapse; font-size:12px;">
                <thead>
                    <tr style="background:#f2f2f2;">
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Club</th>
                        <th style="padding:6px; text-align:left; border-bottom:1px solid #999;">Punten</th>
                    </tr>
                </thead>

                <tbody>
                    ${rows}
                </tbody>
            </table>
        </div>
    `;

    await html2pdf()
        .set({
            margin: 10,
            filename: `Hanzebokaal.pdf`,
            html2canvas: { scale: 2 },
            jsPDF: { unit: "mm", format: "a4", orientation: "portrait" }
        })
        .from(html)
        .save();
}