import {useEffect, useState} from "react";
import {getScheduleItem, updateRaceFromSchedule} from "../../../handlers/schedulehandler";
import TimeComponent from "../TimeComponent";
import ProgressRing from "../../ProgressRing";
import MessageBar from "../../MessageBar";
import * as React from "react";
import ScheduleItemForView from "../../schedule/ScheduleItemForView";
import {
    Badge,
    Button, Input,
    Popover, PopoverSurface, PopoverTrigger,
    Table,
    TableBody,
    TableCell,
    TableHeader,
    TableHeaderCell,
    TableRow
} from "@fluentui/react-components";
import {RaceFinishColumns} from "../../../models/Schedule";
import ScheduleResult from "../../../models/ScheduleResult";
import {getFormatForTimeValue, getMillisecondsFormat} from "../../../handlers/datehandler";
import {
    Checkmark12Regular,
    Delete16Filled,
    Edit12Filled, ErrorCircle12Filled,
    Save16Filled,
} from "@fluentui/react-icons";
import {getParticipantString} from "../../schedule/ScheduleItem";
import ConfirmDialog from "../../ConfirmDialog";
import finishSound from "../../../assets/finishSound.mp3";

const FinishSingleRaceComponent = ({ eventId, raceId }) => {
    const [scheduleItem, setScheduleItem] = useState({});
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [results, setResults] = useState(null);
    const [localResultDateTime, setLocalResultDateTime] = useState(null);
    const [openPopOvers, setOpenPopOvers] = useState([]);
    const [isSaved, setSaved] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const finishAudio = new Audio(finishSound);

    useEffect(() => {
        const unlock = () => {
            finishAudio.load();
            finishAudio.volume = 0;
            finishAudio.play().then(() => {
                finishAudio.pause();
                finishAudio.currentTime = 0;
                finishAudio.volume = 1;
            }).catch(() => {});
        };
        document.addEventListener('keydown', unlock, { once: true });
        return () => document.removeEventListener('keydown', unlock);
    }, []);
// Usage

    const playAudio = () => {
        finishAudio.play().then(() => {/*ignored*/}).catch(() => {/*ignored*/});
    }

    const keysForFinish = [
        "Escape",
        "F12"
    ];

    const notValidRaceResultParams = [
        "DNS",
        "DNF",
        "DQ"
    ];

    useEffect(() => {
        setIsLoading(true);
        getScheduleItem(raceId).then((data) => {
            setIsLoading(false);

            if (!data) {
                setScheduleItem({});
                setError(`An error occurred while fetching schedule data`);
                return;
            }

            setScheduleItem(data);

            setResults(data.results);

            setError(null);
        });

        window.addEventListener("keydown", handleKeyEvent);
        return () => {
            window.removeEventListener("keydown", handleKeyEvent);
        };
    }, []);

    function handleKeyEvent(event) {
        const currentDateTime = new Date();
        if (keysForFinish.includes(event.key)) {
            event.preventDefault();
            addTime(currentDateTime);
            playAudio();
        }
    }

    function saveResults() {
        setIsSaving(true);

        const resultsObject = {
            results: results,
        }

        updateRaceFromSchedule(raceId, resultsObject).then((data) => {
            setIsSaving(false);

            if(!data) {
                setError("Error saving schedule item");
                return;
            }

            setError(null);
            setSaved(true);
        });
    }

    function addTime(dateTime) {
        setResults((prevResults) => {
            let newResults = prevResults;

            if (!newResults) {
                newResults = [];
            }

            newResults.sort((a, b) => a.order - b.order);

            const newResultObject = new ScheduleResult({
                start_nr: undefined,
                order: newResults.length + 1,
                finish_time: dateTime,
            });

            setSaved(false);

            return sortResultData([...newResults, newResultObject]);
        });
    }

    function setStartNR(index, value) {
        setSaved(false);
        setResults((prevResults) => {
            if (!prevResults || prevResults.length < index ) {
                return prevResults;
            }

            let newResults = [...prevResults];
            newResults[index].start_nr = value;
            return newResults;
        });
    }

    function getParticipantsByStartNR(startNR) {
        if (!startNR || scheduleItem.participants?.length === 0) {
            return ``;
        }

        const participants = scheduleItem.participants.find((p) => p.start_nr.toString() === startNR.toString())?.participants;

        if (!participants || !participants.length) {
            return ``;
        }

        return getParticipantString(participants);
    }

    function setNotValidRaceResult(param, index) {
        setResults((prevResults) => {
           if (!prevResults || prevResults.length < index) {
               return prevResults;
           }

           let newResults = [...prevResults];

            newResults[index].order = param !== null ? param : 999;

           newResults = sortResultData(newResults);

           setSaved(false);

           return newResults;
        });
    }

    function setLocalDateTimeForPopover(dateTime) {
        setLocalResultDateTime(dateTime);
    }

    function getTimeObjectOfLocalResult() {
        if (!localResultDateTime || !(localResultDateTime instanceof Date)) {
            return {
                h: 0,
                m: 0,
                s: 0,
                ms: 0
            };
        }

        return {
            h: localResultDateTime.getHours(),
            m: localResultDateTime.getMinutes(),
            s: localResultDateTime.getSeconds(),
            ms: localResultDateTime.getMilliseconds()
        }
    }

    function updateDateTimeOfLocalResult(object) {
        if (!object || !localResultDateTime || !(localResultDateTime instanceof Date)) {
            return;
        }

        const dateTime = new Date(localResultDateTime.getTime());

        if (object.h && isTimeValueValid(object.h, 99)) {
            dateTime.setHours(object.h);
        }

        if (object.m && isTimeValueValid(object.m, 99)) {
            dateTime.setMinutes(object.m);
        }

        if (object.s && isTimeValueValid(object.s, 99)) {
            dateTime.setSeconds(object.s);
        }

        if (object.ms && isTimeValueValid(object.ms, 999)) {
            dateTime.setMilliseconds(object.ms);
        }

        setLocalResultDateTime(dateTime);
    }

    function saveNewDateTime(index) {
        setResults((prevResults) => {
            if (!prevResults || prevResults.length < index ) {
                return prevResults;
            }

            let newResults = prevResults;
            newResults[index].finish_time = localResultDateTime;

            setSaved(false);
            return newResults;
        });

        closePopOver(index);
        setLocalResultDateTime(null);
    }

    function deleteRow(index) {
        setResults((prevResults) => {
            if (!prevResults || prevResults.length < index) {
                return prevResults;
            }

            let newResults = [...prevResults];
            newResults.splice(index, 1);

            newResults = sortResultData(newResults);

            setSaved(false);
            return newResults;
        })
    }

    function handlePopOverStatus(index, open) {
        if (open) {
            openPopOver(index);

        } else {
            closePopOver(index);
        }
    }

    function openPopOver(index) {
        setOpenPopOvers([...openPopOvers, index]);
    }

    function closePopOver(index) {
        setOpenPopOvers([...(openPopOvers.filter((o) => o.index === index))]);
    }

    function sortResultData(resultData) {
        const sorted = [...resultData].sort((a, b) => {
            const aStatus = isNaN(a.order);
            const bStatus = isNaN(b.order);

            if (aStatus && bStatus) {
                return new Date(a.finish_time) - new Date(b.finish_time);
            }

            if (aStatus) return 1;
            if (bStatus) return -1;

            return new Date(a.finish_time) - new Date(b.finish_time);
        });

        let currentRank = 1;
        for (let i = 0; i < sorted.length; i++) {
            if (!isNaN(sorted[i].order)) {
                sorted[i].order = currentRank;
                currentRank++;
            }
        }

        return sorted;
    }

    const getWidthForColumnForRaceFinishColumns = (columnKey) => {
        const column = RaceFinishColumns.find(col => col.columnKey === columnKey);
        if (column) {
            return `${(column.span / 12) * 100}%`;
        }
        return 'auto';
    };

    const getTime = (dateTime) => {
        const diffMs = new Date(dateTime) - new Date(scheduleItem.race_start_time);

        const hours = Math.floor(diffMs / 3_600_000);
        const minutes = Math.floor((diffMs % 3_600_000) / 60_000);
        const seconds = Math.floor((diffMs % 60_000) / 1_000);
        const milliseconds = diffMs % 1_000;

        return `${getFormatForTimeValue(hours)}:${getFormatForTimeValue(minutes)}:${getFormatForTimeValue(seconds)}.${milliseconds.toString().padStart(3, '0')}`;
    }

    const isTimeValueValid = (value, maxValue) => {
        return (value && !isNaN(value) && parseInt(value) <= maxValue && parseInt(value) >= 0);
    }

    return (
        <>
            { isLoading &&
                <>
                    <ProgressRing/>
                </>
            }
            { !isLoading && error &&
                <>
                    <MessageBar title={error} intent={`error`} closeButtonFunction={ () => setError(null) } />
                </>
            }
            {
                !isLoading &&
                <>
                    <div className={`flex flex-gap-medium flex-align-center`}>
                        <TimeComponent startTime={scheduleItem.race_start_time} />
                        <Button as={`a`} appearance={`primary`} className={`button`} disabled={isSaving} onClick={() => saveResults()}>
                            <Save16Filled/> Save Result
                        </Button>
                        {
                            isSaved && !isSaving &&
                            <>
                                <Badge appearance={`outline`} color="success" className={`badge`}>
                                    <Checkmark12Regular/> Results saved
                                </Badge>
                            </>
                        }
                        {
                            !isSaved && !isSaving &&
                            <>
                                <Badge appearance={`outline`} color="danger" className={`badge`}>
                                    <ErrorCircle12Filled/> Unsaved changes
                                </Badge>
                            </>
                        }
                        {
                            isSaving &&
                            <>
                                <ProgressRing/>
                            </>
                        }
                    </div>
                    <ScheduleItemForView scheduleItem={scheduleItem} />
                    <Table
                        style={{tableLayout: "fixed"}}>
                        <TableHeader>
                            <TableRow>
                                {
                                    RaceFinishColumns.map((column) => (
                                        <TableHeaderCell
                                            key={column.columnKey}
                                            style={{ width: getWidthForColumnForRaceFinishColumns(column.columnKey) }} >
                                            <b>{column.label}</b>
                                        </TableHeaderCell>
                                    ))
                                }
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {
                                results && Array.isArray(results) &&
                                <>
                                    {
                                        results.map((result, index) => (
                                            <TableRow key={`result-${index}-${result.order}`}>
                                                <TableCell>
                                                    <Popover>
                                                        <PopoverTrigger>
                                                            <Button as={`a`} appearance={`subtle`} className={`button`} size={`small`}>
                                                                <Edit12Filled/> {result.order}
                                                            </Button>
                                                        </PopoverTrigger>
                                                        <PopoverSurface className={`dialog`}>
                                                            <div className={`flex flex-column flex-gap-small`}>
                                                                {
                                                                    notValidRaceResultParams.map((param) => (
                                                                        <Button key={param} as={`a`} appearance={`subtle`} size={`small`} className={`button`} onClick={() => setNotValidRaceResult((isNaN(result.order) ? null : param), index)}>
                                                                            {param === result.order && <Checkmark12Regular/>} {param}
                                                                        </Button>
                                                                    ))
                                                                }
                                                            </div>
                                                        </PopoverSurface>
                                                    </Popover>
                                                </TableCell>
                                                <TableCell>
                                                    <Input className={`width-100 min-width-unset`} value={result.start_nr} onChange={(e) => setStartNR(index, e.target.value)} />
                                                </TableCell>
                                                <TableCell>
                                                    <Popover open={openPopOvers.includes(index)} onOpenChange={(e, data) => handlePopOverStatus(index, data.open)}>
                                                        <PopoverTrigger>
                                                            <Button as={`a`} appearance={`subtle`} className={`button`} size={`small`} onClick={() => {setLocalDateTimeForPopover(new Date(result.finish_time)); }}>
                                                                <Edit12Filled/> {getTime(result.finish_time)}
                                                            </Button>
                                                        </PopoverTrigger>
                                                        <PopoverSurface className={`dialog`}>
                                                            <div className={'flex-column'}>
                                                                <h3 className={`small-margin`}>Edit Time</h3>
                                                                <p className={`small-margin`}>Edit the endtime this lane has been finished</p>
                                                                <div className={`flex flex-gap-small flex-align-center`}>
                                                                    <Input className={`small-margin input-xs`} size="small" type={`number`} placeholder="HH" value={getTimeObjectOfLocalResult().h} onChange={(e) => updateDateTimeOfLocalResult({h: e.target.value})}/>
                                                                    <p className={`small-margin`}>:</p>
                                                                    <Input className={`small-margin input-xs`} size="small" type={`number`} placeholder="MM" value={getTimeObjectOfLocalResult().m} onChange={(e) => updateDateTimeOfLocalResult({m: e.target.value})}/>
                                                                    <p className={`small-margin`}>:</p>
                                                                    <Input className={`small-margin input-xs`} size="small" type={`number`} placeholder="SS" value={getTimeObjectOfLocalResult().s} onChange={(e) => updateDateTimeOfLocalResult({s: e.target.value})}/>
                                                                    <p className={`small-margin`}>.</p>
                                                                    <Input className={`small-margin input-xs-wide`} size="small"  type={`number`} placeholder="ms" value={getTimeObjectOfLocalResult().ms} onChange={(e) => updateDateTimeOfLocalResult({ms: e.target.value})}/>
                                                                </div>
                                                                <div className={`flex flex-gap-small`}>
                                                                    <Button as={`a`} size={`small`} appearance={`primary`} onClick={() => saveNewDateTime(index) } className={`button`}>
                                                                        Save
                                                                    </Button>
                                                                    <Button as={`a`} size={`small`} appearance={`outline`} onClick={() => closePopOver(index) } className={`button`}>
                                                                        Cancel
                                                                    </Button>
                                                                </div>
                                                            </div>
                                                        </PopoverSurface>
                                                    </Popover>
                                                </TableCell>
                                                <TableCell>{getParticipantsByStartNR(result.start_nr)}</TableCell>
                                                <TableCell>
                                                    <ConfirmDialog
                                                        altButton={
                                                            <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>} />
                                                        }
                                                        appearance={`subtle`}
                                                        buttonSize={`small`}
                                                        title={`Delete Result`}
                                                        description={`Are you sure you want to delete this row of the results? This action cannot be undone.`}
                                                        buttonText={`Delete`}
                                                        buttonColor={`red`}
                                                        onConfirm={() => deleteRow(index)} />

                                                </TableCell>
                                            </TableRow>
                                        ))
                                    }
                                </>

                            }
                        </TableBody>
                    </Table>
                </>
            }
        </>
    );
}


export default FinishSingleRaceComponent;