import {useState} from "react";
import {
    addBoatToDatabase,
    updateBoatFromDatabase,
} from "../../../handlers/databasehandler";
import {Add12Regular} from "@fluentui/react-icons";
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger, Input, Label
} from "@fluentui/react-components";

const ChangeRegistrationBoatDialog = ({eventId, boat, onUpdate, isNew = false, altButton = null}) => {
    const [boatText, setBoatText] = useState(isNew ? "" : boat.boat);
    const [amountOfPeopleText, setAmountOfPeopleText] = useState(isNew ? "1" : boat.amount_of_people);

    async function updateBoat() {
        updateBoatFromDatabase(eventId, boat.id, boatText, amountOfPeopleText).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    async function addBoat() {
        addBoatToDatabase(eventId, boatText, amountOfPeopleText).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    function changeAmountOfPeopleText(e) {
        const value = e;
        if (isNaN(value) && value < 1 || value > 4) {
            return;
        }
        setAmountOfPeopleText(value);
    }

    return (
        <>
            <Dialog>
                <DialogTrigger>
                    { altButton ? altButton : <Button as={"a"} className={`button`}  appearance={"primary"}>{ isNew ? <><Add12Regular/> Toevoegen</> : <>Wijzigen</> }</Button> }
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>{ isNew ? <>Boat Toevoegen</> : <>{boat.boat} wijzigen</>}</DialogTitle>
                    <DialogContent>
                        <div style={{
                            display: "flex",
                            flexDirection: "column",
                            gap: 12,
                            marginBottom: 12,
                            marginTop: 12
                        }}>
                            <div style={{display: "flex", alignItems: "center", gap: 8}}>
                                <Label style={{width: 150}}>Boat:</Label>
                                <Input
                                    value={boatText}
                                    onChange={(e) => setBoatText(e.target.value)}
                                    style={{flex: 1}}/>
                            </div>
                            <div style={{display: "flex", alignItems: "center", gap: 8}}>
                                <Label style={{width: 150}}>Amount of people:</Label>
                                <Input
                                    value={amountOfPeopleText}
                                    onChange={(e) => changeAmountOfPeopleText(e.target.value)}
                                    style={{flex: 1}}
                                    type="number"/>
                            </div>
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button as={"a"} className={`button`} appearance="secondary">Annuleren</Button>
                        </DialogTrigger>
                        <DialogTrigger>
                            <Button as={"a"} className={`button`} appearance="primary" onClick={isNew ? addBoat : updateBoat}>
                                { isNew ? <>Toevoegen</> : <>Wijzigen</> }
                            </Button>
                        </DialogTrigger>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
}

export default ChangeRegistrationBoatDialog;