import React, { useState, useMemo } from 'react';
import {
    Dialog,
    DialogTrigger,
    DialogSurface,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Label,
    Input,
    Combobox,
    Option
} from "@fluentui/react-components";
import { Add16Filled } from "@fluentui/react-icons";
import { FINALS_METHOD, FINALS_METHOD_LABELS, generateFinalsData } from "../../handlers/finalshandler";
import { updateRaceFromSchedule } from "../../handlers/schedulehandler";
import MessageBox from "../MessageBar";
import ProgressRing from "../ProgressRing";
import RaceSelectBox from "../racesystem/RaceSelectBox";

const GenerateFinalsDialog = ({ scheduleData, onUpdate, button }) => {
    const [open, setOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [errorMsg, setErrorMsg] = useState(null);

    const [inputRaceIds, setInputRaceIds] = useState([]);
    const [outputRaceIds, setOutputRaceIds] = useState([]);
    const [method, setMethod] = useState(FINALS_METHOD.POSITIONS);
    const [numLanes, setNumLanes] = useState(9);

    const onDialogOpenChange = (e, data) => setOpen(data.open);
    const onMethodSelect = (e, data) => setMethod(data.optionValue);
    const setNumLanesField = (val) => setNumLanes(parseInt(val) || 0);

    // Filtered data for selectors
    const inputScheduleData = useMemo(() =>
        scheduleData.filter(r => r.participants?.some(p => p.order > 0)), [scheduleData]);

    const outputScheduleData = useMemo(() =>
        scheduleData.filter(r => !r.participants || r.participants.length === 0), [scheduleData]);

    const outputRaceLabels = useMemo(() => {
        const labels = ['A', 'B', 'C', 'D', 'E', 'F'];
        return outputRaceIds.map((id, index) => {
            const race = scheduleData.find(r => r.id === id);
            return race ? `Race ${race.race_nr} (Final ${labels[index] || index + 1})` : '';
        }).filter(Boolean).join(', ');
    }, [outputRaceIds, scheduleData]);

    const methodDescription = useMemo(() => {
        switch (method) {
            case FINALS_METHOD.POSITIONS: return "Best ranks are spread across middle lanes of all selected output races.";
            case FINALS_METHOD.ABC: return "Top ranks go to Final A, next to Final B, using middle-out lane logic.";
            case FINALS_METHOD.HASSLER: return "Fastest participants by time are grouped into Finals A, B, etc.";
            default: return "";
        }
    }, [method]);

    const previewText = useMemo(() => {
        if (!inputRaceIds.length || !outputRaceIds.length) return "Select races to see preview.";
        return `Ready to distribute participants from ${inputRaceIds.length} races into ${outputRaceIds.length} finals.`;
    }, [inputRaceIds, outputRaceIds]);

    const generateFinals = async () => {
        setIsLoading(true);
        setErrorMsg(null);
        try {
            const inputRaces = scheduleData.filter(r => inputRaceIds.includes(r.id));
            const outputRaces = scheduleData.filter(r => outputRaceIds.includes(r.id));

            const finalMapping = generateFinalsData(inputRaces, outputRaces, method, numLanes);

            console.log(finalMapping);

            for (const raceId of Object.keys(finalMapping)) {
                await updateRaceFromSchedule(raceId, { participants: finalMapping[raceId] });
            }

            setOpen(false);
            if (onUpdate) onUpdate();
        } catch (err) {
            setErrorMsg("Generation error: " + err.message);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <>
            <Dialog open={open} onOpenChange={onDialogOpenChange}>
                <DialogTrigger>
                    {button || <Button as={`a`} icon={<Add16Filled />}>Generate Finals</Button>}
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>Generate Finals</DialogTitle>
                    <DialogContent>
                        {errorMsg && <MessageBox title={errorMsg} intent={"error"} />}
                        <div className={`dialog-content-container`}>
                            <div className={`dialog-content-item`}>
                                <Label>Input races (finished):</Label>
                                <RaceSelectBox
                                    scheduleData={scheduleData}
                                    raceIds={inputRaceIds}
                                    setRaceIds={setInputRaceIds}
                                    showNotStartedRaces={false}
                                    showStartedRaces={false}
                                    showFinishedRaces={true}
                                />
                            </div>
                            <div className={`dialog-content-item`}>
                                <Label>Output races (not started):</Label>
                                <RaceSelectBox
                                    scheduleData={scheduleData}
                                    raceIds={outputRaceIds}
                                    setRaceIds={setOutputRaceIds}
                                    showFinishedRaces={false}
                                    showStartedRaces={false}
                                    showNotStartedRaces={true}
                                />
                            </div>
                            {outputRaceLabels && (
                                <div className={`dialog-content-item`}>
                                    <Label />
                                    <span style={{ fontSize: "0.85rem", opacity: 0.7 }}>{outputRaceLabels}</span>
                                </div>
                            )}
                            <div className={`dialog-content-item`}>
                                <Label>Method:</Label>
                                <Combobox value={FINALS_METHOD_LABELS[method] || ""} onOptionSelect={onMethodSelect}>
                                    {Object.entries(FINALS_METHOD).map(([key, val]) => (
                                        <Option key={key} value={val}>{FINALS_METHOD_LABELS[val]}</Option>
                                    ))}
                                </Combobox>
                            </div>
                            {methodDescription && (
                                <div className={`dialog-content-item`}>
                                    <Label />
                                    <span style={{ fontSize: "0.85rem", opacity: 0.7 }}>{methodDescription}</span>
                                </div>
                            )}
                            {method !== FINALS_METHOD.HASSLER && (
                                <div className={`dialog-content-item`}>
                                    <Label>Lanes per final:</Label>
                                    <Input type={`number`} value={numLanes} min={1} onInput={(e) => setNumLanesField(e.target.value)} />
                                </div>
                            )}
                            {previewText && (
                                <div className={`dialog-content-item`}>
                                    <Label>Preview:</Label>
                                    <span>{previewText}</span>
                                </div>
                            )}
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button as={`a`} className={`button`} appearance="secondary">Cancel</Button>
                        </DialogTrigger>
                        <Button as={`a`}
                            className={`button`}
                            appearance="primary"
                            disabled={!!errorMsg || isLoading || !inputRaceIds.length || !outputRaceIds.length}
                            onClick={generateFinals}
                        >
                            {isLoading ? <ProgressRing /> : `Generate`}
                        </Button>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
};

export default GenerateFinalsDialog;