import {Button, Card, Subtitle2, Text} from "@fluentui/react-components";

function SettingsItem({title, text, buttonText, onClick, buttonColor = null}){
    return (
        <Card
            className={`card card-horizontal`}>
            <div className={`flex flex-column flex-gap-small`}>
                <Subtitle2>{title}</Subtitle2>
                <Text>{text}</Text>
            </div>
            <Button as={`a`} className={`button`} appearance={"outline"} onClick={onClick} style={{ color: buttonColor, borderColor: buttonColor }}>
                {buttonText}
            </Button>
        </Card>
    )
}

export default SettingsItem;