import * as React from "react";
import {useEffect, useState} from "react";
import ProgressRing from "../../ProgressRing";
import MessageBar from "../../MessageBar";
import {getSchedule, getScheduleItem, isScheduleItemFinished, saveRaceStarted} from "../../../handlers/schedulehandler";
import ScheduleItemForView from "../../schedule/ScheduleItemForView";
import {
    Badge,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle, DialogTrigger, Input,
    Label, Popover, PopoverSurface, PopoverTrigger
} from "@fluentui/react-components";
import RaceSelectBox from "../RaceSelectBox";
import {
    ArrowLeft12Regular, ArrowLeft16Regular,
    ArrowRight12Filled,
    ArrowRight16Filled, ArrowRight16Regular,
    Timer16Filled,
    WrenchSettingsFilled
} from "@fluentui/react-icons";
import Schedule from "../../../models/Schedule";
import {navigateToPage} from "../../../handlers/routehandler";
import {BiArrowToRight} from "react-icons/bi";

const StartSingleRaceComponent = ({ eventId, raceId }) => {
    const [scheduleItem, setScheduleItem] = useState({});
    const [scheduleData, setScheduleData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);
    const [extraRaces, setExtraRaces] = useState([]);
    const [isStarted, setIsStarted] = useState(false);
    const [isDialogOpen, setDialogOpen] = useState(false);
    const [startDate, setStartDate] = useState(undefined);
    const [manualStartDate, setManualStartDate] = useState({
        h: 0,
        m: 0,
        s: 0,
        ms: 0
    });
    const [isPopoverOpen, setPopoverOpen] = useState(false);


    useEffect(() => {
        setIsLoading(true);
        getScheduleItem(raceId).then((data) => {
            setIsLoading(false);

            if (!data) {
                setScheduleItem({});
                setError(`An error occurred while fetching schedule data`);
                return;
            }

            setScheduleItem(data);

            if (data.race_start_time) {
                setIsStarted(true);
            }

            setError(null);
        });

        getSchedule(eventId).then((data) => {
            if (!data) {
                setScheduleData([]);
                return;
            }

            setScheduleData(data.filter((race) => race instanceof Schedule && race.id && race.id !== parseInt(raceId)));
        });
    }, []);

    function updateManualStartDate(object) {
        if (!object) {
            return;
        }

        const newManualStartDate = {...manualStartDate};

        if (object.h && object.h >= 0 && object.h <= 23) {
            newManualStartDate.h = object.h;
        }

        if (object.m && object.m >= 0 && object.m <= 59) {
            newManualStartDate.m = object.m;
        }

        if (object.s && object.s >= 0 && object.s <= 59) {
            newManualStartDate.s = object.s;
        }

        if (object.ms && object.ms >= 0 && object.ms <= 999) {
            newManualStartDate.ms = object.ms;
        }

        setManualStartDate(newManualStartDate);
    }

    function saveManualStartDate() {
        const dateTime = new Date();

        dateTime.setHours(manualStartDate.h);
        dateTime.setMinutes(manualStartDate.m);
        dateTime.setSeconds(manualStartDate.s);
        dateTime.setMilliseconds(manualStartDate.ms);

        startRace(dateTime);
    }

    function startButtonClicked() {
        const date = new Date();
        setStartDate(date);

        if (isStarted) {
            setDialogOpen(true);
            return;
        }

        startRace(date);
    }

    function startRace(date) {
        if (isDialogOpen) {
            setDialogOpen(false);
        }

        if (!date instanceof Date) {
            setError(`Error starting race. Start Time: ${date.toISOString()}`);
            return;
        }

        saveRaceStarted([parseInt(raceId), ...extraRaces], date).then((result) => {
            if (!result) {
                setError(`Error starting race. Start Time: ${date.toISOString()}`);
                return;
            }

            setSuccess(`Race started successfully. Start Time: ${date.toISOString()}`);
        });

        setIsStarted(true);
    }

    function getScheduleItemFromId(id) {
        if (!scheduleData || !id || !scheduleData instanceof Array) {
            return;
        }

        return scheduleData.find(item => item instanceof Schedule && item.id === id);
    }

    function openNextRace(prev = false) {
        const sortedSchedule = scheduleData.sort(
            (a, b) => prev ?
                parseInt(b.race_nr) - parseInt(a.race_nr) :
                parseInt(a.race_nr) - parseInt(b.race_nr));

        let currentRaceFound = false;
        let nextId = null;

        for (let race of sortedSchedule) {
            if (!(race instanceof Schedule)) {
                continue;
            }

            if (parseInt(race.id) === parseInt(raceId)) {
                currentRaceFound = true;
                continue;
            }

            if (currentRaceFound && !isScheduleItemFinished(race)) {
                nextId = race.id;
                break;
            }
        }

        if (!currentRaceFound || !nextId) {
            setError(`Error finding ${prev ? `previous` : `next`} race`);
            return;
        }

        const newUrl = `${window.location.origin}${window.location.pathname}#/events/${eventId}/start/${nextId}`;
        window.location.replace(newUrl);
        window.location.reload();
    }

    return (
        <>
            { isLoading &&
                <>
                    <ProgressRing/>
                </>
            }
            { !isLoading && error &&
                <>
                    <MessageBar title={error} intent={`error`} closeButtonFunction={ () => setError(null) } />
                </>
            }
            {
                success &&
                <>
                    <MessageBar title={success} intent={`success`} closeButtonFunction={ () => setSuccess(null) } />
                </>
            }
            { !isLoading &&
                <>
                    <div className={`flex flex-gap-medium flex-wrap`}>
                        {
                            isStarted &&
                            <>
                                <Badge appearance="filled" color="warning">
                                    Started
                                </Badge>
                            </>
                        }
                        <div className={`flex-column`}>
                            <Button as={`a`} appearance={`primary`} className={`button`} onClick={() => startButtonClicked()}>
                                <Timer16Filled/> Start Race
                            </Button>
                        </div>
                        <div className={`flex-column`}>
                            <Popover open={isPopoverOpen} onOpenChange={(e, data) => setPopoverOpen(data.open)}>
                                <PopoverTrigger>
                                    <Button as={`a`} appearance={`outline`} className={`button`} onClick={() => {}} icon={<WrenchSettingsFilled/>}/>
                                </PopoverTrigger>
                                <PopoverSurface className={`dialog`}>
                                    <div className={'flex-column'}>
                                        <h3 className={`small-margin`}>Manual Start Time</h3>
                                        <p className={`small-margin text-wrap text-max-width-300`}>Please note, setting a manual start time will override previous starts for the selected races. The date for the start is: {new Date().toLocaleDateString()}</p>
                                        <div className={`flex flex-gap-small flex-align-center`}>
                                            <Input className={`small-margin input-xs`} size="small" type={`number`} placeholder="HH" value={manualStartDate.h} onChange={(e) => updateManualStartDate({h: e.target.value})}/>
                                            <p className={`small-margin`}>:</p>
                                            <Input className={`small-margin input-xs`} size="small" type={`number`} placeholder="MM" value={manualStartDate.m} onChange={(e) => updateManualStartDate({m: e.target.value})}/>
                                            <p className={`small-margin`}>:</p>
                                            <Input className={`small-margin input-xs`} size="small" type={`number`} placeholder="SS" value={manualStartDate.s} onChange={(e) => updateManualStartDate({s: e.target.value})}/>
                                            <p className={`small-margin`}>.</p>
                                            <Input className={`small-margin input-xs-wide`} size="small"  type={`number`} placeholder="ms" value={manualStartDate.ms} onChange={(e) => updateManualStartDate({ms: e.target.value})}/>
                                        </div>
                                        <div className={`flex flex-gap-small`}>
                                            <Button as={`a`} size={`small`} appearance={`primary`} onClick={() => saveManualStartDate() } className={`button`}>
                                                Save
                                            </Button>
                                            <Button as={`a`} size={`small`} appearance={`outline`} className={`button`} onClick={() => setPopoverOpen(false)}>
                                                Cancel
                                            </Button>
                                        </div>
                                    </div>
                                </PopoverSurface>
                            </Popover>
                        </div>

                        <div className={`flex flex-gap-small flex-align-center`}>
                            <Label>
                                Extra races:
                            </Label>
                            <RaceSelectBox
                                scheduleData={scheduleData}
                                raceIds={extraRaces}
                                setRaceIds={setExtraRaces}
                                showNotStartedRaces={true}
                                showStartedRaces={true}
                                showFinishedRaces={false} />
                        </div>
                        <div className={`flex-column`}>
                            <Button as={`a`} appearance={`secondary`} className={`button`} onClick={() => openNextRace(true)}>
                                <ArrowLeft16Regular/> Previous Race
                            </Button>
                        </div>
                        <div className={`flex-column`}>
                            <Button as={`a`} appearance={`secondary`} className={`button`} onClick={() => openNextRace()}>
                                Next Race <ArrowRight16Regular/>
                            </Button>
                        </div>
                    </div>
                    <ScheduleItemForView scheduleItem={scheduleItem} />
                    {
                        extraRaces.filter((race) => getScheduleItemFromId(race) instanceof Schedule).map((race) => (
                            <ScheduleItemForView scheduleItem={getScheduleItemFromId(race)} key={race.id} />
                        ))
                    }
                </>
            }
            <Dialog open={isDialogOpen}>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>
                        Race already started
                    </DialogTitle>
                    <DialogContent>
                        This race is already started, are you sure you want to restart the race?
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger>
                            <Button as={`a`} className={`button`} appearance={`primary`} onClick={() => setDialogOpen(false)}>
                                Close
                            </Button>
                        </DialogTrigger>
                        <DialogTrigger>
                            <Button as={`a`} className={`button`} appearance={`secondary`} onClick={() => startRace(startDate)}>
                                Start Race
                            </Button>
                        </DialogTrigger>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
}

export default StartSingleRaceComponent;