import Schedule from "../models/Schedule";
import SingleScheduleParticipant from "../models/SingleScheduleParticipant";
import {
    addRaceToScheduleFromLocalDatabase, deleteRaceFromScheduleFromLocalDatabase,
    fetchScheduleFromLocalDatabase,
    fetchSingleScheduleItemFromLocalDatabase, updateRaceFromScheduleFromLocalDatabase
} from "./localdatabasehandler";
import {addRaceToScheduleFromDatabase, deleteRaceFromScheduleFromDatabase} from "./databasehandler";
import scheduleItem from "../components/schedule/ScheduleItem";
import Participant from "../models/Participant";

export const getSchedule = async (eventId, sortFinishedRaces = false) => {
    const result = await fetchScheduleFromLocalDatabase(eventId);

    if (!result || !result.data) {
        return null;
    }

    let resultToReturn = result.data.map((schedule) => new Schedule(schedule));

    resultToReturn.sort((a, b) => {
        if (sortFinishedRaces) {
            const aFinished = (a.results?.length > 0);
            const bFinished = (b.results?.length > 0);

            if (aFinished && !bFinished) return 1;
            if (!aFinished && bFinished) return -1;
        }

        return parseInt(a.race_nr) - parseInt(b.race_nr);
    });

    return resultToReturn;
}

export const getScheduleItem = async (raceId) => {
    const result = await fetchSingleScheduleItemFromLocalDatabase(raceId);

    if (!result || !result.data) {
        return null;
    }

    return new Schedule(result.data);
}

export const saveRaceStarted = async (raceIds, startDateTime) => {
    if (!raceIds || !(raceIds instanceof Array) || !(startDateTime instanceof Date)) {
        return null;
    }

    const startTimeObject = {
        race_start_time: startDateTime,
    }

    for (let raceId of raceIds) {
        const result = await updateRaceFromSchedule(raceId, startTimeObject);

        if (!result) {
            return null;
        }
    }

    return true;
}

export const addRaceFromSchedule = async (eventId, data) => {
    if (!data) {
        return;
    }

    const result = await addRaceToScheduleFromDatabase(eventId, data);

    if (result.error) {
        console.error(result.error);
        return null;
    }

    if (result.data?.id) {
        await addRaceToScheduleFromLocalDatabase(result.data);
    }

    return true;
}

export const updateRaceFromSchedule = async (id, data) => {
    if (!data) {
        return;
    }

    const result = await updateRaceFromScheduleFromLocalDatabase(id, data);

    if (result.error) {
        console.error(result.error);
        return null;
    }

    return true;
}

export const deleteRaceFromSchedule = async (id) => {
    const result = await deleteRaceFromScheduleFromDatabase(id);

    if (result.error) {
        console.error(result.error);
        return null;
    }

    await deleteRaceFromScheduleFromLocalDatabase(id);

    return true;
}

export const getParticipantsForSchedule = (registrations, scheduleItem) => {
    /*
    * If schedule item not valid (like 1 id is -1)
    * Then return all participants
    * ---
    * If schedule item valid
    * Return only selected participants
    * */

    /*
    * TO RETURN:
    * [{
    * regId,
    * participants[]
    * }]
    * */

    let allRegistrations = [];

    for (const r of registrations) {
        if (!isRegistrationForScheduleItem(scheduleItem, r.distance_id))
        {
            continue;
        }

        let participants = [];
        const participantKeys = ["participant1", "participant2", "participant3", "participant4"];

        participantKeys.forEach((key) => {
           const participantObject = r[key];

           if (participantObject && participantObject instanceof Participant) {
               participants.push(new SingleScheduleParticipant({
                   ...participantObject,
                   short_club_name: participantObject.club.shortClub,
                   club_id: participantObject.club.id,
               }))
           }
        });

        allRegistrations.push({
            id: r.id,
            participants: participants,
        });
    }

    return allRegistrations;
}

const isRegistrationForScheduleItem = (scheduleItem, distanceId) => {
    if (!scheduleItem || !(scheduleItem.distance) || !distanceId) {
        return false;
    }

    return scheduleItem.distance?.id === distanceId;
}

export const isScheduleItemFinished = (scheduleItem) => {
    return Boolean(
        scheduleItem.results &&
        Array.isArray(scheduleItem.results) &&
        scheduleItem.results.length > 0 &&
        scheduleItem.results.filter((r) => r.start_nr !== null && r.start_nr !== undefined && r.start_nr !== "").length >= scheduleItem.results.length
    );
}

export const moveScheduleItem = async (fromId, destId, eventId, updateTime) => {
    if (!fromId || !destId || !eventId) return null;

    const schedule = await fetchScheduleFromLocalDatabase(eventId);
    if (!schedule || schedule.error) return null;
    const scheduleData = schedule.data;

    const fromItem = scheduleData.find(e => e.id === fromId);
    const destItem = scheduleData.find(e => e.id === destId);

    if (!fromItem || !destItem) return null;

    const moveToLower = parseInt(fromItem.race_nr) > parseInt(destItem.race_nr);

    let timeDifference = 0;

    if (moveToLower) {
        const raceAfter = scheduleData.find(e => parseInt(e.race_nr) === parseInt(destItem.race_nr) + 1);
        const raceBefore = scheduleData.find(e => parseInt(e.race_nr) === parseInt(destItem.race_nr) - 1);

        if (raceAfter || raceBefore) {
            timeDifference =
                Math.abs(new Date(new Date((raceAfter ?? raceBefore).planned_start_time) - new Date(destItem.planned_start_time)).getTime());
        }
    } else {
        const raceAfter = scheduleData.find(e => parseInt(e.race_nr) === parseInt(fromItem.race_nr) + 1);
        const raceBefore = scheduleData.find(e => parseInt(e.race_nr) === parseInt(fromItem.race_nr) - 1);

        if (raceBefore || raceAfter) {
            timeDifference =
                Math.abs(new Date(new Date((raceBefore ?? raceAfter).planned_start_time) - new Date(fromItem.planned_start_time)).getTime());
        }
    }

    let moving = false;

    for (const item of scheduleData) {
        if (!moving && (
            ((moveToLower && parseInt(item.race_nr) === parseInt(destItem.race_nr))
                || (!moveToLower && parseInt(item.race_nr) === parseInt(fromItem.race_nr)))
        )) {
            moving = true;
        }

        if (!moving) {
            continue;
        }

        let itemToChange = {...item};
        itemToChange.race_nr = moveToLower ? parseInt(item.race_nr) + 1 : parseInt(item.race_nr) - 1;

        if (updateTime) {
            let newDate = new Date(itemToChange.planned_start_time);
            newDate.setTime(moveToLower ? newDate.getTime() + timeDifference : newDate.getTime() - timeDifference);
            itemToChange.planned_start_time = newDate;
        }

        await updateRaceFromScheduleFromLocalDatabase(item.id, itemToChange);

        if (moving && (
            ((moveToLower && parseInt(item.race_nr) === parseInt(fromItem.race_nr))
                || (!moveToLower && parseInt(item.race_nr) === parseInt(destItem.race_nr)))
        )) {
            moving = false;
        }
    }

    let fromItemToChange = {...fromItem};

    fromItemToChange.race_nr = destItem.race_nr;

    if (updateTime) {
        fromItemToChange.planned_start_time = destItem.planned_start_time;
    }

    await updateRaceFromScheduleFromLocalDatabase(fromItem.id, fromItemToChange);

    return fromItemToChange;
}