import {
    fetchDistancesForRegistrationsFromDatabase,
    fetchParticipantsFromDatabase,
    fetchRegistrationsFromDatabase
} from "./databasehandler";
import Participant from "../models/Participant";
import Distance from "../models/Distance";

export const fetchAllRegistrations = async (eventId) => {
    if (!eventId) {
        return null;
    }

    const registrations = await fetchRegistrationsFromDatabase(eventId);
    if (!registrations || !(registrations instanceof Array)) return null;

    const { participantIds, distanceIds } = collectIds(registrations);

    const participants = await fetchParticipantsFromDatabase(participantIds);
    if (!participants || !(participants instanceof Array)) return null;

    const distances = await fetchDistancesForRegistrationsFromDatabase(distanceIds);
    if (!distances || !(distances instanceof Array)) return null;

    const participantMap = new Map(participants.map(p => [p.id, new Participant(p.id, p.first_name, p.last_name, p.birthyear, p.info, p.club)]));
    // console.log("Participant Map", participantMap);
    const distanceMap = new Map(distances.map(d => [d.id, new Distance(d.id, d.distance, d.Gender, d.Categories, d.Boat)]));
    // console.log("Participant Map", distanceMap);


    return registrations.map(r => ({
        ...r,
        participant1: participantMap.get(r.participant_id),
        participant2: participantMap.get(r.participant_id2),
        participant3: participantMap.get(r.participant_id3),
        participant4: participantMap.get(r.participant_id4),
        distance: distanceMap.get(r.distance_id)
    }));
}

const collectIds = (registrations) => {
    const participantIds = new Set();
    const distanceIds = new Set();

    registrations.forEach(r => {
        if (r.participant_id) participantIds.add(r.participant_id);
        if (r.participant_id2) participantIds.add(r.participant_id2);
        if (r.participant_id3) participantIds.add(r.participant_id3);
        if (r.participant_id4) participantIds.add(r.participant_id4);

        if (r.distance_id) distanceIds.add(r.distance_id);
    });

    return {
        participantIds: [...participantIds],
        distanceIds: [...distanceIds]
    };
};