import {
    Table,
    TableBody,
    TableCell,
    TableHeader,
    TableHeaderCell,
    TableRow
} from "@fluentui/react-components";
import {ScheduleTableColumns} from "../../models/Schedule";
import {getParticipantString, getTitleString, getWidthForColumnForSchedule} from "./ScheduleItem";

const ScheduleItemForView = ({ scheduleItem }) => {
    return (
      <>
          <div className={`flex flex-column flex-gap-medium`}>
              <div className={`flex flex-gap-medium flex-align-center flex-wrap`}>
                  <h3>{ getTitleString(scheduleItem) }</h3>
              </div>
              <Table
                style={{tableLayout: "fixed"}} >
                  <TableHeader>
                      <TableRow>
                          {ScheduleTableColumns.filter((column) => column.columnKey !== "actions").map((column) => (
                              <TableHeaderCell
                                  key={column.columnKey}
                                  style={{ width: getWidthForColumnForSchedule(column.columnKey) }}
                              >
                                  <b>{column.label}</b>
                              </TableHeaderCell>
                          ))}
                      </TableRow>
                  </TableHeader>
                  <TableBody>
                      {
                          scheduleItem.participants.map((participant, index) => (
                              <TableRow key={index}>
                                  <TableCell>
                                      {participant.start_nr}
                                  </TableCell>
                                  <TableCell>
                                      { getParticipantString(participant.participants) }
                                  </TableCell>
                              </TableRow>
                          ))
                      }
                  </TableBody>
              </Table>
          </div>
      </>
    );
}

export default ScheduleItemForView;