import {useEffect, useState} from "react";
import {
    Button,
    Dialog, DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger, Input, Label,
    Select
} from "@fluentui/react-components";
import {Add12Regular} from "@fluentui/react-icons";
import {addDistanceToDatabase, updateDistanceFromDatabase} from "../../../handlers/databasehandler";

const ChangeRegistrationDistanceDialog = ({eventId, genderList, categoryList, boatList, selectedGender, selectedCategory, selectedBoat, usedDistances, onUpdate, distance, isNew = false, altButton}) => {
    const [distanceText, setDistanceText] = useState(isNew ? "" : distance.distance);

    const [selectedGenderId, setSelectedGenderId] = useState(null);
    const [selectedCategoryId, setSelectedCategoryId] = useState(null);
    const [selectedBoatId, setSelectedBoatId] = useState(null);

    useEffect(() => {
        if (selectedGender) {
            setSelectedGenderId(selectedGender.id);
        }
        else if (genderList.length > 0) {
            setSelectedGenderId(genderList[0].id);
        } 
    }, [genderList]);

    useEffect(() => {
        if (selectedCategory) {
            setSelectedCategoryId(selectedCategory.id);
        }
        else if (categoryList.length > 0) {
            setSelectedCategoryId(categoryList[0].id);
        }
    }, [categoryList]);

    useEffect(() => {
        if (selectedBoat) {
            setSelectedBoatId(selectedBoat.id);
        }
        else if (boatList.length > 0) {
            setSelectedBoatId(boatList[0].id);
        }
    }, [boatList]);

    async function updateDistance() {
        updateDistanceFromDatabase(eventId, distance.id, distanceText, selectedGenderId, selectedCategoryId, selectedBoatId).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    async function addDistance() {
        addDistanceToDatabase(eventId, distanceText, selectedGenderId, selectedCategoryId, selectedBoatId).then((result) => {
            if (!result) {
                console.error(result);
                return;
            }

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    return (
        <>
            <Dialog>
                <DialogTrigger>
                    { altButton ? altButton : <Button as={"a"} className={`button`} appearance={"primary"}>{ isNew ? <><Add12Regular/> Toevoegen</> : <>Wijzigen</> }</Button>}
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>{ isNew ? <>Distance Toevoegen</> : <>{distance.distance} wijzigen</>}</DialogTitle>
                    <DialogContent>
                        <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 12, marginTop: 12 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <Label style={{ width: 150 }}>Gender:</Label>
                                <Select style={{ flex: 1 }} value={selectedGenderId} onChange={(e) => setSelectedGenderId(e.target.value)}>
                                    {genderList.map((item) => (
                                        <option key={item.id} value={item.id}>{item.gender}</option>
                                    ))}
                                </Select>
                            </div>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <Label style={{ width: 150 }}>Category:</Label>
                                <Select style={{ flex: 1 }} value={selectedCategoryId} onChange={(e) => setSelectedCategoryId(e.target.value)}>
                                    {categoryList.map((item) => (
                                        <option key={item.id} value={item.id}>{item.category}</option>
                                    ))}
                                </Select>
                            </div>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <Label style={{ width: 150 }}>Boat:</Label>
                                <Select style={{ flex: 1 }} value={selectedBoatId} onChange={(e) => setSelectedBoatId(e.target.value)}>
                                    {boatList.map((item) => (
                                        <option key={item.id} value={item.id}>{item.boat}</option>
                                    ))}
                                </Select>
                            </div>
                            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                                <Label style={{ width: 150 }}>Distance:</Label>
                                <Input
                                    value={distanceText}
                                    onChange={(e) => setDistanceText(e.target.value)}
                                    style={{ flex: 1 }}/>
                            </div>
                        </div>
                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger disableButtonEnhancement>
                            <Button as={"a"} className={`button`} appearance="secondary">Annuleren</Button>
                        </DialogTrigger>
                        <DialogTrigger>
                            <Button as={"a"} className={`button`} appearance="primary" onClick={isNew ? addDistance : updateDistance}>
                                { isNew ? <>Toevoegen</> : <>Wijzigen</> }
                            </Button>
                        </DialogTrigger>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    );
}

export default ChangeRegistrationDistanceDialog;