import {
    Badge,
    Button,
    Table,
    TableBody,
    TableCell,
    TableHeader,
    TableHeaderCell,
    TableRow
} from "@fluentui/react-components";
import {ScheduleTableColumns} from "../../models/Schedule";
import {Add16Filled, Delete16Filled, Edit16Filled, ListBar16Filled, Sparkle16Filled} from "@fluentui/react-icons";
import UpdateScheduleDialog from "./UpdateScheduleDialog";
import {
    deleteRaceFromSchedule,
    getParticipantsForSchedule, isScheduleItemFinished,
    updateRaceFromSchedule
} from "../../handlers/schedulehandler";
import UpdateScheduleParticipantDialog from "./UpdateScheduleParticipantDialog";
import {useState} from "react";
import ProgressRing from "../ProgressRing";
import DeleteParticipantRowDialog from "./DeleteParticipantRowDialog";
import ScheduleParticipants from "../../models/ScheduleParticipants";
import MessageBox from "../MessageBar";
import ConfirmDialog from "../ConfirmDialog";
import {formatDateForTitle} from "../../handlers/datehandler";

const ScheduleItem = ({ scheduleItem, onUpdate, boats, genders, distances, categories, registrations }) => {
    const [isLoading, setIsLoading] = useState(false);
    const [errorMsg, setErrorMsg] = useState(null);

    let participants = scheduleItem.participants;

    function removeParticipantRow(index, updateStartNumbers = false) {
        setIsLoading(true);

        participants.splice(index, 1);

        if (updateStartNumbers) {
            updateStartNRs(index);
        }

        updateParticipantsOfSchedule({ participants: participants }).then((result) => {
            setIsLoading(false);
            if (!result) {
                setErrorMsg("Error saving schedule item");
            }

            setErrorMsg(null);

            if (onUpdate) {
                onUpdate();
            }
        });
    }

    function updateStartNRs(index) {
        participants = participants.map((participant, p_index) => {
            if (p_index < index) {
                return participant;
            }

            return new ScheduleParticipants(
                {
                    start_nr: parseInt(participant.start_nr) - 1,
                    participants: participant.participants
                }
            );
        });
    }

    async function updateParticipantsOfSchedule(participantsObject) {
        return await updateRaceFromSchedule(scheduleItem.id, participantsObject);
    }

    function deleteRace() {
        setIsLoading(true);

        deleteRaceFromSchedule(scheduleItem.id).then((result) => {
            setIsLoading(false);

            if (!result) {
                setErrorMsg("Error deleting schedule item");
                return;
            }

            setErrorMsg(null);

            if (onUpdate) {
                onUpdate();
            }
        })
    }

    return (
      <>
          <div className={`flex flex-column flex-gap-medium`}>
              {
                  errorMsg && <MessageBox title={errorMsg} intent={"error"}/>
              }
              <div className={`flex flex-gap-medium flex-align-center flex-wrap`}>
                  {
                      isLoading &&
                      <>
                          <ProgressRing/>
                      </>
                  }
                  {
                      scheduleItem.race_start_time && !isScheduleItemFinished(scheduleItem) &&
                      <>
                          <Badge appearance="filled" color="warning">
                              Started
                          </Badge>
                      </>
                  }
                  {
                      isScheduleItemFinished(scheduleItem) &&
                      <>
                          <Badge appearance="filled" color="success">
                              Finished
                          </Badge>
                      </>
                  }
                  <h3>{ getTitleString(scheduleItem) }</h3>
                  <div className={`flex flex-gap-small flex-wrap`}>
                      <UpdateScheduleDialog
                          isNew={false}
                          scheduleItem={scheduleItem}
                          onUpdate={onUpdate}
                          button={
                              <Button as={`a`} className={`button`} appearance={`subtle`}>
                                  <Edit16Filled/>
                                  Edit
                              </Button>
                          }
                          availableDistances={distances}
                          availableBoats={boats}
                          availableCategories={categories}
                          availableGenders={genders}
                      />
                      <ConfirmDialog
                          buttonText={`Delete`}
                          altButtonText={<><Delete16Filled/>Delete</>}
                          buttonColor={`red`}
                          appearance={`subtle`}
                          className={`button-delete-text`}
                          title={`Delete race`}
                          description={`Are you sure you want to delete race ${scheduleItem.race_nr}?`}
                          onConfirm={() => deleteRace()}
                            />
                  </div>
              </div>
              <Table
               style={{tableLayout: "fixed"}} >
                  <TableHeader>
                      <TableRow>
                          {ScheduleTableColumns.map((column) => (
                              <TableHeaderCell
                                  key={column.columnKey}
                                  style={{ width: getWidthForColumnForSchedule(column.columnKey) }}
                              >
                                  {column.label}
                              </TableHeaderCell>
                          ))}
                      </TableRow>
                  </TableHeader>
                  <TableBody>
                      {
                          scheduleItem.participants.map((participant, index) => (
                              <TableRow key={index}>
                                  <TableCell>
                                      {participant.start_nr}
                                  </TableCell>
                                  <TableCell>
                                      { getParticipantString(participant.participants) }
                                  </TableCell>
                                  <TableCell>
                                      <div className={`flex flex-gap-medium`}>
                                          <UpdateScheduleParticipantDialog
                                              key={`update-${participant.start_nr}-${participant.fullName}`}
                                              isNew={false}
                                              scheduleItem={scheduleItem}
                                              start_nr={participant.start_nr}
                                              scheduleItemParticipants={participant.participants}
                                              registrationsForRace={ getParticipantsForSchedule(registrations, scheduleItem) }
                                              onUpdate={onUpdate}
                                              button={
                                                  <Button as={`a`} appearance={`subtle`} size={`small`} icon={<Edit16Filled/>}/>
                                              }
                                          />
                                          <DeleteParticipantRowDialog
                                              key={`delete-${participant.start_nr}-${participant.fullName}`}
                                              onDeleteParticipantRow={() => removeParticipantRow(index)}
                                              onDeleteParticipantRowWithStartNR={() => removeParticipantRow(index, true)}
                                              button={
                                                  <Button as={`a`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>}/>
                                              }
                                          />
                                      </div>
                                  </TableCell>
                              </TableRow>
                          ))
                      }
                  </TableBody>
              </Table>
              <div>
                  <UpdateScheduleParticipantDialog
                      key={`add-${scheduleItem.participants.length}`}
                      isNew={true}
                      scheduleItem={scheduleItem}
                      registrationsForRace={ getParticipantsForSchedule(registrations, scheduleItem) }
                      onUpdate={onUpdate}
                      button={
                          <Button as={`a`} appearance={`primary`} className={`button`}>
                              <Add16Filled/> Add Participant
                          </Button>
                      } />

              </div>
          </div>
      </>
    );
}

export const getTitleString = (scheduleItem) => {
    if (!scheduleItem) {
        return ``;
    }
    return `Race ${scheduleItem.race_nr} - ${formatDateForTitle(scheduleItem.planned_start_time)} - ${scheduleItem.boat?.boat} - ${scheduleItem.gender?.gender} - ${scheduleItem.category?.category} - ${scheduleItem.distance?.distance}${scheduleItem.race_type ? ` - ${scheduleItem.race_type}` : ``}`;
}

export const getParticipantString = (participants) => {
    return participants.map(participant => participant.first_name + " " + participant.last_name + (participant.short_club_name?.length === 0 ? "" : " - " + participant.short_club_name)).join(`, `);
}

export const getWidthForColumnForSchedule = (columnKey) => {
    const column = ScheduleTableColumns.find(col => col.columnKey === columnKey);
    if (column) {
        return `${(column.span / 12) * 100}%`;
    }
    return 'auto';
};


export default ScheduleItem;