import {
    Button, Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogSurface,
    DialogTitle,
    DialogTrigger
} from "@fluentui/react-components";
import {useState} from "react";

const DeleteParticipantRowDialog = ({onDeleteParticipantRow, onDeleteParticipantRowWithStartNR, button}) => {
    const [updateStartNR, setUpdateStartNR] = useState(true);

    function handleDelete() {
        if (updateStartNR && onDeleteParticipantRowWithStartNR) {
            onDeleteParticipantRowWithStartNR();
            return;
        }

        if (onDeleteParticipantRow) {
            onDeleteParticipantRow();
        }
    }

    return (
        <>
            <Dialog>
                <DialogTrigger>
                    { button }
                </DialogTrigger>
                <DialogSurface className={`dialog`}>
                    <DialogTitle>
                        <DialogTitle>Delete Participant?</DialogTitle>
                    </DialogTitle>
                    <DialogContent>
                        <div className={`dialog-content-container`}>
                            <div className={`dialog-content-item`}>
                                <p>Are you sure you want to delete this participant from the schedule?</p>
                            </div>
                            <div className={`dialog-content-item`}>
                                <Checkbox as={`input`} checked={updateStartNR} onChange={() => setUpdateStartNR(!updateStartNR)} label={`Update Start NR`}/>
                            </div>
                        </div>

                    </DialogContent>
                    <DialogActions>
                        <DialogTrigger>
                            <Button
                                as={`a`}
                                className={`button`}
                                appearance={`subtle`}>
                                Cancel
                            </Button>
                        </DialogTrigger>
                        <DialogTrigger>
                            <Button
                                as={`a`}
                                className={`button`}
                                appearance={`primary`}
                                onClick={handleDelete}
                            >
                                Delete Participant
                            </Button>
                        </DialogTrigger>
                    </DialogActions>
                </DialogSurface>
            </Dialog>
        </>
    )
}

export default DeleteParticipantRowDialog;