import {useEffect, useState} from "react";
import {Timer16Filled} from "@fluentui/react-icons";
import {getFormatForTimeValue, getMillisecondsFormat} from "../../handlers/datehandler";

const TimeComponent = ({startTime}) => {

    const [timer, setTimer] = useState("00:00:00");

    const startDateTime = new Date(startTime);

    useEffect(() => {
        setInterval(() => {
            setTimer(getTime());
        }, 100);
    }, []);

    function getTime() {
        const diffMs = new Date() - startDateTime;

        const hours = Math.floor(diffMs / 3_600_000);
        const minutes = Math.floor((diffMs % 3_600_000) / 60_000);
        const seconds = Math.floor((diffMs % 60_000) / 1_000);
        const tenths = Math.floor((diffMs % 1_000) / 100);

        return `${getFormatForTimeValue(hours)}:${getFormatForTimeValue(minutes)}:${getFormatForTimeValue(seconds)}.${tenths}`;
    }

    return (
        <>
            <p className={`timer`}><Timer16Filled/> {timer}</p>
        </>
    );
}

export default TimeComponent;