import {Table, TableBody, TableHeader, TableHeaderCell, TableRow} from "@fluentui/react-components";

const RegistrationSettingsTable = ({ title, tableRows }) => {
    const RegSettingsTableColumns = [
        { columnKey: "title", label: title, span: 11 },
        { columnKey: "actions", label: "Actions", span: 1 },
    ]

    const getWidthForColumnForRegSettings = (columnKey) => {
        const column = RegSettingsTableColumns.find(col => col.columnKey === columnKey);
        if (column) {
            return `${(column.span / 12) * 100}%`;
        }
        return 'auto';
    };

    return (
        <Table className={`table`}>
            <TableHeader>
                <TableRow>
                    {RegSettingsTableColumns.map(column => (
                        <TableHeaderCell key={column.columnKey} style={{ width: getWidthForColumnForRegSettings(column.columnKey) }}>
                            <b>{column.label}</b>
                        </TableHeaderCell>
                    ))}
                </TableRow>
            </TableHeader>
            <TableBody>
                {tableRows}
            </TableBody>
        </Table>
    );
}

export default RegistrationSettingsTable;