import {Button, TableCell, TableRow} from "@fluentui/react-components";
import {useState} from "react";
import ProgressRing from "../../ProgressRing";
import {useParams} from "react-router-dom";
import {
    deleteBoatFromDatabase,
    fetchBoatsFromDatabase,
} from "../../../handlers/databasehandler";
import MessageBox from "../../MessageBar";
import * as React from "react";
import {Delete16Filled, Edit16Filled} from "@fluentui/react-icons";
import ChangeRegistrationBoatDialog from "./ChangeRegistrationBoatDialog";
import RegistrationSettingsTable from "../RegistrationSettingsTable";
import ConfirmDialog from "../../ConfirmDialog";
import InnerBodyContainer from "../../InnerBodyContainer";

const RegistrationBoatView = () => {
    const {id} = useParams();
    const [isLoading, setIsLoading] = useState(true);
    const [dataFetched, setDataFetched] = useState(false);
    const [boats, setBoats] = useState([]);
    const [errorMsg, setErrorMsg] = useState(null);

    async function fetchBoats() {
        return await fetchBoatsFromDatabase(id);
    }

    async function deleteBoat(boatId) {
        const result = await deleteBoatFromDatabase(id, boatId);
        if (!result) {
            setErrorMsg("Error deleting category.");
            return;
        }

        fetchBoatsAfterOperation();
    }

    function fetchBoatsAfterOperation() {
        fetchBoats().then((data) => setBoats(data));
    }

    if (!dataFetched) {
        setDataFetched(true);
        fetchBoats().then((data) => {
            setIsLoading(false);

            if (data == null) {
                setErrorMsg("Error loading genders");
                return;
            }

            setBoats(data);
        });
    }

    return (
        <InnerBodyContainer content={
            <>
                { isLoading && <ProgressRing/>}
                { !isLoading && errorMsg != null &&
                    <MessageBox
                        intent={"error"}
                        title={"An error occurred:"}
                        message={errorMsg}
                        closeButtonFunction={() => { setErrorMsg(null) }}
                    />
                }
                { !isLoading && errorMsg == null &&
                    <>
                        <RegistrationSettingsTable title={`Boats`} tableRows={
                            boats.map((boat, index) => (
                                <TableRow key={`${boat.id}-${index}`}>
                                    <TableCell>{boat.boat} ({boat.amount_of_people})</TableCell>
                                    <TableCell>
                                        <div className={`flex flex-gap-medium`}>
                                            <ChangeRegistrationBoatDialog
                                                eventId={id}
                                                boat={boat}
                                                onUpdate={() => fetchBoatsAfterOperation()}
                                                altButton={
                                                    <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Edit16Filled/>}/>
                                                }
                                            />
                                            <ConfirmDialog
                                                title={"Item verwijderen?"}
                                                description={`Weet u zeker dat '${boat.boat}' moet worden verwijderd? Deze actie kan niet ongedaan worden gemaakt`}
                                                buttonText={"Verwijderen"}
                                                onConfirm={() => deleteBoat(boat.id)}
                                                buttonColor={"red"}
                                                appearance={`subtle`}
                                                buttonSize={`small`}
                                                altButton={
                                                    <Button as={`a`} className={`button`} appearance={`subtle`} size={`small`} icon={<Delete16Filled/>}/>
                                                }                                            />
                                        </div>
                                    </TableCell>
                                </TableRow>
                            ))
                        }/>
                    </>
                }
                <div style={{display: "flex"}}>
                    <ChangeRegistrationBoatDialog
                        isNew={true}
                        eventId={id}
                        onUpdate={() => fetchBoatsAfterOperation()}
                    />
                </div>
            </>
        }></InnerBodyContainer>
    );
}

export default RegistrationBoatView;