import html2pdf from "html2pdf.js";
import {formatDateForTitle} from "./datehandler";

// ─── Shared html2pdf options ──────────────────────────────────────────────────

const BASE_PDF_OPTIONS = {
    margin:      [12, 12, 12, 12],
    format:      "a4",
    orientation: "portrait",
    image:       { type: "jpeg", quality: 2 },
    html2canvas: { scale: 1, useCORS: true, logging: false },
    pagebreak:   { mode: ["avoid-all", "css"] },
};

const PDF_MODES = {
    detailed: "detailed",
    titles: "titles",
};

// ─── Data helpers ─────────────────────────────────────────────────────────────

function getTitleString(scheduleItem) {
    if (!scheduleItem) {
        return ``;
    }
    return `Race ${scheduleItem.race_nr} - ${formatDateForTitle(scheduleItem.planned_start_time)} - ${scheduleItem.boat?.boat} - ${scheduleItem.gender?.gender} - ${scheduleItem.category?.category} - ${scheduleItem.distance?.distance}${scheduleItem.race_type ? ` - ${scheduleItem.race_type}` : ``}`;
}

function getParticipantString(participants) {
    if (!Array.isArray(participants) || participants.length === 0) {
        return "-";
    }
    return participants.map(participant => participant.first_name + " " + participant.last_name + (participant.short_club_name?.length === 0 ? "" : " - " + participant.short_club_name)).join(`, `);
}

function isValidDate(dateValue) {
    if (!dateValue) {
        return false;
    }

    const parsed = new Date(dateValue);
    return !Number.isNaN(parsed.getTime());
}

function padTimeValue(value) {
    return value.toString().padStart(2, "0");
}

function formatElapsedTime(raceStartTime, finishTime) {
    if (!isValidDate(finishTime)) {
        return "-";
    }

    if (!isValidDate(raceStartTime)) {
        const finishDate = new Date(finishTime);

        return `${padTimeValue(finishDate.getHours())}:${padTimeValue(finishDate.getMinutes())}:${padTimeValue(finishDate.getSeconds())}.${finishDate.getMilliseconds().toString().padStart(3, "0")}`;
    }

    const diffMs = new Date(finishTime).getTime() - new Date(raceStartTime).getTime();

    if (Number.isNaN(diffMs) || diffMs < 0) {
        return "-";
    }

    const hours = Math.floor(diffMs / 3_600_000);
    const minutes = Math.floor((diffMs % 3_600_000) / 60_000);
    const seconds = Math.floor((diffMs % 60_000) / 1_000);
    const milliseconds = diffMs % 1_000;

    return `${padTimeValue(hours)}:${padTimeValue(minutes)}:${padTimeValue(seconds)}.${milliseconds.toString().padStart(3, "0")}`;
}

function getParticipantsByStartNr(scheduleItem) {
    const participantMap = new Map();

    (scheduleItem.participants || []).forEach((lane) => {
        if (lane?.start_nr === undefined || lane?.start_nr === null) {
            return;
        }

        participantMap.set(String(lane.start_nr), lane.participants || []);
    });

    return participantMap;
}

function getDetailedTableConfig(scheduleItem) {
    const results = Array.isArray(scheduleItem.results) ? scheduleItem.results : [];

    if (results.length > 0) {
        const participantsByStartNr = getParticipantsByStartNr(scheduleItem);

        return {
            headers: [
                { key: "rank", label: "Uitslag", width: "80px" },
                { key: "time", label: "Tijd", width: "110px" },
                { key: "participants", label: "Deelnemer(s)", width: "auto" },
            ],
            rows: results.map((result, index) => {
                const isOrderText = Number.isNaN(Number(result.order));
                return {
                    // Follow race overview behavior: visible result number is row index + 1.
                    rank: index + 1,
                    participants: getParticipantString(participantsByStartNr.get(String(result.start_nr)) || []),
                    // For DNS/DNF/DQ rows, show that label in the time column.
                    time: isOrderText ? (result.order ?? "") : formatElapsedTime(scheduleItem.race_start_time, result.finish_time),
                };
            }),
        };
    }

    const participantRows = Array.isArray(scheduleItem.participants) ? scheduleItem.participants : [];

    return {
        headers: [
            { key: "startNr", label: "Start nr.", width: "80px" },
            { key: "participants", label: "Deelnemer(s)", width: "auto" },
        ],
        rows: participantRows.map((lane) => ({
            startNr: lane.start_nr ?? "",
            participants: getParticipantString(lane.participants),
        })),
    };
}

function appendTableCell(row, text, { isHeader = false, width = null } = {}) {
    const cell = document.createElement(isHeader ? "th" : "td");

    cell.style.cssText = `
        border-bottom: 1px solid #ccc;
        padding: 4px 8px;
        text-align: left;
        font-size: 11px;
        vertical-align: top;
        ${isHeader ? "background: #f0f0f0; font-weight: bold;" : ""}
        ${width ? `width: ${width};` : ""}
    `;
    cell.textContent = text ?? "";

    row.appendChild(cell);
}

function buildDetailedTable(scheduleItem) {
    const { headers, rows } = getDetailedTableConfig(scheduleItem);
    const table = document.createElement("table");

    table.style.cssText = `
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
    `;

    const thead = document.createElement("thead");
    const headerRow = document.createElement("tr");

    headers.forEach(({ label, width }) => {
        appendTableCell(headerRow, label, { isHeader: true, width });
    });

    thead.appendChild(headerRow);
    table.appendChild(thead);

    const tbody = document.createElement("tbody");

    if (rows.length === 0) {
        const emptyRow = document.createElement("tr");
        const emptyCell = document.createElement("td");

        emptyCell.colSpan = headers.length;
        emptyCell.style.cssText = `
            border-bottom: 1px solid #ccc;
            padding: 4px 8px;
            font-size: 11px;
            color: #666;
        `;
        emptyCell.textContent = "Geen deelnemers of uitslagen";
        emptyRow.appendChild(emptyCell);
        tbody.appendChild(emptyRow);
    } else {
        rows.forEach((rowData) => {
            const row = document.createElement("tr");

            headers.forEach(({ key }) => {
                appendTableCell(row, rowData[key]);
            });

            tbody.appendChild(row);
        });
    }

    table.appendChild(tbody);

    return table;
}

// ─── DOM builder ─────────────────────────────────────────────────────────────

function buildScheduleHtmlContainer(scheduleData, mode) {
    const titleOnly = mode === PDF_MODES.titles;
    const container = document.createElement("div");
    // No opacity/visibility tricks — html2canvas cannot capture invisible elements.
    // The container is appended to body and removed immediately after PDF generation.
    container.style.cssText = `
        width: 675px;
        background: #fff;
        font-family: Arial, sans-serif;
        font-size: 12px;
        color: #000;
        box-sizing: border-box;
    `;

    scheduleData.forEach((scheduleItem) => {
        const block = document.createElement("div");
        block.style.cssText = `
            margin-bottom: ${titleOnly ? "6px" : "20px"};
            break-inside:      avoid;
            page-break-inside: avoid;
        `;

        // Title: glued to first table row so neither gets orphaned at a page edge.
        const title = document.createElement("div");
        title.style.cssText = `
            font-size: ${titleOnly ? "13px" : "14px"};
            font-weight: bold;
            padding-bottom: 3px;
            margin-bottom: ${titleOnly ? "0" : "6px"};
            line-height: 1.25;
            break-inside:      avoid;
            page-break-inside: avoid;
            break-after:       avoid;
            page-break-after:  avoid;
        `;
        title.textContent = getTitleString(scheduleItem);
        block.appendChild(title);

        if (mode === PDF_MODES.titles) {
            const hr = document.createElement("hr");
            block.appendChild(hr);
        }

        if (!titleOnly) {
            block.appendChild(buildDetailedTable(scheduleItem));
        }

        container.appendChild(block);
    });

    document.body.appendChild(container);


    return container;
}

// ─── Public API ───────────────────────────────────────────────────────────────

async function generateSchedulePdf(scheduleData, { filename, mode, warningContext }) {
    if (!scheduleData?.length) {
        console.warn(`${warningContext}: no schedule data provided`);
        return;
    }

    const container = buildScheduleHtmlContainer(scheduleData, mode);

    try {
        await html2pdf()
            .set({ ...BASE_PDF_OPTIONS, filename })
            .from(container)
            .save();
    } finally {
        if (document.body.contains(container)) {
            document.body.removeChild(container);
        }
    }
}

/**
 * Generates a simple detailed PDF overview.
 * If a race has results, the PDF shows result rows + times.
 * Otherwise, it shows start numbers with participants.
 *
 * @param {Array} scheduleData
 * @returns {Promise<void>}
 */
export async function generateScheduleDetailedPdf(scheduleData) {
    await generateSchedulePdf(scheduleData, {
        filename: "schedule_detailed.pdf",
        mode: PDF_MODES.detailed,
        warningContext: "generateScheduleDetailedPdf",
    });
}

/**
 * Generates a title-only PDF: one title per race, without participant data.
 *
 * @param {Array} scheduleData
 * @returns {Promise<void>}
 */
export async function generateScheduleTitleOverviewPdf(scheduleData) {
    await generateSchedulePdf(scheduleData, {
        filename: "schedule_titles.pdf",
        mode: PDF_MODES.titles,
        warningContext: "generateScheduleTitleOverviewPdf",
    });
}